static void world_lighting_config_defaults(WorldLightingConfig *cfg){
    if(!cfg) return;
    memset(cfg,0,sizeof(*cfg));
    cfg->override_active=false;
    cfg->sun_yaw_deg=-120.0f;
    cfg->sun_pitch_deg=48.0f;
    cfg->sun_color=(Vec3){1.45f,1.22f,0.82f};
    cfg->ambient=(Vec3){0.22f,0.25f,0.34f};
}

static void world_lighting_config_save(const WorldLightingConfig *cfg){
    FILE *f;
    if(!cfg) return;
    f=fopen(WORLD_LIGHTING_FILE,"w");
    if(!f) return;
    fprintf(f,"override=%d\n",cfg->override_active?1:0);
    fprintf(f,"sun_yaw=%.3f\n",(double)cfg->sun_yaw_deg);
    fprintf(f,"sun_pitch=%.3f\n",(double)cfg->sun_pitch_deg);
    fprintf(f,"sun_color=%.4f %.4f %.4f\n",(double)cfg->sun_color.x,(double)cfg->sun_color.y,(double)cfg->sun_color.z);
    fprintf(f,"ambient=%.4f %.4f %.4f\n",(double)cfg->ambient.x,(double)cfg->ambient.y,(double)cfg->ambient.z);
    fclose(f);
}

static void world_lighting_config_load(WorldLightingConfig *cfg){
    FILE *f;
    char line[256];
    if(!cfg) return;
    world_lighting_config_defaults(cfg);
    f=fopen(WORLD_LIGHTING_FILE,"r");
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        char *eq;
        char *key;
        char *value;
        if(line[0]=='#') continue;
        {
            size_t len=strlen(line);
            while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;
        }
        key=line;
        while(*key&&isspace((unsigned char)*key)) key++;
        if(!*key) continue;
        {
            char *end=key+strlen(key);
            while(end>key&&isspace((unsigned char)end[-1])) *--end=0;
        }
        eq=strchr(key,'=');
        if(!eq) continue;
        *eq++=0;
        value=eq;
        while(*value&&isspace((unsigned char)*value)) value++;
        {
            char *end=value+strlen(value);
            while(end>value&&isspace((unsigned char)end[-1])) *--end=0;
        }
        if(strcmp(key,"override")==0) cfg->override_active=(atoi(value)!=0);
        else if(strcmp(key,"sun_yaw")==0) cfg->sun_yaw_deg=(float)atof(value);
        else if(strcmp(key,"sun_pitch")==0) cfg->sun_pitch_deg=(float)atof(value);
        else if(strcmp(key,"sun_color")==0) sscanf(value,"%f %f %f",&cfg->sun_color.x,&cfg->sun_color.y,&cfg->sun_color.z);
        else if(strcmp(key,"ambient")==0) sscanf(value,"%f %f %f",&cfg->ambient.x,&cfg->ambient.y,&cfg->ambient.z);
    }
    fclose(f);
}

static void world_lighting_apply_override(LightingSystem *ls,const WorldLightingConfig *cfg){
    float yaw_r,pitch_r,cp;
    if(!ls||!cfg||!cfg->override_active) return;
    yaw_r=cfg->sun_yaw_deg*(float)M_PI/180.0f;
    pitch_r=cfg->sun_pitch_deg*(float)M_PI/180.0f;
    cp=cosf(pitch_r);
    ls->sun_dir=vec3_norm((Vec3){
        cosf(yaw_r)*cp,
        -sinf(pitch_r),
        sinf(yaw_r)*cp
    });
    ls->sun_color=cfg->sun_color;
    ls->ambient=cfg->ambient;
    ls->sun_elev=-ls->sun_dir.y;
}
