static void world_flags_save(void){
    FILE *f=fopen(WORLD_FLAGS_FILE,"w");
    if(!f) return;
    for(int i=0;i<WORLD_FLAG_MAX;i++) if(g_world_flags[i]) fprintf(f,"%d 1\n",i);
    fclose(f);
}

static void world_flags_load(void){
    FILE *f=fopen(WORLD_FLAGS_FILE,"r");
    char line[256];
    memset(g_world_flags,0,sizeof(g_world_flags));
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        int idx=0,val=0;
        if(line[0]=='#') continue;
        if(sscanf(line,"%d %d",&idx,&val)>=1&&idx>=0&&idx<WORLD_FLAG_MAX)
            g_world_flags[idx]=(val!=0);
    }
    fclose(f);
}

static bool world_flag_get(int idx){
    if(idx<0||idx>=WORLD_FLAG_MAX) return false;
    return g_world_flags[idx];
}

static void world_flag_set(int idx,bool value){
    if(idx<0||idx>=WORLD_FLAG_MAX) return;
    if(g_world_flags[idx]==value) return;
    g_world_flags[idx]=value;
    world_flags_save();
}

static uint8_t *rgba_downsample_half(const uint8_t *src,int w,int h){
    int nw=(w>1)?(w/2):1;
    int nh=(h>1)?(h/2):1;
    uint8_t *dst=(uint8_t*)malloc((size_t)nw*(size_t)nh*4u);
    if(!dst) return NULL;
    for(int y=0;y<nh;y++){
        for(int x=0;x<nw;x++){
            int sx=x*2, sy=y*2;
            int sx1=(sx+1<w)?sx+1:sx;
            int sy1=(sy+1<h)?sy+1:sy;
            const uint8_t *p00=src+((size_t)sy*(size_t)w+(size_t)sx )*4u;
            const uint8_t *p10=src+((size_t)sy*(size_t)w+(size_t)sx1)*4u;
            const uint8_t *p01=src+((size_t)sy1*(size_t)w+(size_t)sx )*4u;
            const uint8_t *p11=src+((size_t)sy1*(size_t)w+(size_t)sx1)*4u;
            uint8_t *d=dst+((size_t)y*(size_t)nw+(size_t)x)*4u;
            for(int c=0;c<4;c++) d[c]=(uint8_t)(((int)p00[c]+(int)p10[c]+(int)p01[c]+(int)p11[c])/4);
        }
    }
    return dst;
}

static GLuint GLH_texture_rgba_srgb_streamed(const uint8_t *px,int w,int h){
    const int max_dim=2048;
    const uint8_t *upload_px=px;
    uint8_t *owned=NULL;
    int up_w=w, up_h=h;
    if(!px||w<=0||h<=0) return 0;
    while(up_w>max_dim||up_h>max_dim){
        uint8_t *next=rgba_downsample_half(upload_px,up_w,up_h);
        if(owned) free(owned);
        if(!next) break;
        owned=next;
        upload_px=owned;
        up_w=(up_w>1)?(up_w/2):1;
        up_h=(up_h>1)?(up_h/2):1;
    }
    {
        GLuint id=0;
        glGenTextures(1,&id);
        glBindTexture(GL_TEXTURE_2D,id);
        glTexImage2D(GL_TEXTURE_2D,0,GL_SRGB8_ALPHA8,up_w,up_h,0,GL_RGBA,GL_UNSIGNED_BYTE,upload_px);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_BASE_LEVEL,0);
        glGenerateMipmap(GL_TEXTURE_2D);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
        if(owned) free(owned);
        return id;
    }
}

/* Upload pre-decoded albedo pixels as sRGB so models shade correctly */
static GLuint GLH_texture_rgba_srgb(void *px,int w,int h){
    if(!px||w<=0||h<=0)return 0;
    GLuint id=0;glGenTextures(1,&id);glBindTexture(GL_TEXTURE_2D,id);
    glTexImage2D(GL_TEXTURE_2D,0,GL_SRGB8_ALPHA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,px);
    glGenerateMipmap(GL_TEXTURE_2D);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
    return id;
}

static GLuint GLH_texture_file_srgb_streamed(const char *path){
    int w=0,h=0,ch=0;
    uint8_t *px=stbi_load(path,&w,&h,&ch,4);
    GLuint id=0;
    if(!px) return 0;
    id=GLH_texture_rgba_srgb_streamed(px,w,h);
    stbi_image_free(px);
    return id;
}

