/* ── Water Zone System ──────────────────────────────────────────
   Up to 8 independent water bodies, each with its own style.
   Outside all zones the global g_wstyle (Deep Ocean) applies.
   Zones blend smoothly at their edges (10% falloff band).
   Edit in-game with F2.                                         */
#define WZONE_SAVE_FILE  "water_zones.txt"

typedef struct {
    float cx,cz;       /* world-space centre            */
    float radius;      /* influence radius               */
    float level;       /* water surface Y (world units) */
    int   preset_idx;  /* WaterStyleDef index            */
    bool  active;
} WaterZone;

static WaterZone g_wzones[MAX_WATER_ZONES];
static int       g_wzone_count=0;
/* scene depth + color textures passed from pfx each frame for depth-buffer water */
static GLuint    g_scene_depth_tex=0;
static GLuint    g_scene_color_tex=0;
static GLuint    g_scene_depth_copy_tex=0;
static int       g_scene_depth_copy_w=0;
static int       g_scene_depth_copy_h=0;

static void wzone_save(void){
    FILE *f=fopen(WZONE_SAVE_FILE,"w");
    if(!f)return;
    fprintf(f,"# Water zones — %d entries\n",g_wzone_count);
    for(int i=0;i<g_wzone_count;i++){
        WaterZone *z=&g_wzones[i];
        if(!z->active)continue;
        fprintf(f,"%.1f %.1f %.1f %d %.2f\n",
                (double)z->cx,(double)z->cz,
                (double)z->radius,z->preset_idx,
                (double)z->level);
    }
    fclose(f);
    printf("[WZone] Saved %d zones to %s\n",g_wzone_count,WZONE_SAVE_FILE);
}

static void wzone_load(void){
    FILE *f=fopen(WZONE_SAVE_FILE,"r");
    if(!f)return;
    g_wzone_count=0;
    char line[64];
    while(fgets(line,sizeof(line),f)&&g_wzone_count<MAX_WATER_ZONES){
        if(line[0]=='#')continue;
        float cx,cz,rad,lv=WATER_LEVEL; int pi;
        int nf=sscanf(line,"%f %f %f %d %f",&cx,&cz,&rad,&pi,&lv);
        if(nf>=4){
            WaterZone *z=&g_wzones[g_wzone_count++];
            z->cx=cx;z->cz=cz;z->radius=rad;
            z->preset_idx=pi>=0&&pi<WATER_PRESET_COUNT?pi:0;
            z->level=(nf>=5)?lv:WATER_LEVEL;  /* backward compat */
            z->active=true;
        }
    }
    fclose(f);
    printf("[WZone] Loaded %d zones from %s\n",g_wzone_count,WZONE_SAVE_FILE);
}

/* ── wzone_local_level: returns water surface Y at world XZ ──
   Checks all zones sorted by proximity weight. Returns the level
   of the dominant zone, or WATER_LEVEL if outside all zones.    */
static float wzone_local_level(float wx, float wz){
    float best_t = 0.0f;
    float best_level = WATER_LEVEL;
    for(int zi=0;zi<g_wzone_count;zi++){
        WaterZone *z=&g_wzones[zi];
        if(!z->active)continue;
        float dx=wx-z->cx, dz2=wz-z->cz;
        float d=sqrtf(dx*dx+dz2*dz2);
        if(d>=z->radius)continue;
        float t=clampf(1.0f-(d/z->radius),0.0f,1.0f);
        t=t*t*(3.0f-2.0f*t); /* smoothstep */
        if(t>best_t){ best_t=t; best_level=z->level; }
    }
    return best_level;
}

static float wzone_shore_radius_at_angle(const WaterZone *z,float angle){
    float dirx,dirz,r,max_r,step,last_wet_r;
    if(!z) return 1.0f;
    dirx=cosf(angle);
    dirz=sinf(angle);
    max_r=z->radius*1.10f;
    step=fmaxf(z->radius/28.0f,1.0f);
    last_wet_r=z->radius;
    for(r=step;r<=max_r;r+=step){
        float wx=z->cx+dirx*r;
        float wz=z->cz+dirz*r;
        float th=terrain_h(wx,wz);
        if(th<=z->level+0.06f){
            last_wet_r=r;
        }else if(th>z->level+0.18f){
            return fminf(last_wet_r,z->radius*1.05f);
        }
    }
    return fminf(last_wet_r,z->radius*1.05f);
}

static float wzone_smoothed_shore_radius_at_angle(const WaterZone *z,float angle){
    const float delta=0.085f;
    float r0,r1,r2,r3,r4;
    if(!z) return 1.0f;
    r0=wzone_shore_radius_at_angle(z,angle-delta*2.0f);
    r1=wzone_shore_radius_at_angle(z,angle-delta);
    r2=wzone_shore_radius_at_angle(z,angle);
    r3=wzone_shore_radius_at_angle(z,angle+delta);
    r4=wzone_shore_radius_at_angle(z,angle+delta*2.0f);
    return r0*0.10f+r1*0.22f+r2*0.36f+r3*0.22f+r4*0.10f;
}

/* ── End water zone system ───────────────────────────────────── */

/* ── wzone_rebuild_vaos: (re)build per-zone elevated water quads ──
   Called after any zone add/remove/resize/level-change.
   Zones at WATER_LEVEL don't need their own quad — the global ocean
   plane already covers them.  Zones at any other level get a quad
   centred at (cx, level+0.03, cz) spanning radius*1.15 in XZ.         */
static void wzone_rebuild_vaos(Terrain *t){
    /* Free any existing zone VAOs */
    for(int i=0;i<MAX_WATER_ZONES;i++){
        if(t->zone_vaos[i]){ billboard_mesh_free(t->zone_vaos[i]); t->zone_vaos[i]=0; }
        t->zone_ic[i]=0;
    }
    GLH_Attrib wa[]={{0,3,GL_FLOAT,GL_FALSE,0},{1,3,GL_FLOAT,GL_FALSE,12},{2,3,GL_FLOAT,GL_FALSE,24}};
    for(int zi=0;zi<g_wzone_count&&zi<MAX_WATER_ZONES;zi++){
        WaterZone *z=&g_wzones[zi];
        if(!z->active)continue;
        const float y=z->level+0.07f;
        const float extent=z->radius*1.08f;
        const int res=96;
        const int cols=res+1;
        const int rows=res+1;
        const int vcount=cols*rows;
        const int icap=res*res*6;
        float *verts=(float*)malloc((size_t)vcount*9u*sizeof(float));
        uint32_t *idx=(uint32_t*)malloc((size_t)icap*sizeof(uint32_t));
        if(!verts||!idx){
            free(verts);
            free(idx);
            continue;
        }
        {
            const float step=(extent*2.0f)/(float)res;
            for(int rz=0;rz<rows;rz++){
                for(int rx=0;rx<cols;rx++){
                    float lx=-extent + (float)rx*step;
                    float lz=-extent + (float)rz*step;
                    float wx=z->cx+lx;
                    float wz=z->cz+lz;
                    float dist=sqrtf(lx*lx+lz*lz);
                    float angle=atan2f(lz,lx);
                    float shore_r=wzone_smoothed_shore_radius_at_angle(z,angle);
                    float shore_band=fmaxf(z->radius*0.06f,1.5f);
                    float terrain=terrain_h(wx,wz);
                    float radial=1.0f-clampf((dist-shore_r)/shore_band,0.0f,1.0f);
                    float wet=clampf(fmaxf(z->level-terrain,0.0f)/0.22f,0.0f,1.0f);
                    wet=wet*wet*(3.0f-2.0f*wet);
                    if(dist>shore_r+shore_band) wet=0.0f;
                    float alpha=radial*wet;
                    int vi=(rz*cols+rx)*9;
                    verts[vi+0]=wx;
                    verts[vi+1]=y;
                    verts[vi+2]=wz;
                    verts[vi+3]=0.0f;
                    verts[vi+4]=0.0f;
                    verts[vi+5]=0.0f;
                    verts[vi+6]=alpha;
                    verts[vi+7]=clampf(dist/fmaxf(z->radius,1.0f),0.0f,1.0f);
                    verts[vi+8]=0.0f;
                }
            }
            {
                int ii=0;
                for(int rz=0;rz<res;rz++){
                    for(int rx=0;rx<res;rx++){
                        uint32_t a=(uint32_t)(rz*cols+rx);
                        uint32_t b=a+1u;
                        uint32_t c=a+(uint32_t)cols;
                        uint32_t d=c+1u;
                        float aa=verts[a*9u+6];
                        float ba=verts[b*9u+6];
                        float ca=verts[c*9u+6];
                        float da=verts[d*9u+6];
                        if((aa+ca+ba) > 0.54f){
                            idx[ii++]=a; idx[ii++]=c; idx[ii++]=b;
                        }
                        if((ba+ca+da) > 0.54f){
                            idx[ii++]=b; idx[ii++]=c; idx[ii++]=d;
                        }
                    }
                }
                t->zone_ic[zi]=ii;
            }
        }
        if(t->zone_ic[zi]<=0){
            free(verts);
            free(idx);
            continue;
        }
        t->zone_vaos[zi]=GLH_mesh(verts,(size_t)vcount*9u*sizeof(float),idx,(size_t)t->zone_ic[zi]*sizeof(uint32_t),
                                  9*sizeof(float),wa,3);
        free(verts);
        free(idx);
    }
}

