#include "engine/scene.inc"

static const char *player_character_slot_key(int slot){
    static const char *keys[PLAYER_CHAR_SLOT_COUNT]={
        "idle","walk","run","attack","attack2","jump","death","roll","block","hit"
    };
    if(slot<0||slot>=PLAYER_CHAR_SLOT_COUNT) return "idle";
    return keys[slot];
}

static const char *player_character_slot_label(int slot){
    static const char *labels[PLAYER_CHAR_SLOT_COUNT]={
        "Idle","Walk","Run","Attack","Attack 2","Jump","Death","Roll","Block","Hit"
    };
    if(slot<0||slot>=PLAYER_CHAR_SLOT_COUNT) return "Idle";
    return labels[slot];
}

static int player_character_model_path_cmp(const void *a,const void *b){
    const char (*pa)[256]=(const char (*)[256])a;
    const char (*pb)[256]=(const char (*)[256])b;
    return strcmp(*pa,*pb);
}

static void player_character_model_name_from_path(const char *path,char *out,size_t out_sz){
    const char *base,*dot;
    size_t len;
    if(!out||out_sz==0) return;
    out[0]=0;
    if(!path||!path[0]) return;
    base=strrchr(path,'/');
    base=base?base+1:path;
    dot=strrchr(base,'.');
    len=dot&&dot>base?(size_t)(dot-base):strlen(base);
    if(len>=out_sz) len=out_sz-1;
    memcpy(out,base,len);
    out[len]=0;
}

static int player_character_sound_path_cmp(const void *a,const void *b){
    const char (*pa)[256]=(const char (*)[256])a;
    const char (*pb)[256]=(const char (*)[256])b;
    return strcmp(*pa,*pb);
}

static int sound_zone_music_path_cmp(const void *a,const void *b){
    const char (*pa)[256]=(const char (*)[256])a;
    const char (*pb)[256]=(const char (*)[256])b;
    return strcmp(*pa,*pb);
}

static void player_character_model_registry_build(void){
    DIR *dir=opendir("models/main_characters");
    struct dirent *ent;
    g_player_char_model_option_count=0;
    memset(g_player_char_model_paths,0,sizeof(g_player_char_model_paths));
    memset(g_player_char_model_names,0,sizeof(g_player_char_model_names));
    if(dir){
        while((ent=readdir(dir))!=NULL&&g_player_char_model_option_count<PLAYER_CHARACTER_MODEL_OPTION_MAX){
            const char *ext;
            if(ent->d_name[0]=='.') continue;
            ext=strrchr(ent->d_name,'.');
            if(!ext) continue;
            if(strcasecmp(ext,".fbx")!=0&&strcasecmp(ext,".glb")!=0&&strcasecmp(ext,".gltf")!=0) continue;
            snprintf(g_player_char_model_paths[g_player_char_model_option_count],
                     sizeof(g_player_char_model_paths[g_player_char_model_option_count]),
                     "models/main_characters/%s",ent->d_name);
            g_player_char_model_option_count++;
        }
        closedir(dir);
    }
    if(g_player_char_model_option_count>1){
        qsort(g_player_char_model_paths,(size_t)g_player_char_model_option_count,
              sizeof(g_player_char_model_paths[0]),player_character_model_path_cmp);
    }
    for(int i=0;i<g_player_char_model_option_count;i++){
        player_character_model_name_from_path(g_player_char_model_paths[i],
                                              g_player_char_model_names[i],
                                              sizeof(g_player_char_model_names[i]));
        if(!g_player_char_model_names[i][0]){
            snprintf(g_player_char_model_names[i],sizeof(g_player_char_model_names[i]),"Character %d",i+1);
        }
    }
}

static void player_character_sound_registry_build(void){
    DIR *dir=opendir("sound_effects");
    struct dirent *ent;
    g_player_char_sound_option_count=0;
    memset(g_player_char_sound_paths,0,sizeof(g_player_char_sound_paths));
    memset(g_player_char_sound_names,0,sizeof(g_player_char_sound_names));
    if(!dir) return;
    while((ent=readdir(dir))!=NULL&&g_player_char_sound_option_count<PLAYER_CHARACTER_SOUND_OPTION_MAX){
        const char *ext;
        if(ent->d_name[0]=='.') continue;
        ext=strrchr(ent->d_name,'.');
        if(!ext) continue;
        if(strcasecmp(ext,".wav")!=0&&strcasecmp(ext,".mp3")!=0&&strcasecmp(ext,".ogg")!=0) continue;
        snprintf(g_player_char_sound_paths[g_player_char_sound_option_count],
                 sizeof(g_player_char_sound_paths[g_player_char_sound_option_count]),
                 "sound_effects/%s",ent->d_name);
        g_player_char_sound_option_count++;
    }
    closedir(dir);
    if(g_player_char_sound_option_count>1){
        qsort(g_player_char_sound_paths,(size_t)g_player_char_sound_option_count,
              sizeof(g_player_char_sound_paths[0]),player_character_sound_path_cmp);
    }
    for(int i=0;i<g_player_char_sound_option_count;i++){
        player_character_model_name_from_path(g_player_char_sound_paths[i],
                                              g_player_char_sound_names[i],
                                              sizeof(g_player_char_sound_names[i]));
        if(!g_player_char_sound_names[i][0]){
            snprintf(g_player_char_sound_names[i],sizeof(g_player_char_sound_names[i]),"Sound %d",i+1);
        }
    }
}

