static void player_character_config_defaults(PlayerCharacterConfig *cfg){
    if(!cfg) return;
    memset(cfg,0,sizeof(*cfg));
    strncpy(cfg->name,"Main Guy",sizeof(cfg->name)-1);
    strncpy(cfg->model_path,"models/main_guy.glb",sizeof(cfg->model_path)-1);
    cfg->scale=1.0f;
}

static void player_character_library_defaults(void){
    memset(&g_player_char_library,0,sizeof(g_player_char_library));
    memset(g_player_char_presets,0,sizeof(g_player_char_presets));
    g_player_char_library.count=1;
    g_player_char_library.active_index=0;
    g_player_char_editor_index=0;
    player_character_config_defaults(&g_player_char_presets[0]);
}

static PlayerCharacterConfig *player_character_active_preset(void){
    if(g_player_char_library.count<=0) return NULL;
    if(g_player_char_library.active_index<0||g_player_char_library.active_index>=g_player_char_library.count)
        g_player_char_library.active_index=0;
    return &g_player_char_presets[g_player_char_library.active_index];
}

static PlayerCharacterConfig *player_character_selected_preset(void){
    if(g_player_char_library.count<=0) return NULL;
    if(g_player_char_editor_index<0||g_player_char_editor_index>=g_player_char_library.count)
        g_player_char_editor_index=g_player_char_library.active_index;
    if(g_player_char_editor_index<0||g_player_char_editor_index>=g_player_char_library.count)
        g_player_char_editor_index=0;
    return &g_player_char_presets[g_player_char_editor_index];
}

static void player_character_config_trim_line(char *text){
    int len;
    if(!text) return;
    len=(int)strlen(text);
    while(len>0&&(text[len-1]=='\n'||text[len-1]=='\r')) text[--len]=0;
}

static bool player_character_legacy_load(PlayerCharacterConfig *cfg,const char *path){
    FILE *f;
    char line[512];
    if(!cfg) return false;
    player_character_config_defaults(cfg);
    f=fopen(path,"r");
    if(!f) return false;
    while(fgets(line,sizeof(line),f)){
        char *eq=strchr(line,'=');
        if(!eq) continue;
        *eq=0;
        char *key=line;
        char *value=eq+1;
        player_character_config_trim_line(value);
        if(strcmp(key,"model")==0){
            strncpy(cfg->model_path,value,sizeof(cfg->model_path)-1);
            cfg->model_path[sizeof(cfg->model_path)-1]=0;
            continue;
        }
        for(int slot=0;slot<PLAYER_CHAR_SLOT_COUNT;slot++){
            char expect[32];
            snprintf(expect,sizeof(expect),"anim_%s",player_character_slot_key(slot));
            if(strcmp(key,expect)==0){
                strncpy(cfg->anim_override[slot],value,sizeof(cfg->anim_override[slot])-1);
                cfg->anim_override[slot][sizeof(cfg->anim_override[slot])-1]=0;
                break;
            }
            snprintf(expect,sizeof(expect),"sound_%s",player_character_slot_key(slot));
            if(strcmp(key,expect)==0){
                strncpy(cfg->anim_sound_path[slot],value,sizeof(cfg->anim_sound_path[slot])-1);
                cfg->anim_sound_path[slot][sizeof(cfg->anim_sound_path[slot])-1]=0;
                break;
            }
        }
    }
    fclose(f);
    return true;
}

static bool player_character_library_load(const char *path){
    FILE *f;
    char line[512];
    PlayerCharacterConfig *current=NULL;
    player_character_library_defaults();
    g_player_char_library.count=0;
    g_player_char_library.active_index=0;
    g_player_char_editor_index=0;
    f=fopen(path,"r");
    if(!f){
        PlayerCharacterConfig legacy;
        if(player_character_legacy_load(&legacy,"player.txt")){
            g_player_char_presets[0]=legacy;
            g_player_char_library.count=1;
        }
        return false;
    }
    while(fgets(line,sizeof(line),f)){
        char *eq=strchr(line,'=');
        player_character_config_trim_line(line);
        if(strcmp(line,"preset_begin")==0){
            if(g_player_char_library.count<PLAYER_CHARACTER_PRESET_MAX){
                current=&g_player_char_presets[g_player_char_library.count++];
                player_character_config_defaults(current);
            }
            continue;
        }
        if(strcmp(line,"preset_end")==0){
            current=NULL;
            continue;
        }
        if(!eq) continue;
        *eq=0;
        char *key=line;
        char *value=eq+1;
        player_character_config_trim_line(value);
        if(strcmp(key,"active")==0){
            g_player_char_library.active_index=atoi(value);
            continue;
        }
        if(!current){
            current=&g_player_char_presets[0];
            if(g_player_char_library.count<=0) g_player_char_library.count=1;
        }
        if(strcmp(key,"name")==0){
            strncpy(current->name,value,sizeof(current->name)-1);
            current->name[sizeof(current->name)-1]=0;
            continue;
        }
        if(strcmp(key,"model")==0){
            strncpy(current->model_path,value,sizeof(current->model_path)-1);
            current->model_path[sizeof(current->model_path)-1]=0;
            continue;
        }
        if(strcmp(key,"scale")==0){
            current->scale=clampf((float)atof(value),0.01f,10.0f);
            continue;
        }
        for(int slot=0;slot<PLAYER_CHAR_SLOT_COUNT;slot++){
            char expect[32];
            snprintf(expect,sizeof(expect),"anim_%s",player_character_slot_key(slot));
            if(strcmp(key,expect)==0){
                strncpy(current->anim_override[slot],value,sizeof(current->anim_override[slot])-1);
                current->anim_override[slot][sizeof(current->anim_override[slot])-1]=0;
                break;
            }
            snprintf(expect,sizeof(expect),"sound_%s",player_character_slot_key(slot));
            if(strcmp(key,expect)==0){
                strncpy(current->anim_sound_path[slot],value,sizeof(current->anim_sound_path[slot])-1);
                current->anim_sound_path[slot][sizeof(current->anim_sound_path[slot])-1]=0;
                break;
            }
        }
    }
    fclose(f);
    if(g_player_char_library.count<=0) player_character_library_defaults();
    if(g_player_char_library.active_index<0||g_player_char_library.active_index>=g_player_char_library.count)
        g_player_char_library.active_index=0;
    if(g_player_char_editor_index<0||g_player_char_editor_index>=g_player_char_library.count)
        g_player_char_editor_index=g_player_char_library.active_index;
    return true;
}

static void player_character_library_save(const char *path){
    FILE *f;
    if(!path) return;
    f=fopen(path,"w");
    if(!f) return;
    fprintf(f,"active=%d\n",g_player_char_library.active_index);
    for(int pi=0;pi<g_player_char_library.count&&pi<PLAYER_CHARACTER_PRESET_MAX;pi++){
        PlayerCharacterConfig *cfg=&g_player_char_presets[pi];
        fprintf(f,"preset_begin\n");
        fprintf(f,"name=%s\n",cfg->name[0]?cfg->name:"Character");
        fprintf(f,"model=%s\n",cfg->model_path[0]?cfg->model_path:"models/main_guy.glb");
        fprintf(f,"scale=%.4f\n",(double)cfg->scale);
        for(int slot=0;slot<PLAYER_CHAR_SLOT_COUNT;slot++){
            if(cfg->anim_override[slot][0])
                fprintf(f,"anim_%s=%s\n",player_character_slot_key(slot),cfg->anim_override[slot]);
            if(cfg->anim_sound_path[slot][0])
                fprintf(f,"sound_%s=%s\n",player_character_slot_key(slot),cfg->anim_sound_path[slot]);
        }
        fprintf(f,"preset_end\n");
    }
    fclose(f);
}

static const char *scene_anim_name_at(const Scene *s,int anim_index){
    static const char *empty="";
    if(!s||anim_index<0) return empty;
    if(s->format==SCENE_FORMAT_UFBX&&s->scene&&anim_index<(int)s->scene->anim_stacks.count){
        const char *name=s->scene->anim_stacks.data[anim_index]->name.data;
        return name?name:empty;
    }
    if(s->format==SCENE_FORMAT_GLTF&&s->gltf&&anim_index<(int)s->gltf->animations_count){
        const char *name=s->gltf->animations[anim_index].name;
        return name?name:empty;
    }
    if(s->format==SCENE_FORMAT_MODELC&&s->modelc_anims&&anim_index<s->modelc_anim_count){
        const char *name=s->modelc_anims[anim_index].name;
        return name?name:empty;
    }
    return empty;
}

static bool player_character_find_anim_entry(CharModel *cm,const char *anim_name,AnimEntry *out_entry){
    Scene *scenes[1+CHARMODEL_MAX_EXTRA];
    int scene_count=0;
    if(!cm||!anim_name||!anim_name[0]||!out_entry) return false;
    scenes[scene_count++]=&cm->base;
    for(int i=0;i<cm->extra_count&&scene_count<(int)(sizeof(scenes)/sizeof(scenes[0]));i++)
        scenes[scene_count++]=&cm->extra[i];
    for(int si=0;si<scene_count;si++){
        Scene *scene=scenes[si];
        int idx=scene_find_anim(scene,anim_name);
        if(idx>=0){
            out_entry->scene=scene;
            out_entry->stack=idx;
            return true;
        }
    }
    return false;
}

static void player_character_apply_custom_scale(CharModel *cm,float scale){
    if(!cm||scale==1.0f) return;
    charmodel_apply_scene_scale(&cm->base,scale);
    for(int i=0;i<cm->extra_count;i++) charmodel_apply_scene_scale(&cm->extra[i],scale);
}

static void player_character_apply_config(CharModel *cm,AnimMap *amap,const PlayerCharacterConfig *cfg){
    (void)amap;
    if(!cm||!cfg) return;
    player_character_apply_custom_scale(cm,cfg->scale);
    for(int slot=0;slot<PLAYER_CHAR_SLOT_COUNT&&slot<ANIM_SLOTS;slot++){
        if(cfg->anim_override[slot][0]){
            AnimEntry resolved={0};
            if(player_character_find_anim_entry(cm,cfg->anim_override[slot],&resolved))
                cm->anims[slot]=resolved;
        }
    }
}

static void player_character_reload_runtime(CharModel *char_model,
                                            AnimMap *player_amap,
                                            Player *player,
                                            const PlayerCharacterConfig *cfg){
    if(!char_model||!player_amap||!cfg) return;
    charmodel_free(char_model);
    charmodel_init(char_model,cfg->model_path[0]?cfg->model_path:"models/main_guy.glb");
    animmap_init(player_amap,NULL);
    player_character_apply_config(char_model,player_amap,cfg);
    if(player){
        player->anim_idx=player_amap->idle;
        player->prev_anim_idx=player_amap->idle;
        player->anim_time=0.0;
    }
}

static int player_character_slot_anim_index(const AnimMap *amap,int slot){
    if(!amap) return -1;
    switch(slot){
        case 0: return amap->idle;
        case 1: return amap->walk;
        case 2: return amap->run;
        case 3: return amap->attack;
        case 4: return amap->attack2;
        case 5: return amap->jump;
        case 6: return amap->death;
        case 7: return amap->roll;
        case 8: return amap->block;
        case 9: return amap->hit;
        default: return -1;
    }
}

static void player_character_play_anim_sound(const PlayerCharacterConfig *cfg,const AnimMap *amap,int anim_idx){
    if(!cfg||!amap||anim_idx<0) return;
    for(int slot=0;slot<PLAYER_CHAR_SLOT_COUNT;slot++){
        if(player_character_slot_anim_index(amap,slot)!=anim_idx) continue;
        if(cfg->anim_sound_path[slot][0]) audio_play_file(cfg->anim_sound_path[slot],90);
        break;
    }
}

