static void equip_box_face(Vertex *verts,int base,
                           Vec3 p0,Vec3 p1,Vec3 p2,Vec3 p3,
                           Vec3 normal,Vec3 tangent,Vec3 bitangent){
    const Vec3 pos[4]={p0,p1,p2,p3};
    const float uv[4][2]={{0,0},{1,0},{1,1},{0,1}};
    for(int i=0;i<4;i++){
        Vertex *v=&verts[base+i];
        memset(v,0,sizeof(*v));
        v->pos[0]=pos[i].x;v->pos[1]=pos[i].y;v->pos[2]=pos[i].z;
        v->normal[0]=normal.x;v->normal[1]=normal.y;v->normal[2]=normal.z;
        v->uv[0]=uv[i][0];v->uv[1]=uv[i][1];
        v->tangent[0]=tangent.x;v->tangent[1]=tangent.y;v->tangent[2]=tangent.z;
        v->bitangent[0]=bitangent.x;v->bitangent[1]=bitangent.y;v->bitangent[2]=bitangent.z;
    }
}

static bool equip_mesh_build_box(GpuMesh *gm,
                                 float cx,float cy,float cz,
                                 float sx,float sy,float sz,
                                 const float color[4],const float emissive[3],
                                 float metallic,float roughness){
    Vertex verts[24];
    const GLuint idx[36]={
        0,1,2, 0,2,3, 4,5,6, 4,6,7, 8,9,10, 8,10,11,
        12,13,14, 12,14,15, 16,17,18, 16,18,19, 20,21,22, 20,22,23
    };
    const float x0=cx-sx*0.5f,x1=cx+sx*0.5f;
    const float y0=cy-sy*0.5f,y1=cy+sy*0.5f;
    const float z0=cz-sz*0.5f,z1=cz+sz*0.5f;
    GLH_Attrib attrs[]={
        {0,3,GL_FLOAT,GL_FALSE,offsetof(Vertex,pos)},
        {1,3,GL_FLOAT,GL_FALSE,offsetof(Vertex,normal)},
        {2,2,GL_FLOAT,GL_FALSE,offsetof(Vertex,uv)},
        {3,4,GL_FLOAT,GL_FALSE,offsetof(Vertex,weights)},
        {4,4,GL_INT,0,offsetof(Vertex,bones)},
        {5,3,GL_FLOAT,GL_FALSE,offsetof(Vertex,tangent)},
        {6,3,GL_FLOAT,GL_FALSE,offsetof(Vertex,bitangent)}
    };
    equip_box_face(verts,0,
        (Vec3){x1,y0,z0},(Vec3){x1,y0,z1},(Vec3){x1,y1,z1},(Vec3){x1,y1,z0},
        (Vec3){1,0,0},(Vec3){0,0,1},(Vec3){0,1,0});
    equip_box_face(verts,4,
        (Vec3){x0,y0,z1},(Vec3){x0,y0,z0},(Vec3){x0,y1,z0},(Vec3){x0,y1,z1},
        (Vec3){-1,0,0},(Vec3){0,0,-1},(Vec3){0,1,0});
    equip_box_face(verts,8,
        (Vec3){x0,y1,z0},(Vec3){x1,y1,z0},(Vec3){x1,y1,z1},(Vec3){x0,y1,z1},
        (Vec3){0,1,0},(Vec3){1,0,0},(Vec3){0,0,1});
    equip_box_face(verts,12,
        (Vec3){x0,y0,z1},(Vec3){x1,y0,z1},(Vec3){x1,y0,z0},(Vec3){x0,y0,z0},
        (Vec3){0,-1,0},(Vec3){1,0,0},(Vec3){0,0,-1});
    equip_box_face(verts,16,
        (Vec3){x1,y0,z1},(Vec3){x0,y0,z1},(Vec3){x0,y1,z1},(Vec3){x1,y1,z1},
        (Vec3){0,0,1},(Vec3){-1,0,0},(Vec3){0,1,0});
    equip_box_face(verts,20,
        (Vec3){x0,y0,z0},(Vec3){x1,y0,z0},(Vec3){x1,y1,z0},(Vec3){x0,y1,z0},
        (Vec3){0,0,-1},(Vec3){1,0,0},(Vec3){0,1,0});
    memset(gm,0,sizeof(*gm));
    gm->vao=GLH_mesh_full(verts,sizeof(verts),idx,sizeof(idx),sizeof(Vertex),attrs,7,
                          &gm->vbo,&gm->ebo);
    if(!gm->vao)return false;
    gm->index_count=36;
    gm->geometry_to_world=mat4_identity();
    gm->has_pbr=true;
    gm->metallic=metallic;
    gm->roughness=roughness;
    gm->alpha_cutoff=0.0f;
    gm->mat_color[0]=color[0];gm->mat_color[1]=color[1];gm->mat_color[2]=color[2];gm->mat_color[3]=color[3];
    gm->emissive[0]=emissive[0];gm->emissive[1]=emissive[1];gm->emissive[2]=emissive[2];
    return true;
}

static bool equip_scene_add_box(Scene *sc,
                                float cx,float cy,float cz,
                                float sx,float sy,float sz,
                                const float color[4],const float emissive[3],
                                float metallic,float roughness){
    if(!sc||sc->num_meshes>=MAX_MESHES)return false;
    if(!equip_mesh_build_box(&sc->meshes[sc->num_meshes],cx,cy,cz,sx,sy,sz,color,emissive,metallic,roughness))return false;
    sc->num_meshes++;
    sc->format=SCENE_FORMAT_UFBX;
    return true;
}

static bool equip_scene_add_box_def(Scene *sc,const EquipBoxDef *box){
    if(!sc||!box)return false;
    return equip_scene_add_box(sc,
                               box->cx,box->cy,box->cz,
                               box->sx,box->sy,box->sz,
                               box->color,box->emissive,
                               box->metallic,box->roughness);
}

