static bool item_can_have_equipment_visual(ItemType item){
    return equipment_visual_def(item)!=NULL;
}

static void equipment_models_save_defaults(void){
    FILE *f=fopen(EQUIPMENT_MODEL_FILE,"w");
    if(!f) return;
    fprintf(f,"# item_id|label|model_path\n");
    fprintf(f,"# Leave model_path empty to use procedural fallback visuals.\n");
    for(int item=ITEM_NONE+1;item<ITEM_COUNT;item++){
        if(!item_can_have_equipment_visual((ItemType)item)) continue;
        {
            const EquipmentVisualDef *def=equipment_visual_def((ItemType)item);
            const char *model_path=(def&&def->model_path&&def->model_path[0])?def->model_path:"";
            fprintf(f,"%d|%s|%s\n",item,editor_item_type_name(item),model_path);
        }
    }
    fclose(f);
}

static void equipment_visuals_reset_cache(void){
    for(int item=0;item<ITEM_COUNT;item++){
        if(g_item_visuals[item].built){
            scene_free(&g_item_visuals[item].scene);
        }
        memset(&g_item_visuals[item],0,sizeof(g_item_visuals[item]));
    }
}

static void equipment_models_load(void){
    FILE *f=fopen(EQUIPMENT_MODEL_FILE,"r");
    char line[1024];
    equipment_visuals_reset_cache();
    memset(g_equipment_model_paths,0,sizeof(g_equipment_model_paths));
    if(!f){
        equipment_models_save_defaults();
        return;
    }
    while(fgets(line,sizeof(line),f)){
        char *id_tok,*name_tok,*path_tok,*nl;
        int item_id;
        if(line[0]=='#'||line[0]=='\n'||line[0]=='\r') continue;
        nl=strpbrk(line,"\r\n");
        if(nl) *nl=0;
        id_tok=strtok(line,"|");
        name_tok=strtok(NULL,"|");
        path_tok=strtok(NULL,"");
        (void)name_tok;
        if(!id_tok) continue;
        item_id=atoi(id_tok);
        if(item_id<=ITEM_NONE||item_id>=ITEM_COUNT) continue;
        if(path_tok){
            while(*path_tok==' '||*path_tok=='\t') path_tok++;
            strncpy(g_equipment_model_paths[item_id],path_tok,sizeof(g_equipment_model_paths[item_id])-1);
        }
    }
    fclose(f);
}

static const char *equipment_visual_model_path(const EquipmentVisualDef *def){
    if(!def) return NULL;
    if(def->item>ITEM_NONE&&def->item<ITEM_COUNT&&g_equipment_model_paths[def->item][0])
        return g_equipment_model_paths[def->item];
    if(def->model_path&&def->model_path[0]) return def->model_path;
    return NULL;
}

static void equip_placement_overrides_save(void){
    FILE *f=fopen(EQUIP_PLACEMENT_FILE,"w");
    if(!f) return;
    fprintf(f,"# item inst offx offy offz rotx roty rotz scale\n");
    for(int item=0;item<ITEM_COUNT;item++){
        for(int inst=0;inst<2;inst++){
            const EquipPlacementOverride *ov=&g_equip_placement_overrides[item][inst];
            if(!ov->active) continue;
            fprintf(f,"%d %d %.4f %.4f %.4f %.4f %.4f %.4f %.4f\n",
                    item,inst,
                    (double)ov->offset.x,(double)ov->offset.y,(double)ov->offset.z,
                    (double)ov->rot_deg.x,(double)ov->rot_deg.y,(double)ov->rot_deg.z,
                    (double)ov->scale);
        }
    }
    fclose(f);
}

static void equip_placement_overrides_load(void){
    FILE *f=fopen(EQUIP_PLACEMENT_FILE,"r");
    char line[256];
    memset(g_equip_placement_overrides,0,sizeof(g_equip_placement_overrides));
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        int item,inst;
        float ox,oy,oz,rx,ry,rz,scale;
        if(line[0]=='#'||line[0]=='\n'||line[0]=='\r') continue;
        if(sscanf(line,"%d %d %f %f %f %f %f %f %f",
                  &item,&inst,&ox,&oy,&oz,&rx,&ry,&rz,&scale)==9){
            if(item>ITEM_NONE&&item<ITEM_COUNT&&inst>=0&&inst<2){
                EquipPlacementOverride *ov=&g_equip_placement_overrides[item][inst];
                ov->active=true;
                ov->offset=(Vec3){ox,oy,oz};
                ov->rot_deg=(Vec3){rx,ry,rz};
                ov->scale=scale;
            }
        }
    }
    fclose(f);
}

static EquipAttachInst equip_attach_with_override(ItemType item,EquipAttachInst inst,int inst_index){
    if(item>ITEM_NONE&&item<ITEM_COUNT&&inst_index>=0&&inst_index<2){
        const EquipPlacementOverride *ov=&g_equip_placement_overrides[item][inst_index];
        if(ov->active){
            inst.offset=ov->offset;
            inst.rot_deg=ov->rot_deg;
            inst.scale=ov->scale;
        }
    }
    return inst;
}

static void equip_placement_override_set(ItemType item,int inst_index,EquipAttachInst inst){
    EquipPlacementOverride *ov;
    if(item<=ITEM_NONE||item>=ITEM_COUNT||inst_index<0||inst_index>=2) return;
    ov=&g_equip_placement_overrides[item][inst_index];
    ov->active=true;
    ov->offset=inst.offset;
    ov->rot_deg=inst.rot_deg;
    ov->scale=inst.scale<=0.0f?1.0f:inst.scale;
}

static void equip_placement_override_clear(ItemType item,int inst_index){
    if(item<=ITEM_NONE||item>=ITEM_COUNT||inst_index<0||inst_index>=2) return;
    memset(&g_equip_placement_overrides[item][inst_index],0,sizeof(g_equip_placement_overrides[item][inst_index]));
}

static bool equip_scene_has_renderable_meshes(const Scene *sc){
    if(!scene_has_data(sc)) return false;
    for(int i=0;i<sc->num_meshes;i++){
        const GpuMesh *gm=&sc->meshes[i];
        if(gm->vao&&gm->index_count>0) return true;
    }
    return false;
}

static void equip_item_visual_build(ItemType item){
    EquipItemVisual *ev;
    const EquipmentVisualDef *def;
    const char *model_path;
    bool tried_model=false;
    if(item<=ITEM_NONE||item>=ITEM_COUNT)return;
    ev=&g_item_visuals[item];
    if(ev->built)return;
    memset(ev,0,sizeof(*ev));
    ev->built=true;
    def=equipment_visual_def(item);
    if(!def){
        ev->inst_count=0;
        return;
    }
    ev->inst_count=def->inst_count;
    if(ev->inst_count>(int)(sizeof(ev->inst)/sizeof(ev->inst[0])))
        ev->inst_count=(int)(sizeof(ev->inst)/sizeof(ev->inst[0]));
    for(int i=0;i<ev->inst_count;i++) ev->inst[i]=def->inst[i];
    model_path=equipment_visual_model_path(def);
    if(model_path&&model_path[0]){
        tried_model=true;
        if(scene_load(&ev->scene,model_path)&&equip_scene_has_renderable_meshes(&ev->scene)){
            if(item==ITEM_HELM_KNIGHT){
                printf("[Equip] Knight Helm model loaded path=%s meshes=%d scale=%.4f center=(%.3f,%.3f,%.3f) ground=%.4f\n",
                       model_path,ev->scene.num_meshes,
                       (double)ev->scene.model_scale,
                       (double)ev->scene.cx,(double)ev->scene.cy,(double)ev->scene.cz,
                       (double)ev->scene.ground_offset);
                if(ev->scene.num_meshes>0){
                    GpuMesh *gm=&ev->scene.meshes[0];
                    printf("[Equip] Knight Helm mesh0 vao=%u index_count=%d alpha=%.3f cutoff=%.3f double_sided=%d tex=%u\n",
                           gm->vao,gm->index_count,
                           (double)gm->mat_color[3],(double)gm->alpha_cutoff,
                           gm->double_sided?1:0,gm->texture);
                }
            }
            return;
        }
        if(item==ITEM_HELM_KNIGHT){
            printf("[Equip] Knight Helm model unusable path=%s meshes=%d format=%d\n",
                   model_path,ev->scene.num_meshes,(int)ev->scene.format);
        }
        scene_free(&ev->scene);
        memset(&ev->scene,0,sizeof(ev->scene));
    }
    for(int i=0;i<def->box_count;i++) equip_scene_add_box_def(&ev->scene,&def->boxes[i]);
}

static const char *const *equip_socket_aliases(EquipSocket socket){
    static const char *const right_hand[]={"RightHand","Hand_R","hand_r","hand.r","mixamorig:righthand","weapon_r",NULL};
    static const char *const left_hand[]={"LeftHand","Hand_L","hand_l","hand.l","mixamorig:lefthand","weapon_l",NULL};
    static const char *const head[]={"Head","head","neck","headfront","head_end","mixamorig:head",NULL};
    static const char *const chest[]={"Spine02","Spine2","UpperChest","Chest","Spine01","spine_02","mixamorig:spine2",NULL};
    static const char *const pelvis[]={"Hips","Pelvis","hips","mixamorig:hips",NULL};
    static const char *const left_shoulder[]={"LeftShoulder","Shoulder_L","shoulder_l","shoulder.l","mixamorig:leftshoulder",NULL};
    static const char *const right_shoulder[]={"RightShoulder","Shoulder_R","shoulder_r","shoulder.r","mixamorig:rightshoulder",NULL};
    static const char *const back[]={"Spine01","Spine1","Spine02","UpperChest","Chest","spine_01","mixamorig:spine",NULL};
    static const char *const left_foot[]={"LeftFoot","Foot_L","foot_l","foot.l","mixamorig:leftfoot",NULL};
    static const char *const right_foot[]={"RightFoot","Foot_R","foot_r","foot.r","mixamorig:rightfoot",NULL};
    switch(socket){
        case EQUIP_SOCKET_RIGHT_HAND: return right_hand;
        case EQUIP_SOCKET_LEFT_HAND: return left_hand;
        case EQUIP_SOCKET_HEAD: return head;
        case EQUIP_SOCKET_CHEST: return chest;
        case EQUIP_SOCKET_PELVIS: return pelvis;
        case EQUIP_SOCKET_LEFT_SHOULDER: return left_shoulder;
        case EQUIP_SOCKET_RIGHT_SHOULDER: return right_shoulder;
        case EQUIP_SOCKET_BACK: return back;
        case EQUIP_SOCKET_LEFT_FOOT: return left_foot;
        case EQUIP_SOCKET_RIGHT_FOOT: return right_foot;
        default: return right_hand;
    }
}

static bool equip_name_equals_ci(const char *a,const char *b){
    unsigned char ca,cb;
    if(!a||!b) return false;
    while(*a&&*b){
        ca=(unsigned char)*a++;
        cb=(unsigned char)*b++;
        if(ca>='A'&&ca<='Z') ca=(unsigned char)(ca-'A'+'a');
        if(cb>='A'&&cb<='Z') cb=(unsigned char)(cb-'A'+'a');
        if(ca!=cb) return false;
    }
    return *a==0&&*b==0;
}

static int equip_name_match_score(const char *name,const char *const *aliases){
    if(!name||!aliases) return 0;
    for(int i=0;aliases[i];i++){
        if(equip_name_equals_ci(name,aliases[i])) return 2;
    }
    for(int i=0;aliases[i];i++){
        if(path_contains_ci(name,aliases[i])) return 1;
    }
    return 0;
}

static Mat4 equip_socket_fallback(EquipSocket socket){
    switch(socket){
        case EQUIP_SOCKET_RIGHT_HAND: return mat4_translate(0.34f,1.02f,0.02f);
        case EQUIP_SOCKET_LEFT_HAND: return mat4_translate(-0.34f,1.02f,0.02f);
        case EQUIP_SOCKET_HEAD: return mat4_translate(0.00f,1.72f,0.02f);
        case EQUIP_SOCKET_CHEST: return mat4_translate(0.00f,1.10f,0.00f);
        case EQUIP_SOCKET_PELVIS: return mat4_translate(0.00f,0.92f,0.00f);
        case EQUIP_SOCKET_LEFT_SHOULDER: return mat4_translate(-0.30f,1.34f,0.00f);
        case EQUIP_SOCKET_RIGHT_SHOULDER: return mat4_translate(0.30f,1.34f,0.00f);
        case EQUIP_SOCKET_BACK: return mat4_translate(0.00f,1.18f,-0.12f);
        case EQUIP_SOCKET_LEFT_FOOT: return mat4_translate(-0.14f,0.18f,0.02f);
        case EQUIP_SOCKET_RIGHT_FOOT: return mat4_translate(0.14f,0.18f,0.02f);
        default: return mat4_identity();
    }
}

static Mat4 mat4_without_scale_keep_translation(Mat4 m){
    float lx=sqrtf(m.m[0]*m.m[0] + m.m[1]*m.m[1] + m.m[2]*m.m[2]);
    float ly=sqrtf(m.m[4]*m.m[4] + m.m[5]*m.m[5] + m.m[6]*m.m[6]);
    float lz=sqrtf(m.m[8]*m.m[8] + m.m[9]*m.m[9] + m.m[10]*m.m[10]);
    if(lx>0.000001f){
        m.m[0]/=lx; m.m[1]/=lx; m.m[2]/=lx;
    }
    if(ly>0.000001f){
        m.m[4]/=ly; m.m[5]/=ly; m.m[6]/=ly;
    }
    if(lz>0.000001f){
        m.m[8]/=lz; m.m[9]/=lz; m.m[10]/=lz;
    }
    return m;
}

typedef struct{
    Scene *scene;
    ufbx_scene *eval;
}CharAttachPose;

static void charattach_pose_begin(CharAttachPose *pose,Scene *sc,int anim_index,double at){
    memset(pose,0,sizeof(*pose));
    pose->scene=sc;
    if(!scene_has_data(sc))return;
    if(sc->format==SCENE_FORMAT_UFBX&&sc->scene&&sc->scene->anim_stacks.count>0&&anim_index>=0){
        int idx=anim_index<(int)sc->scene->anim_stacks.count?anim_index:(int)sc->scene->anim_stacks.count-1;
        ufbx_anim_stack *stk=sc->scene->anim_stacks.data[idx];
        double real_end=anim_stack_real_end(stk);
        double dur=real_end-stk->time_begin;
        double t=dur>0.0?fmod(at,dur):0.0;
        pose->eval=ufbx_evaluate_scene(sc->scene,stk->anim,stk->time_begin+t,NULL,NULL);
    }else if(sc->format==SCENE_FORMAT_GLTF){
        scene_gltf_evaluate(sc,anim_index,at);
    }else if(sc->format==SCENE_FORMAT_MODELC){
        scene_modelc_evaluate(sc,anim_index,at);
    }
}

static void charattach_pose_end(CharAttachPose *pose){
    if(pose&&pose->eval){
        ufbx_free_scene(pose->eval);
        pose->eval=NULL;
    }
}

static Mat4 charattach_socket_world(const CharAttachPose *pose,EquipSocket socket){
    const Scene *sc=pose?pose->scene:NULL;
    const char *const *aliases=equip_socket_aliases(socket);
    if(sc&&sc->format==SCENE_FORMAT_GLTF&&sc->gltf&&sc->gltf_eval_world){
        int best_index=-1;
        int best_score=0;
        for(int i=0;i<sc->gltf_node_count;i++){
            const char *name=sc->gltf->nodes[i].name?sc->gltf->nodes[i].name:"";
            int score=equip_name_match_score(name,aliases);
            if(score>best_score){
                best_score=score;
                best_index=i;
                if(score>=2) break;
            }
        }
        if(best_index>=0){
            Mat4 socket=sc->gltf_eval_world?sc->gltf_eval_world[best_index]:
                        (sc->gltf_rest_world?sc->gltf_rest_world[best_index]:mat4_identity());
            /* Keep the animated socket orientation/position, but strip inherited scale
               from the armature so attachments do not explode or collapse. */
            return mat4_without_scale_keep_translation(socket);
        }
    }
    if(sc&&sc->format==SCENE_FORMAT_UFBX){
        const ufbx_scene *src=pose&&pose->eval?pose->eval:sc->scene;
        if(src){
            size_t best_index=(size_t)-1;
            int best_score=0;
            for(size_t i=0;i<src->nodes.count;i++){
                const char *name=src->nodes.data[i]->name.data?src->nodes.data[i]->name.data:"";
                int score=equip_name_match_score(name,aliases);
                if(score>best_score){
                    best_score=score;
                    best_index=i;
                    if(score>=2) break;
                }
            }
            if(best_index!=(size_t)-1) return mat4_from_ufbx(&src->nodes.data[best_index]->node_to_world);
        }
    }
    return equip_socket_fallback(socket);
}

static Mat4 equip_instance_local(EquipAttachInst inst){
    const float d2r=(float)(M_PI/180.0);
    Mat4 sc=mat4_scale_u(inst.scale<=0.0f?1.0f:inst.scale);
    Mat4 rx=mat4_rot_x(inst.rot_deg.x*d2r);
    Mat4 ry=mat4_rot_y(inst.rot_deg.y*d2r);
    Mat4 rz=mat4_rot_z(inst.rot_deg.z*d2r);
    Mat4 rot=mat4_mul(ry,mat4_mul(rx,rz));
    Mat4 tr=mat4_translate(inst.offset.x,inst.offset.y,inst.offset.z);
    return mat4_mul(tr,mat4_mul(rot,sc));
}

static Mat4 equip_scene_local(const Scene *sc){
    if(!scene_has_data(sc)) return mat4_identity();
    float s=sc->model_scale>0.0f?sc->model_scale:1.0f;
    return mat4_mul(mat4_scale_u(s),
                    mat4_translate(-sc->cx,-sc->cy,-sc->cz));
}

static float mat4_uniform_scale(const Mat4 *m){
    float sx,sy,sz;
    if(!m) return 1.0f;
    sx=sqrtf(m->m[0]*m->m[0] + m->m[1]*m->m[1] + m->m[2]*m->m[2]);
    sy=sqrtf(m->m[4]*m->m[4] + m->m[5]*m->m[5] + m->m[6]*m->m[6]);
    sz=sqrtf(m->m[8]*m->m[8] + m->m[9]*m->m[9] + m->m[10]*m->m[10]);
    if(sx<=0.0001f && sy<=0.0001f && sz<=0.0001f) return 1.0f;
    if(sx<=0.0001f) sx=sy>0.0001f?sy:sz;
    if(sy<=0.0001f) sy=sx;
    if(sz<=0.0001f) sz=sx;
    return (sx+sy+sz)*(1.0f/3.0f);
}

static void equip_debug_log(const char *fmt,...){
    FILE *f;
    va_list ap;
    f=fopen("equip_debug.log","a");
    if(!f) return;
    va_start(ap,fmt);
    vfprintf(f,fmt,ap);
    va_end(ap);
    fputc('\n',f);
    fclose(f);
}

void draw_charmodel_equipment(SkinProg *sp,const Inventory *inv,Scene *char_scene,
                              Mat4 wm,int anim_index,double at,
                              Mat4 proj,Mat4 view,Vec3 cam_pos,LightingSystem *ls){
    CharAttachPose pose;
    float parent_scale;
    Mat4 parent_unscale;
    if(!inv||!char_scene)return;
    parent_scale=mat4_uniform_scale(&wm);
    parent_unscale=mat4_scale_u(parent_scale>0.0001f?(1.0f/parent_scale):1.0f);
    charattach_pose_begin(&pose,char_scene,anim_index,at);
    equip_debug_log("[DrawEquip] begin inv=%p scene=%p fmt=%d meshes=%d parent_scale=%.6f anim=%d",
                    (void*)inv,(void*)char_scene,char_scene?(int)char_scene->format:-1,
                    char_scene?char_scene->num_meshes:0,(double)parent_scale,anim_index);
    for(int slot=0;slot<INV_EQUIP_SLOTS;slot++){
        ItemType item=inv->equipped[slot];
        EquipItemVisual *ev;
        if(item<=ITEM_NONE||item>=ITEM_COUNT)continue;
        equip_item_visual_build(item);
        ev=&g_item_visuals[item];
        equip_debug_log("[DrawEquip] slot=%d item=%d built=%d scene_ok=%d inst_count=%d",
                        slot,(int)item,ev->built?1:0,scene_has_data(&ev->scene)?1:0,ev->inst_count);
        if(!ev->built||!scene_has_data(&ev->scene))continue;
        for(int ii=0;ii<ev->inst_count;ii++){
            EquipAttachInst inst=equip_attach_with_override(item,ev->inst[ii],ii);
            Mat4 socket_w=charattach_socket_world(&pose,inst.socket);
            Mat4 item_w=mat4_mul(wm,mat4_mul(socket_w,
                                         mat4_mul(parent_unscale,
                                          mat4_mul(equip_instance_local(inst),equip_scene_local(&ev->scene)))));
            if(slot==EQUIP_SLOT_HELM){
                equip_debug_log("[DrawEquip] helm item=%d inst=%d socket=%d off=(%.3f %.3f %.3f) sc=%.3f item_pos=(%.3f %.3f %.3f)",
                                (int)item,ii,(int)inst.socket,
                                (double)inst.offset.x,(double)inst.offset.y,(double)inst.offset.z,(double)inst.scale,
                                (double)item_w.m[12],(double)item_w.m[13],(double)item_w.m[14]);
            }
            draw_scene_prop(sp,&ev->scene,item_w,proj,view,cam_pos,ls);
        }
    }
    charattach_pose_end(&pose);
}

void shadow_charmodel_equipment(ShadowMap *sm,LightingSystem *ls,const Inventory *inv,
                                Scene *char_scene,Mat4 wm,int anim_index,double at){
    CharAttachPose pose;
    float parent_scale;
    Mat4 parent_unscale;
    if(!inv||!char_scene)return;
    parent_scale=mat4_uniform_scale(&wm);
    parent_unscale=mat4_scale_u(parent_scale>0.0001f?(1.0f/parent_scale):1.0f);
    charattach_pose_begin(&pose,char_scene,anim_index,at);
    for(int slot=0;slot<INV_EQUIP_SLOTS;slot++){
        ItemType item=inv->equipped[slot];
        EquipItemVisual *ev;
        if(item<=ITEM_NONE||item>=ITEM_COUNT)continue;
        equip_item_visual_build(item);
        ev=&g_item_visuals[item];
        if(!ev->built||!scene_has_data(&ev->scene))continue;
        for(int ii=0;ii<ev->inst_count;ii++){
            EquipAttachInst inst=equip_attach_with_override(item,ev->inst[ii],ii);
            Mat4 socket_w=charattach_socket_world(&pose,inst.socket);
            Mat4 item_w=mat4_mul(wm,mat4_mul(socket_w,
                                 mat4_mul(parent_unscale,
                                          mat4_mul(equip_instance_local(inst),equip_scene_local(&ev->scene)))));
            shadow_scene_prop(sm,ls,&ev->scene,item_w);
        }
    }
    charattach_pose_end(&pose);
}

/* ── Skinned Shader ─────────────────────────────────────────── */
static const char *VERT_SKIN=
"#version 330 core\n"
"layout(location=0)in vec3 aPos;\nlayout(location=1)in vec3 aNormal;\n"
"layout(location=2)in vec2 aUV;\nlayout(location=3)in vec4 aWeights;\nlayout(location=4)in ivec4 aBones;\nlayout(location=5)in vec3 aTangent;\nlayout(location=6)in vec3 aBitangent;\n"
"uniform mat4 uProj,uView,uModel,uBones[128];\n"
"out vec3 vNormal,vFragPos,vTangent,vBitangent;out vec2 vUV;\n"
"void main(){\n"
"    mat4 skin=aWeights.x*uBones[aBones.x]+aWeights.y*uBones[aBones.y]+aWeights.z*uBones[aBones.z]+aWeights.w*uBones[aBones.w];\n"
"    if(dot(aWeights,vec4(1))<0.05)skin=mat4(1);\n"
"    vec3 skinnedNormal=mat3(skin)*aNormal;\n"
"    vec3 skinnedTangent=mat3(skin)*aTangent;\n"
"    vec3 skinnedBitangent=mat3(skin)*aBitangent;\n"
"    vec4 world=uModel*skin*vec4(aPos,1);\n"
"    gl_Position=uProj*uView*world;vFragPos=world.xyz;\n"
"    mat3 nmat=mat3(transpose(inverse(uModel)));\n"
"    vNormal=normalize(nmat*skinnedNormal);vTangent=normalize(nmat*skinnedTangent);vBitangent=normalize(nmat*skinnedBitangent);vUV=aUV;}\n";

static const char *FRAG_SKIN=
"#version 330 core\n"
"in vec3 vNormal,vFragPos,vTangent,vBitangent;in vec2 vUV;\n"
"uniform sampler2D uAlbedo,uNormalTex,uMRTex,uEmissiveTex;\n"
"uniform bool uHasTexture,uHasNormalTex,uHasMRTex,uHasEmissiveTex;\n"
"uniform bool uTintEnabled;uniform int uTintRegion;uniform vec3 uTintColors[5];\n"
"uniform bool uDebugAlbedo;\n"
"uniform vec4 uBaseColor;uniform vec3 uEmissiveFactor,uCamPos;uniform float uMetallic,uRoughness,uAlphaCutoff,uFlash;\n"
 LIGHTING_UNIFORMS
"out vec4 FragColor;\n"
/* GGX Cook-Torrance BRDF helpers */
"float D_GGX(float NdotH,float rough){\n"
"    float a=rough*rough;float a2=a*a;\n"
"    float d=NdotH*NdotH*(a2-1.0)+1.0;\n"
"    return a2/(3.14159265*d*d+1e-7);}\n"
"float G_SchlickGGX(float x,float k){return x/(x*(1.0-k)+k);}\n"
"float G_Smith(float NdotV,float NdotL,float rough){\n"
"    float r=rough+1.0;float k=r*r/8.0;\n"
"    return G_SchlickGGX(max(NdotV,0.0001),k)*G_SchlickGGX(max(NdotL,0.0001),k);}\n"
"vec3 F_Schlick(float cosTheta,vec3 F0){return F0+(1.0-F0)*pow(clamp(1.0-cosTheta,0.0,1.0),5.0);}\n"
"void main(){\n"
/* Geometric normal used for shadow bias; shading normal (N) gets normal-mapped below */
"    vec3 gN=normalize(vNormal);\n"
"    vec3 N=gN;\n"
"    if(uHasNormalTex){vec3 tn=texture(uNormalTex,vUV).xyz*2.0-1.0;N=normalize(mat3(normalize(vTangent),normalize(vBitangent),gN)*tn);}\n"
"    vec4 texSample=uHasTexture?texture(uAlbedo,vUV):vec4(1.0);\n"
    /* glTF base color is the texture multiplied by its material factor. */
"    vec4 baseSample=texSample*uBaseColor;\n"
"    if(baseSample.a<uAlphaCutoff)discard;\n"
"    if(uDebugAlbedo){FragColor=vec4(baseSample.rgb,baseSample.a);return;}\n"
"    vec3 albedo=baseSample.rgb;\n"
"    if(uTintEnabled&&uTintRegion>0&&uTintRegion<=4){\n"
"        vec3 tint=uTintColors[uTintRegion-1];\n"
"        float lum=dot(albedo,vec3(0.299,0.587,0.114));\n"
"        albedo=mix(albedo,mix(albedo*(0.55+tint*0.85),tint*(0.35+lum*0.95),0.45),0.75);\n"
"    }\n"
"    float rough=uRoughness,metal=uMetallic;\n"
"    if(uHasMRTex){vec3 mr=texture(uMRTex,vUV).rgb;rough=clamp(rough*mr.g,0.04,1.0);metal=clamp(metal*mr.b,0.0,1.0);}\n"
"    vec3 emissive=uEmissiveFactor*(uHasEmissiveTex?texture(uEmissiveTex,vUV).rgb:vec3(1.0));\n"
"    vec3 F0=mix(vec3(0.04),albedo,metal);\n"
"    vec3 V=normalize(uCamPos-vFragPos);\n"
"    float NdotV=max(dot(N,V),0.0001);\n"
/* Shadow — PCSS from cascade shadow maps, using geometric normal for slope bias */
"    float sunFade=clamp(uSunElev*10.0,0.0,1.0);\n"
"    float shadow=0.0;\n"
"    float gNdotL=dot(gN,-uSunDir);\n"
"    if(gNdotL<=0.0){shadow=sunFade;}\n"
"    else if(sunFade>0.0){\n"
"        float sb=clamp(1.0-gNdotL,0.0,1.0);\n"
"        vec4 lsF=uLightVP*vec4(vFragPos+gN*(0.06+sb*0.18),1.0);\n"
"        vec3 pC=lsF.xyz/lsF.w*0.5+0.5;\n"
"        vec2 pd[12]=vec2[12](vec2(-0.326,-0.406),vec2(-0.840,-0.074),vec2(-0.696,0.457),vec2(-0.203,0.621),vec2(0.962,-0.195),vec2(0.473,-0.480),vec2(0.519,0.767),vec2(0.185,-0.893),vec2(0.507,0.064),vec2(0.896,0.412),vec2(-0.322,-0.933),vec2(-0.792,-0.598));\n"
"        if(pC.z<=1.0&&pC.x>0.02&&pC.x<0.98&&pC.y>0.02&&pC.y<0.98){\n"
"            vec2 ts=1.0/vec2(textureSize(uShadowMap,0));float bias=0.00015+sb*0.00035;\n"
"            float bD=0.0,bC=0.0;\n"
"            for(int i=0;i<5;i++){float d=texture(uShadowMap,pC.xy+pd[i]*ts*5.0).r;if(pC.z-bias>d){bD+=d;bC+=1.0;}}\n"
"            float pen=(bC>0.0)?clamp((pC.z-bD/bC)/(bD/bC)*3.5,0.5,9.0):2.5;\n"
"            float pcf=0.0;for(int i=0;i<12;i++){float sd=texture(uShadowMap,pC.xy+pd[i]*ts*pen).r;pcf+=(pC.z-bias>sd)?1.0:0.0;}\n"
"            shadow=clamp(pcf/12.0,0.0,0.65)*sunFade;\n"
"        }else{\n"
"            vec4 lsW=uLightVPWide*vec4(vFragPos+gN*(0.18+sb*0.35),1.0);\n"
"            vec3 pW=lsW.xyz/lsW.w*0.5+0.5;\n"
"            if(pW.z<=1.0&&pW.x>0.0&&pW.x<1.0&&pW.y>0.0&&pW.y<1.0){\n"
"                vec2 tw=1.0/vec2(textureSize(uShadowMapWide,0));float pcfw=0.0;float bW=0.0004+sb*0.0008;\n"
"                for(int i=0;i<12;i++){float sd=texture(uShadowMapWide,pW.xy+pd[i]*tw*4.0).r;pcfw+=(pW.z-bW>sd)?1.0:0.0;}\n"
"                shadow=clamp(pcfw/12.0,0.0,0.55)*sunFade*0.7;\n"
"            }\n"
"        }\n"
"    }\n"
/* Sun directional light — Cook-Torrance GGX or toon, shadow-modulated */
"    vec3 L=normalize(-uSunDir);\n"
"    vec3 H=normalize(V+L);\n"
"    float NdotL=max(dot(N,L),0.0);\n"
"    float NdotH=max(dot(N,H),0.0);\n"
"    float HdotV=max(dot(H,V),0.0);\n"
"    vec3 col=vec3(0.0);\n"
"    if(!uToonShading){\n"
/* PBR path: GGX specular + Lambertian diffuse, energy conserving via Fresnel split */
"        vec3 F=F_Schlick(HdotV,F0);\n"
"        vec3 kD=(vec3(1.0)-F)*(1.0-metal);\n"
"        float D=D_GGX(NdotH,rough);float G=G_Smith(NdotV,NdotL,rough);\n"
"        vec3 spec=D*G*F/(4.0*NdotV*NdotL+0.001);\n"
"        col+=(kD*albedo/3.14159265+spec)*uSunColor*NdotL*(1.0-shadow);\n"
/* Hemisphere ambient: split into diffuse and specular terms via Fresnel */
"        float hemi=N.y*0.5+0.5;\n"
"        vec3 skyAmb=mix(uAmbient*0.7,uAmbient*1.3+vec3(0.04,0.05,0.08),hemi);\n"
"        vec3 Fa=F_Schlick(NdotV,F0);\n"
"        col+=(vec3(1.0)-Fa)*(1.0-metal)*albedo*skyAmb+Fa*skyAmb*(1.0-rough*0.5);\n"
/* Point lights — full GGX per light */
"        for(int i=0;i<uNumLights;i++){\n"
"            vec3 lv=uLightPos[i]-vFragPos;float dist=length(lv);\n"
"            vec3 Ll=normalize(lv);vec3 Hl=normalize(V+Ll);\n"
"            float att=1.0-clamp(dist/uLightRadius[i],0.0,1.0);\n"
"            float cone=1.0;\n"
"            if(uLightParams[i].x>0.5) cone=smoothstep(uLightParams[i].z,uLightParams[i].y,dot(normalize(uLightDir[i]),-Ll));\n"
"            att*=att*cone;\n"
"            float NdotLl=max(dot(N,Ll),0.0);float NdotHl=max(dot(N,Hl),0.0);float HdotVl=max(dot(Hl,V),0.0);\n"
"            vec3 Fl=F_Schlick(HdotVl,F0);\n"
"            float Dl=D_GGX(NdotHl,rough);float Gl=G_Smith(NdotV,NdotLl,rough);\n"
"            col+=((vec3(1.0)-Fl)*(1.0-metal)*albedo/3.14159265+Dl*Gl*Fl/(4.0*NdotV*NdotLl+0.001))*uLightColor[i]*NdotLl*att;\n"
"        }\n"
"    }else{\n"
/* Toon path: quantized bands, ink rim, shadow-aware */
"        float rawDiff=NdotL*(1.0-shadow);\n"
"        float toonDiff=(rawDiff>0.0)?ceil(rawDiff*uToonBands)/uToonBands:0.0;\n"
"        float toonSpec=step(0.52,pow(NdotH,mix(96.0,8.0,rough)))*(1.0-shadow);\n"
"        float rim=pow(clamp(1.0-NdotV,0.0,1.0),1.8);\n"
"        vec3 diffC=mix(albedo,vec3(0.0),metal);vec3 specC=mix(vec3(0.04),albedo,metal);\n"
"        col=diffC*(uAmbient*0.75+uSunColor*(0.12+toonDiff*0.88))+specC*uSunColor*toonSpec*0.22+albedo*rim*0.08;\n"
        /* toonDiff is already quantized via ceil(rawDiff*uToonBands)/uToonBands above,
           so the toon bands are baked into col. Do NOT quantize the final linear-space
           color product — sRGB textures decoded to linear have small values (~0.05-0.25)
           that collapse to wrong hues when quantized this way. */
"        float ink=smoothstep(0.46,0.88,rim)*(1.0-smoothstep(0.0,0.55,rawDiff));\n"
"        col=mix(col,vec3(0.05,0.06,0.07),ink*0.82);\n"
"        col=mix(vec3(dot(col,vec3(0.299,0.587,0.114))),col,1.22);\n"
"        for(int i=0;i<uNumLights;i++){\n"
"            vec3 lv=uLightPos[i]-vFragPos;float d=length(lv);\n"
"            vec3 Ll=normalize(lv);\n"
"            float att=1.0-clamp(d/uLightRadius[i],0.0,1.0);\n"
"            float cone=1.0;\n"
"            if(uLightParams[i].x>0.5) cone=smoothstep(uLightParams[i].z,uLightParams[i].y,dot(normalize(uLightDir[i]),-Ll));\n"
"            att*=att*cone;\n"
"            float ldiff=max(dot(N,Ll),0.0);\n"
"            if(ldiff>0.0)ldiff=ceil(ldiff*uToonBands)/uToonBands;\n"
"            vec3 Hl=normalize(V+Ll);\n"
"            float lspec=step(0.58,pow(max(dot(N,Hl),0.0),mix(96.0,8.0,rough)));\n"
"            col+=diffC*uLightColor[i]*ldiff*att+specC*uLightColor[i]*lspec*att*(1.0-rough*0.65);\n"
"        }\n"
"    }\n"
"    col+=emissive;\n"
"    col=mix(col,vec3(1.0,0.1,0.1),uFlash);\n"
"    FragColor=vec4(col,baseSample.a);}\n";

static void skinprog_init(SkinProg *sp){sp->prog=GLH_program(VERT_SKIN,FRAG_SKIN);sp->loc_model=glGetUniformLocation(sp->prog,"uModel");sp->loc_bones=glGetUniformLocation(sp->prog,"uBones[0]");}

Mat4 entity_mat(Vec3 pos,float yaw,float dy,float scale,float cx,float cy,float cz){
    return mat4_mul(mat4_translate(pos.x,pos.y+dy,pos.z),mat4_mul(mat4_rot_y(yaw),mat4_mul(mat4_scale_u(scale),mat4_translate(-cx,-cy,-cz))));
}

static void draw_scene(SkinProg *sp,Scene *sc,Mat4 wm,int ai,double at,float flash,Mat4 proj,Mat4 view,Vec3 cam_pos,LightingSystem *ls){
    if(!scene_has_data(sc))return; /* no mesh loaded — skip silently */
    static int debug_albedo=-1;
    if(debug_albedo<0) debug_albedo=(getenv("ENGINE_DEBUG_ALBEDO")&&getenv("ENGINE_DEBUG_ALBEDO")[0]&&getenv("ENGINE_DEBUG_ALBEDO")[0]!='0')?1:0;
    lighting_push(ls,sp->prog);GLH_begin(sp->prog,proj.m,view.m);GLH_float(sp->prog,"uFlash",flash);GLH_vec3(sp->prog,"uCamPos",cam_pos.x,cam_pos.y,cam_pos.z);GLH_bool(sp->prog,"uDebugAlbedo",debug_albedo);GLH_bool(sp->prog,"uTintEnabled",g_player_tint_enabled);GLH_vec3_array(sp->prog,"uTintColors",APPEARANCE_COLOR_SLOTS,&g_player_tint_colors[0][0]);
    ufbx_scene *eval=NULL;
    if(sc->format==SCENE_FORMAT_UFBX&&sc->scene&&sc->scene->anim_stacks.count>0&&ai>=0){int idx=ai<(int)sc->scene->anim_stacks.count?ai:(int)sc->scene->anim_stacks.count-1;ufbx_anim_stack *stk=sc->scene->anim_stacks.data[idx];double real_end=anim_stack_real_end(stk);double dur=real_end-stk->time_begin;double t=dur>0?fmod(at,dur):0;eval=ufbx_evaluate_scene(sc->scene,stk->anim,stk->time_begin+t,NULL,NULL);}
    else if(sc->format==SCENE_FORMAT_GLTF)scene_gltf_evaluate(sc,ai,at);
    else if(sc->format==SCENE_FORMAT_MODELC)scene_modelc_evaluate(sc,ai,at);
    Mat4 bone_mats[MAX_BONES];
    for(int mi=0;mi<sc->num_meshes;mi++){GpuMesh *gm=&sc->meshes[mi];Mat4 mesh_mat;
        if(sc->format==SCENE_FORMAT_UFBX&&sc->skins[mi])mesh_mat=wm;
        /* Skinned glTF bones are generated in mesh-local space by compute_bones_gltf(),
           so uModel stays at the entity/world transform only. */
        else if(sc->format==SCENE_FORMAT_GLTF&&gm->num_gpu_bones>0)mesh_mat=wm;
        else if(sc->format==SCENE_FORMAT_MODELC&&gm->num_gpu_bones>0&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mesh_mat=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
        else if(eval&&sc->format==SCENE_FORMAT_UFBX&&gm->node_typed_id<eval->nodes.count){ufbx_matrix g2w=eval->nodes.data[gm->node_typed_id]->geometry_to_world;mesh_mat=mat4_mul(wm,mat4_from_ufbx(&g2w));}
        else if(sc->format==SCENE_FORMAT_GLTF&&sc->gltf_eval_world&&gm->node_typed_id<(uint32_t)sc->gltf_node_count)mesh_mat=mat4_mul(wm,sc->gltf_eval_world[gm->node_typed_id]);
        else if(sc->format==SCENE_FORMAT_MODELC&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mesh_mat=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
        else mesh_mat=mat4_mul(wm,gm->geometry_to_world);
        glUniformMatrix4fv(sp->loc_model,1,GL_FALSE,mesh_mat.m);
        if(gm->texture){GLH_bind_texture(sp->prog,"uAlbedo",gm->texture,0);GLH_bool(sp->prog,"uHasTexture",1);}
        else GLH_bool(sp->prog,"uHasTexture",0);
        GLH_int(sp->prog,"uTintRegion",g_player_tint_enabled?(int)gm->tint_region:0);
        if(gm->normal_tex){GLH_bind_texture(sp->prog,"uNormalTex",gm->normal_tex,1);GLH_bool(sp->prog,"uHasNormalTex",1);} else GLH_bool(sp->prog,"uHasNormalTex",0);
        if(gm->mr_tex){GLH_bind_texture(sp->prog,"uMRTex",gm->mr_tex,2);GLH_bool(sp->prog,"uHasMRTex",1);} else GLH_bool(sp->prog,"uHasMRTex",0);
        if(gm->emissive_tex){GLH_bind_texture(sp->prog,"uEmissiveTex",gm->emissive_tex,3);GLH_bool(sp->prog,"uHasEmissiveTex",1);} else GLH_bool(sp->prog,"uHasEmissiveTex",0);
        GLH_vec4(sp->prog,"uBaseColor",gm->mat_color[0],gm->mat_color[1],gm->mat_color[2],gm->mat_color[3]);
        GLH_vec3(sp->prog,"uEmissiveFactor",gm->emissive[0],gm->emissive[1],gm->emissive[2]);
        GLH_float(sp->prog,"uMetallic",gm->metallic);
        GLH_float(sp->prog,"uRoughness",gm->roughness);
        GLH_float(sp->prog,"uAlphaCutoff",gm->alpha_cutoff);
        for(int i=0;i<MAX_BONES;i++)bone_mats[i]=mat4_identity();
        if(sc->format==SCENE_FORMAT_GLTF)compute_bones_gltf(bone_mats,gm->num_gpu_bones,gm,sc);
        else if(sc->format==SCENE_FORMAT_MODELC)compute_bones_modelc(bone_mats,gm->num_gpu_bones,gm,sc);
        else compute_bones(bone_mats,gm->num_gpu_bones,gm,sc->skins[mi],eval);
        glUniformMatrix4fv(sp->loc_bones,MAX_BONES,GL_FALSE,bone_mats[0].m);
        /* Per-mesh polygon offset: each successive layer (clothing over body) is
           pulled slightly toward the camera to prevent z-fighting. */
        glEnable(GL_POLYGON_OFFSET_FILL);
        glPolygonOffset(-1.0f*(float)(mi+1),-1.0f*(float)(mi+1));
        glBindVertexArray(gm->vao);glDrawElements(GL_TRIANGLES,gm->index_count,GL_UNSIGNED_INT,0);
        glPolygonOffset(0.0f,0.0f);glDisable(GL_POLYGON_OFFSET_FILL);}
    if(eval)ufbx_free_scene(eval);
}

static void draw_scene_prop(SkinProg *sp,Scene *sc,Mat4 wm,Mat4 proj,Mat4 view,Vec3 cam_pos,LightingSystem *ls){
    if(!scene_has_data(sc))return;
    glEnable(GL_DEPTH_TEST);
    glDepthMask(GL_TRUE);
    glDisable(GL_BLEND);
    lighting_push(ls,sp->prog);
    GLH_begin(sp->prog,proj.m,view.m);
    GLH_float(sp->prog,"uFlash",0.0f);
    GLH_vec3(sp->prog,"uCamPos",cam_pos.x,cam_pos.y,cam_pos.z);
    GLH_bool(sp->prog,"uDebugAlbedo",0);
    GLH_bool(sp->prog,"uTintEnabled",0);
    if(sc->format==SCENE_FORMAT_GLTF)scene_gltf_evaluate(sc,-1,0.0);
    else if(sc->format==SCENE_FORMAT_MODELC)scene_modelc_evaluate(sc,-1,0.0);
    {
        Mat4 bone_mats[MAX_BONES];
        for(int mi=0;mi<sc->num_meshes;mi++){GpuMesh *gm=&sc->meshes[mi];Mat4 mesh_mat;
            bool two_sided=(gm->double_sided||gm->alpha_cutoff>0.001f||gm->mat_color[3]<0.999f);
            if(sc->format==SCENE_FORMAT_GLTF&&gm->num_gpu_bones>0)mesh_mat=wm;
            else if(sc->format==SCENE_FORMAT_MODELC&&gm->num_gpu_bones>0&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mesh_mat=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
            else if(sc->format==SCENE_FORMAT_GLTF&&sc->gltf_eval_world&&gm->node_typed_id<(uint32_t)sc->gltf_node_count)mesh_mat=mat4_mul(wm,sc->gltf_eval_world[gm->node_typed_id]);
            else if(sc->format==SCENE_FORMAT_MODELC&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mesh_mat=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
            else mesh_mat=mat4_mul(wm,gm->geometry_to_world);
            if(two_sided) glDisable(GL_CULL_FACE);
            else { glEnable(GL_CULL_FACE); glCullFace(GL_BACK); }
            glUniformMatrix4fv(sp->loc_model,1,GL_FALSE,mesh_mat.m);
            if(gm->texture){GLH_bind_texture(sp->prog,"uAlbedo",gm->texture,0);GLH_bool(sp->prog,"uHasTexture",1);}
            else GLH_bool(sp->prog,"uHasTexture",0);
            GLH_int(sp->prog,"uTintRegion",0);
            if(gm->normal_tex){GLH_bind_texture(sp->prog,"uNormalTex",gm->normal_tex,1);GLH_bool(sp->prog,"uHasNormalTex",1);} else GLH_bool(sp->prog,"uHasNormalTex",0);
            if(gm->mr_tex){GLH_bind_texture(sp->prog,"uMRTex",gm->mr_tex,2);GLH_bool(sp->prog,"uHasMRTex",1);} else GLH_bool(sp->prog,"uHasMRTex",0);
            if(gm->emissive_tex){GLH_bind_texture(sp->prog,"uEmissiveTex",gm->emissive_tex,3);GLH_bool(sp->prog,"uHasEmissiveTex",1);} else GLH_bool(sp->prog,"uHasEmissiveTex",0);
            GLH_vec4(sp->prog,"uBaseColor",gm->mat_color[0],gm->mat_color[1],gm->mat_color[2],gm->mat_color[3]);
            GLH_vec3(sp->prog,"uEmissiveFactor",gm->emissive[0],gm->emissive[1],gm->emissive[2]);
            GLH_float(sp->prog,"uMetallic",gm->metallic);
            GLH_float(sp->prog,"uRoughness",gm->roughness);
            GLH_float(sp->prog,"uAlphaCutoff",gm->alpha_cutoff);
            for(int i=0;i<MAX_BONES;i++)bone_mats[i]=mat4_identity();
            if(sc->format==SCENE_FORMAT_GLTF)compute_bones_gltf(bone_mats,gm->num_gpu_bones,gm,sc);
            else if(sc->format==SCENE_FORMAT_MODELC)compute_bones_modelc(bone_mats,gm->num_gpu_bones,gm,sc);
            else compute_bones(bone_mats,gm->num_gpu_bones,gm,sc->skins[mi],NULL);
            glUniformMatrix4fv(sp->loc_bones,MAX_BONES,GL_FALSE,bone_mats[0].m);
            glBindVertexArray(gm->vao);glDrawElements(GL_TRIANGLES,gm->index_count,GL_UNSIGNED_INT,0);}
    }
    glEnable(GL_CULL_FACE);
    glCullFace(GL_BACK);
}

/* Draw using a CharModel — resolves correct scene+stack per anim slot */
void draw_charmodel(SkinProg *sp,CharModel *cm,Mat4 wm,int anim_slot,double at,float flash,Mat4 proj,Mat4 view,Vec3 cam_pos,LightingSystem *ls){
    if(!cm||!scene_has_data(&cm->base))return; /* model not loaded — skip */
    if(anim_slot<0||anim_slot>=ANIM_SLOTS)anim_slot=ANIM_IDLE;
    AnimEntry *ae=&cm->anims[anim_slot];
    Scene *sc=ae->scene?ae->scene:&cm->base;
    draw_scene(sp,sc,wm,ae->scene?ae->stack:-1,at,flash,proj,view,cam_pos,ls);
    if(g_charmodel_render_inventory)
        draw_charmodel_equipment(sp,g_charmodel_render_inventory,sc,wm,
                                 ae->scene?ae->stack:-1,at,proj,view,cam_pos,ls);
}
static void shadow_scene_prop(ShadowMap *sm,LightingSystem *ls,Scene *sc,Mat4 wm){
    if(!scene_has_data(sc))return;
    glUseProgram(sm->prog_skin_depth);
    glUniformMatrix4fv(glGetUniformLocation(sm->prog_skin_depth,"uLightVP"),1,GL_FALSE,ls->light_vp.m);
    if(sc->format==SCENE_FORMAT_GLTF)scene_gltf_evaluate(sc,-1,0.0);
    else if(sc->format==SCENE_FORMAT_MODELC)scene_modelc_evaluate(sc,-1,0.0);
    {
        GLint loc_mod=glGetUniformLocation(sm->prog_skin_depth,"uModel");
        GLint loc_bon=glGetUniformLocation(sm->prog_skin_depth,"uBones[0]");
        Mat4 bone_mats[MAX_BONES];
        for(int mi=0;mi<sc->num_meshes;mi++){GpuMesh *gm=&sc->meshes[mi];Mat4 mm;
            bool two_sided=(gm->alpha_cutoff>0.001f||gm->mat_color[3]<0.999f);
            if(sc->format==SCENE_FORMAT_GLTF&&gm->num_gpu_bones>0)mm=wm;
            else if(sc->format==SCENE_FORMAT_MODELC&&gm->num_gpu_bones>0&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mm=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
            else if(sc->format==SCENE_FORMAT_GLTF&&sc->gltf_eval_world&&gm->node_typed_id<(uint32_t)sc->gltf_node_count)mm=mat4_mul(wm,sc->gltf_eval_world[gm->node_typed_id]);
            else if(sc->format==SCENE_FORMAT_MODELC&&sc->modelc_eval_world&&gm->node_typed_id<(uint32_t)sc->modelc_node_count)mm=mat4_mul(wm,sc->modelc_eval_world[gm->node_typed_id]);
            else mm=mat4_mul(wm,gm->geometry_to_world);
            if(two_sided) glDisable(GL_CULL_FACE);
            else { glEnable(GL_CULL_FACE); glCullFace(GL_BACK); }
            glUniformMatrix4fv(loc_mod,1,GL_FALSE,mm.m);
            for(int i=0;i<MAX_BONES;i++)bone_mats[i]=mat4_identity();
            if(sc->format==SCENE_FORMAT_GLTF)compute_bones_gltf(bone_mats,gm->num_gpu_bones,gm,sc);
            else if(sc->format==SCENE_FORMAT_MODELC)compute_bones_modelc(bone_mats,gm->num_gpu_bones,gm,sc);
            else compute_bones(bone_mats,gm->num_gpu_bones,gm,sc->skins[mi],NULL);
            glUniformMatrix4fv(loc_bon,MAX_BONES,GL_FALSE,bone_mats[0].m);
            glBindVertexArray(gm->vao);glDrawElements(GL_TRIANGLES,gm->index_count,GL_UNSIGNED_INT,0);}
    }
    glEnable(GL_CULL_FACE);
    glCullFace(GL_BACK);
}
static void shadow_scene(ShadowMap *sm,LightingSystem *ls,Scene *sc,Mat4 wm,int ai,double at);
static void static_collision_world_mark_dirty(void);
static const char *scene_name(SceneID scene);
static SceneID scene_id_for_props(const PropList *pl);
int static_collision_world_obstacle_count(void);
bool static_collision_world_obstacle_aabb(int idx,AABB *out_box);
void static_collision_world_move_capsule(Vec3 *pos,Vec3 move,Vec3 *vel,bool *on_ground,float height,float radius);
void static_collision_world_resolve_capsule(Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius);
