#define MAX_DMG_LABELS 48
typedef struct{Vec3 world_pos;float timer,damage;bool is_crit,is_incoming;}DmgLabel;
static DmgLabel g_dmg_labels[MAX_DMG_LABELS];

static DmgLabel *dmg_label_alloc(void){
    DmgLabel *slot=NULL;float lowest=999.0f;DmgLabel *oldest=&g_dmg_labels[0];
    for(int i=0;i<MAX_DMG_LABELS;i++){
        if(g_dmg_labels[i].timer<=0.0f){slot=&g_dmg_labels[i];break;}
        if(g_dmg_labels[i].timer<lowest){lowest=g_dmg_labels[i].timer;oldest=&g_dmg_labels[i];}
    }
    return slot?slot:oldest;
}

void dmg_label_spawn(Vec3 pos,float damage,bool is_crit){
    DmgLabel *s=dmg_label_alloc();
    s->world_pos=pos;s->world_pos.y+=0.5f;
    s->timer=1.2f;s->damage=damage;s->is_crit=is_crit;s->is_incoming=false;
}

void dmg_label_spawn_incoming(Vec3 pos,float damage){
    DmgLabel *s=dmg_label_alloc();
    s->world_pos=pos;s->world_pos.y+=1.0f;
    s->timer=1.0f;s->damage=damage;s->is_crit=false;s->is_incoming=true;
}

