static void appearance_reset(PlayerAppearance *ap){
    memset(ap,0,sizeof(*ap));
    ap->selected_slot=0;
    memcpy(ap->rgb,APPEARANCE_DEFAULT_RGB,sizeof(ap->rgb));
}

static void appearance_sync_render_state(const PlayerAppearance *ap){
    for(int i=0;i<APPEARANCE_COLOR_SLOTS;i++){
        g_player_tint_colors[i][0]=(float)ap->rgb[i][0]/255.0f;
        g_player_tint_colors[i][1]=(float)ap->rgb[i][1]/255.0f;
        g_player_tint_colors[i][2]=(float)ap->rgb[i][2]/255.0f;
    }
}

static void appearance_stage_saved_from_current(const PlayerAppearance *ap){
    memcpy(g_player_appearance_saved_rgb,ap->rgb,sizeof(g_player_appearance_saved_rgb));
}

static void appearance_restore_saved(PlayerAppearance *ap){
    memcpy(ap->rgb,g_player_appearance_saved_rgb,sizeof(g_player_appearance_saved_rgb));
    appearance_sync_render_state(ap);
}

static void appearance_set_enabled_from_saved(PlayerAppearance *ap,bool enabled){
    appearance_restore_saved(ap);
    g_player_tint_enabled=enabled;
}

static bool appearance_save_button_hit(int mx,int my,int win_w,int win_h){
    const float W=(float)win_w,H=(float)win_h;
    const float pw=520.0f,ph=360.0f;
    const float px=(W-pw)*0.5f,py=(H-ph)*0.5f;
    const float bx=px+pw-120.0f,by=py+ph-48.0f,bw=92.0f,bh=30.0f;
    return mx>=bx&&mx<=bx+bw&&my>=by&&my<=by+bh;
}

static void appearance_adjust(PlayerAppearance *ap,int slot,int channel,int delta){
    int v;
    if(!ap||slot<0||slot>=APPEARANCE_COLOR_SLOTS||channel<0||channel>=3) return;
    v=(int)ap->rgb[slot][channel]+delta;
    if(v<0)v=0;
    if(v>255)v=255;
    ap->rgb[slot][channel]=(unsigned char)v;
    appearance_sync_render_state(ap);
}

static void appearance_load_from_bytes(PlayerAppearance *ap,const uint8_t *src,int count){
    bool any=false;
    appearance_reset(ap);
    if(!src) return;
    for(int i=0;i<APPEARANCE_COLOR_SLOTS*3&&i<count;i++){
        if(src[i]!=0) any=true;
        ap->rgb[i/3][i%3]=src[i];
    }
    if(!any) memcpy(ap->rgb,APPEARANCE_DEFAULT_RGB,sizeof(ap->rgb));
    appearance_stage_saved_from_current(ap);
    appearance_sync_render_state(ap);
}

