#define HUD_MAX_VERTS 32768   /* 6 floats per vertex: x,y,r,g,b,a */
static float g_hud_vbuf[HUD_MAX_VERTS*6];  /* static — lives in BSS, not stack */
typedef struct HUD{
    GLuint prog,vao,vbo;
    int win_w,win_h;
    int vcount;
}HUD;
static void loading_render(HUD *h,int win_w,int win_h,
                           const char *step,int done,int total);
static void hud_init(HUD *h,int w,int hp){
    h->win_w=w;h->win_h=hp;h->vcount=0;
    h->prog=GLH_program(
        "#version 330 core\nlayout(location=0)in vec2 aPos;\nlayout(location=1)in vec4 aColor;\nuniform mat4 uOrtho;\nout vec4 vColor;\nvoid main(){gl_Position=uOrtho*vec4(aPos,0,1);vColor=aColor;}\n",
        "#version 330 core\nin vec4 vColor;out vec4 F;\nvoid main(){F=vColor;}\n");
    GLH_Attrib a[]={{0,2,GL_FLOAT,GL_FALSE,0},{1,4,GL_FLOAT,GL_FALSE,8}};
    h->vbo=GLH_vbo(HUD_MAX_VERTS*6*sizeof(float));
    h->vao=GLH_mesh_dynamic(HUD_MAX_VERTS*6*sizeof(float),24,a,2);    glBindVertexArray(h->vao);glBindBuffer(GL_ARRAY_BUFFER,h->vbo);
    glVertexAttribPointer(0,2,GL_FLOAT,GL_FALSE,24,(void*)0);
    glVertexAttribPointer(1,4,GL_FLOAT,GL_FALSE,24,(void*)8);
    glBindVertexArray(0);
}
static void hud_resize(HUD *h,int w,int hp){h->win_w=w;h->win_h=hp;}
static void menu_text_flush(HUD *h);
static void hud_rect(HUD *h,float x,float y,float w,float ht,float r,float g,float b,float a){
    if(h->vcount+6>HUD_MAX_VERTS)return;
    float *v=g_hud_vbuf+h->vcount*6;
    float q[][6]={{x,y,r,g,b,a},{x+w,y,r,g,b,a},{x+w,y+ht,r,g,b,a},{x,y,r,g,b,a},{x+w,y+ht,r,g,b,a},{x,y+ht,r,g,b,a}};
    memcpy(v,q,sizeof(q));h->vcount+=6;
}
static void hud_flush(HUD *h){
    if(!h->vcount)return;
    float fw=(float)h->win_w,fh=(float)h->win_h;
    Mat4 o=mat4_identity();o.m[0]=2.0f/fw;o.m[5]=-2.0f/fh;o.m[12]=-1.0f;o.m[13]=1.0f;
    GLH_vbo_update(h->vbo,g_hud_vbuf,(size_t)h->vcount*6*sizeof(float));
    glUseProgram(h->prog);GLH_mat4(h->prog,"uOrtho",o.m);
    glBindVertexArray(h->vao);glBindBuffer(GL_ARRAY_BUFFER,h->vbo);
    glDisable(GL_DEPTH_TEST);
    glDisable(GL_CULL_FACE);
    glDepthMask(GL_TRUE);          /* ensure depth mask never blocks HUD draw */
    glDisable(GL_POLYGON_OFFSET_FILL);
    glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);
    glDrawArrays(GL_TRIANGLES,0,h->vcount);
    glDisable(GL_BLEND);
    glEnable(GL_DEPTH_TEST);
    /* do NOT restore cull face here — game runs with it off by default */
    glBindVertexArray(0);
    h->vcount=0;
    menu_text_flush(h);
}
static void hud_bar(HUD *h,float x,float y,float w,float ht,float pct,float fr,float fg,float fb,float br,float bg,float bb){
    hud_rect(h,x,y,w,ht,br,bg,bb,0.75f);hud_rect(h,x,y,w*clampf(pct,0,1),ht,fr,fg,fb,0.9f);
}
static void hud_char(HUD *h,float x,float y,float sc,char c,float r,float g,float b,float a){
    int idx=(int)(unsigned char)c-32;if(idx<0||idx>=96)idx=31;/*'?'*/
    for(int row=0;row<8;row++){uint8_t bits=g_font[idx][row];for(int col=0;col<8;col++){if(bits&(0x80u>>col))hud_rect(h,x+col*sc,y+row*sc,sc,sc,r,g,b,a);}}
}
static void hud_str_bitmap(HUD *h,float x,float y,float sc,const char *s,float r,float g,float b,float a){
    float cx=x;for(int i=0;s[i];i++){if(s[i]=='\n'){y+=9*sc;cx=x;continue;}hud_char(h,cx,y,sc,s[i],r,g,b,a);cx+=9*sc;}
}

typedef struct{
    char text[256];
    float x,y;
    float px;
    float r,g,b,a;
    uint8_t kind;
}MenuTextCmd;

typedef enum{
    MENU_TEXT_KIND_DISPLAY=0,
    MENU_TEXT_KIND_BODY=1,
}MenuTextKind;

typedef struct{
    bool tried;
    bool ready;
    GLuint prog,vao,vbo;
    TTF_Font *display_fonts[16];
    int display_font_px[16];
    int display_font_count;
    TTF_Font *body_fonts[16];
    int body_font_px[16];
    int body_font_count;
    MenuTextCmd cmds[512];
    int cmd_count;
}MenuTextSystem;

static MenuTextSystem g_menu_text={0};

static int menu_text_px(float sc){
    int px=(int)lroundf(sc*12.0f);
    if(px<12) px=12;
    if(px>128) px=128;
    return px;
}

static int hud_text_px(float sc){
    int px=(int)lroundf(sc*13.0f);
    if(px<12) px=12;
    if(px>72) px=72;
    return px;
}

static bool menu_text_init(void){
    if(g_menu_text.tried) return g_menu_text.ready;
    g_menu_text.tried=true;
    if(TTF_Init()!=0){
        printf("[MenuFont] TTF_Init failed: %s\n",TTF_GetError());
        return false;
    }
    g_menu_text.prog=GLH_program(
        "#version 330 core\n"
        "layout(location=0)in vec2 aPos;\n"
        "layout(location=1)in vec2 aUV;\n"
        "uniform mat4 uOrtho;\n"
        "out vec2 vUV;\n"
        "void main(){gl_Position=uOrtho*vec4(aPos,0,1);vUV=aUV;}\n",
        "#version 330 core\n"
        "in vec2 vUV;\n"
        "uniform sampler2D uTex;\n"
        "uniform vec4 uColor;\n"
        "out vec4 F;\n"
        "void main(){float a=texture(uTex,vUV).a;F=vec4(uColor.rgb,uColor.a*a);}\n");
    glGenVertexArrays(1,&g_menu_text.vao);
    glGenBuffers(1,&g_menu_text.vbo);
    glBindVertexArray(g_menu_text.vao);
    glBindBuffer(GL_ARRAY_BUFFER,g_menu_text.vbo);
    glBufferData(GL_ARRAY_BUFFER,sizeof(float)*24,NULL,GL_DYNAMIC_DRAW);
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0,2,GL_FLOAT,GL_FALSE,sizeof(float)*4,(void*)0);
    glEnableVertexAttribArray(1);
    glVertexAttribPointer(1,2,GL_FLOAT,GL_FALSE,sizeof(float)*4,(void*)(sizeof(float)*2));
    glBindBuffer(GL_ARRAY_BUFFER,0);
    glBindVertexArray(0);
    g_menu_text.ready=true;
    return true;
}

static TTF_Font *menu_text_get_font_kind(int px,MenuTextKind kind){
    if(!menu_text_init()) return NULL;
    TTF_Font **fonts=(kind==MENU_TEXT_KIND_BODY)?g_menu_text.body_fonts:g_menu_text.display_fonts;
    int *font_px=(kind==MENU_TEXT_KIND_BODY)?g_menu_text.body_font_px:g_menu_text.display_font_px;
    int *font_count=(kind==MENU_TEXT_KIND_BODY)?&g_menu_text.body_font_count:&g_menu_text.display_font_count;
    for(int i=0;i<*font_count;i++){
        if(font_px[i]==px) return fonts[i];
    }
    if(*font_count>=16) return fonts[*font_count-1];
    TTF_Font *font=NULL;
    if(kind==MENU_TEXT_KIND_BODY){
        static const char *body_candidates[]={
            "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "fonts/CinzelDecorative-Regular.ttf",
            NULL
        };
        for(int i=0;body_candidates[i]&&!font;i++) font=TTF_OpenFont(body_candidates[i],px);
    }else{
        static const char *display_candidates[]={
            "fonts/CinzelDecorative-Black.ttf",
            "fonts/CinzelDecorative-Bold.ttf",
            NULL
        };
        for(int i=0;display_candidates[i]&&!font;i++) font=TTF_OpenFont(display_candidates[i],px);
    }
    if(!font){
        printf("[MenuFont] Failed to open %s font at %dpx: %s\n",
               kind==MENU_TEXT_KIND_BODY?"body":"display",px,TTF_GetError());
        return NULL;
    }
    TTF_SetFontHinting(font,TTF_HINTING_NORMAL);
    font_px[*font_count]=px;
    fonts[*font_count]=font;
    (*font_count)++;
    return font;
}

static TTF_Font *menu_text_get_font(int px){
    return menu_text_get_font_kind(px,MENU_TEXT_KIND_DISPLAY);
}

static float menu_text_width(float sc,const char *text){
    TTF_Font *font=menu_text_get_font(menu_text_px(sc));
    if(!font) return sc*8.0f*(float)strlen(text);
    {
        int w=0,h=0;
        if(TTF_SizeUTF8(font,text,&w,&h)==0) return (float)w;
    }
    return sc*8.0f*(float)strlen(text);
}

static void menu_text_push(HUD *h,float x,float y,float sc,float px,const char *text,float r,float g,float b,float a,MenuTextKind kind){
    (void)h;
    if(!menu_text_init()||!menu_text_get_font_kind((int)px,kind)){
        hud_str_bitmap(h,x,y,sc,text,r,g,b,a);
        return;
    }
    if(g_menu_text.cmd_count>=512){
        hud_str_bitmap(h,x,y,sc,text,r,g,b,a);
        return;
    }
    MenuTextCmd *cmd=&g_menu_text.cmds[g_menu_text.cmd_count++];
    snprintf(cmd->text,sizeof(cmd->text),"%s",text);
    cmd->x=x; cmd->y=y; cmd->px=px;
    cmd->r=r; cmd->g=g; cmd->b=b; cmd->a=a;
    cmd->kind=(uint8_t)kind;
}

static void menu_text(HUD *h,float x,float y,float sc,const char *text,float r,float g,float b,float a){
    if(!text||!text[0]) return;
    menu_text_push(h,x,y,sc,(float)menu_text_px(sc),text,r,g,b,a,MENU_TEXT_KIND_DISPLAY);
}

static void hud_str(HUD *h,float x,float y,float sc,const char *s,float r,float g,float b,float a){
    if(!s||!s[0]) return;
    if(menu_text_init()&&menu_text_get_font_kind(hud_text_px(sc),MENU_TEXT_KIND_BODY)){
        const char *line=s;
        float cy=y;
        char buf[256];
        while(*line){
            size_t len=0;
            while(line[len]&&line[len]!='\n'&&len<sizeof(buf)-1) len++;
            memcpy(buf,line,len);
            buf[len]=0;
            if(len>0) menu_text_push(h,x,cy,sc,(float)hud_text_px(sc),buf,r,g,b,a,MENU_TEXT_KIND_BODY);
            cy+=9.0f*sc;
            line+=len;
            if(*line=='\n') line++;
        }
        return;
    }
    hud_str_bitmap(h,x,y,sc,s,r,g,b,a);
}

static void menu_text_flush(HUD *h){
    if(g_menu_text.cmd_count<=0) return;
    if(!menu_text_init()){ g_menu_text.cmd_count=0; return; }
    {
        float fw=(float)h->win_w,fh=(float)h->win_h;
        Mat4 o=mat4_identity();
        o.m[0]=2.0f/fw; o.m[5]=-2.0f/fh; o.m[12]=-1.0f; o.m[13]=1.0f;
        glUseProgram(g_menu_text.prog);
        GLH_mat4(g_menu_text.prog,"uOrtho",o.m);
        glUniform1i(glGetUniformLocation(g_menu_text.prog,"uTex"),0);
        glBindVertexArray(g_menu_text.vao);
        glDisable(GL_DEPTH_TEST);
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);
        for(int i=0;i<g_menu_text.cmd_count;i++){
            MenuTextCmd *cmd=&g_menu_text.cmds[i];
            TTF_Font *font=menu_text_get_font_kind((int)cmd->px,(MenuTextKind)cmd->kind);
            if(!font) continue;
            SDL_Color col={255,255,255,255};
            SDL_Surface *surf=TTF_RenderUTF8_Blended(font,cmd->text,col);
            if(!surf) continue;
            SDL_Surface *rgba=SDL_ConvertSurfaceFormat(surf,SDL_PIXELFORMAT_RGBA32,0);
            SDL_FreeSurface(surf);
            if(!rgba) continue;
            GLuint tex=0;
            glGenTextures(1,&tex);
            glActiveTexture(GL_TEXTURE0);
            glBindTexture(GL_TEXTURE_2D,tex);
            glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,rgba->w,rgba->h,0,GL_RGBA,GL_UNSIGNED_BYTE,rgba->pixels);
            glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);
            glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
            glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);
            glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
            glUniform4f(glGetUniformLocation(g_menu_text.prog,"uColor"),cmd->r,cmd->g,cmd->b,cmd->a);
            {
                float x=cmd->x, y=cmd->y;
                float w=(float)rgba->w, ht=(float)rgba->h;
                float vtx[24]={
                    x,    y,     0.0f,0.0f,
                    x+w,  y,     1.0f,0.0f,
                    x+w,  y+ht,  1.0f,1.0f,
                    x,    y,     0.0f,0.0f,
                    x+w,  y+ht,  1.0f,1.0f,
                    x,    y+ht,  0.0f,1.0f
                };
                glBindBuffer(GL_ARRAY_BUFFER,g_menu_text.vbo);
                glBufferSubData(GL_ARRAY_BUFFER,0,sizeof(vtx),vtx);
                glDrawArrays(GL_TRIANGLES,0,6);
            }
            glDeleteTextures(1,&tex);
            SDL_FreeSurface(rgba);
        }
        glDisable(GL_BLEND);
        glEnable(GL_DEPTH_TEST);
        glDepthFunc(GL_LESS);
        glDepthMask(GL_TRUE);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glBindVertexArray(0);
        glUseProgram(0);
    }
    g_menu_text.cmd_count=0;
}

