static void skilltree_draw(SkillTree *st,HUD *h,int win_w,int win_h,Player *pl){
    if(!st||!st->open) return;

    const float W=(float)win_w,H=(float)win_h;
    const float pw=560.0f,ph=420.0f;
    const float px=(W-pw)*0.5f,py=(H-ph)*0.5f;
    int mx=0,my=0;
    SDL_GetMouseState(&mx,&my);

    hud_rect(h,0,0,W,H,0,0,0,0.55f);
    hud_rect(h,px,py,pw,ph,0.08f,0.09f,0.11f,0.96f);
    hud_rect(h,px,py,pw,3.0f,0.85f,0.65f,0.18f,1.0f);
    hud_rect(h,px,py+ph-3.0f,pw,3.0f,0.85f,0.65f,0.18f,1.0f);

    hud_str(h,px+22.0f,py+18.0f,1.5f,"SKILL TREE",0.98f,0.92f,0.78f,1.0f);
    {
        char subtitle[96];
        const PlayerClassProfile *cp=player_class_profile(pl?pl->class_id:PLAYER_CLASS_WARRIOR);
        snprintf(subtitle,sizeof(subtitle),"%s  POINTS: %d",cp->title,st->available_points);
        hud_str(h,px+22.0f,py+42.0f,1.0f,subtitle,0.72f,0.76f,0.82f,1.0f);
    }

    for(int i=0;i<SKILL_NODE_COUNT;i++){
        float rx,ry,rw,rh,bx,by,bw,bh;
        float btn_r=0.20f,btn_g=0.24f,btn_b=0.28f;
        bool can_buy=st->available_points>0&&st->ranks[i]<SKILL_RANK_CAP;
        bool hovered=false;
        char rank_buf[32];

        skilltree_row_layout(win_w,win_h,i,&rx,&ry,&rw,&rh,&bx,&by,&bw,&bh);
        hovered=mx>=bx&&mx<=bx+bw&&my>=by&&my<=by+bh;

        hud_rect(h,rx,ry,rw,rh,0.13f,0.14f,0.17f,0.95f);
        hud_rect(h,rx,ry,6.0f,rh,0.85f,0.65f,0.18f,1.0f);
        hud_str(h,rx+16.0f,ry+8.0f,1.15f,SKILL_NODE_NAMES[i],0.96f,0.96f,0.96f,1.0f);
        hud_str(h,rx+16.0f,ry+25.0f,0.9f,SKILL_NODE_DESCS[i],0.72f,0.76f,0.82f,1.0f);

        snprintf(rank_buf,sizeof(rank_buf),"%d/%d",st->ranks[i],SKILL_RANK_CAP);
        hud_str(h,rx+rw-88.0f,ry+15.0f,1.0f,rank_buf,0.94f,0.83f,0.52f,1.0f);

        if(can_buy){
            btn_r=hovered?0.34f:0.26f;
            btn_g=hovered?0.56f:0.45f;
            btn_b=hovered?0.32f:0.24f;
        }
        hud_rect(h,bx,by,bw,bh,btn_r,btn_g,btn_b,1.0f);
        hud_str(h,bx+bw*0.5f-4.0f,by+6.0f,1.4f,"+",can_buy?0.98f:0.58f,can_buy?0.98f:0.58f,can_buy?0.98f:0.58f,1.0f);
    }

    hud_str(h,px+22.0f,py+ph-28.0f,1.0f,"[K] Close  [Click +] Spend point",0.82f,0.84f,0.88f,1.0f);
}
static void appearance_draw(PlayerAppearance *ap,HUD *h,int win_w,int win_h){
    if(!ap||!ap->open) return;
    {
        const float W=(float)win_w,H=(float)win_h;
        const float pw=520.0f,ph=360.0f;
        const float px=(W-pw)*0.5f,py=(H-ph)*0.5f;
        const float sbx=px+pw-120.0f,sby=py+ph-48.0f,sbw=92.0f,sbh=30.0f;
        int mx=0,my=0;
        bool hov=false;
        SDL_GetMouseState(&mx,&my);
        hov=mx>=sbx&&mx<=sbx+sbw&&my>=sby&&my<=sby+sbh;
        hud_rect(h,0,0,W,H,0,0,0,0.45f);
        hud_rect(h,px,py,pw,ph,0.09f,0.07f,0.05f,0.96f);
        hud_rect(h,px,py,pw,3.0f,0.88f,0.62f,0.20f,1.0f);
        hud_str(h,px+18.0f,py+16.0f,1.5f,"APPEARANCE",0.98f,0.90f,0.78f,1.0f);
        hud_str(h,px+18.0f,py+36.0f,1.0f,"[TAB] Slot  [R/F][G/V][B/N] RGB  [J] Cancel",0.74f,0.78f,0.82f,0.94f);
        for(int i=0;i<APPEARANCE_COLOR_SLOTS;i++){
            float ry=py+70.0f+(float)i*50.0f;
            float cr=(float)ap->rgb[i][0]/255.0f;
            float cg=(float)ap->rgb[i][1]/255.0f;
            float cb=(float)ap->rgb[i][2]/255.0f;
            char buf[48];
            hud_rect(h,px+18.0f,ry,pw-36.0f,40.0f,i==ap->selected_slot?0.18f:0.12f,i==ap->selected_slot?0.14f:0.10f,0.08f,0.95f);
            hud_rect(h,px+18.0f,ry,6.0f,40.0f,cr,cg,cb,1.0f);
            hud_rect(h,px+320.0f,ry+6.0f,120.0f,28.0f,cr,cg,cb,1.0f);
            hud_str(h,px+34.0f,ry+12.0f,1.2f,APPEARANCE_SLOT_NAMES[i],0.95f,0.95f,0.95f,1.0f);
            snprintf(buf,sizeof(buf),"R%03d G%03d B%03d",ap->rgb[i][0],ap->rgb[i][1],ap->rgb[i][2]);
            hud_str(h,px+168.0f,ry+12.0f,1.0f,buf,0.86f,0.84f,0.76f,1.0f);
        }
        hud_rect(h,sbx,sby,sbw,sbh,hov?0.30f:0.20f,hov?0.44f:0.32f,hov?0.20f:0.12f,1.0f);
        hud_str(h,sbx+20.0f,sby+8.0f,1.2f,"SAVE",0.96f,0.98f,0.92f,1.0f);
    }
}
/* Minimap: 160×160 top-down overview, bottom-right corner */
static void minimap_draw(HUD *h,Vec3 ppos,float pyaw,Enemy *enemies,int ne,QuestSystem *qs,Vec3 campfire_pos){
    const float MS=160.0f,MX=(float)h->win_w-MS-10.0f,MY=(float)h->win_h-MS-10.0f;
    const float WR=600.0f; /* world units shown – ~1.2km view radius */
    hud_rect(h,MX-2,MY-2,MS+4,MS+4,0,0,0,0.85f);
    /* Terrain color grid (4px cells = 40×40 = 1600 quads) */
    int cells=40;float cell_px=MS/cells,cell_wu=WR*2.0f/cells;
    for(int gz=0;gz<cells;gz++)for(int gx=0;gx<cells;gx++){
        float wx=ppos.x+(gx-cells/2+0.5f)*cell_wu;
        float wz=ppos.z+(gz-cells/2+0.5f)*cell_wu;
        Vec3 tc=terrain_color_at(wx,wz,terrain_h(wx,wz));
        hud_rect(h,MX+gx*cell_px,MY+gz*cell_px,cell_px+0.5f,cell_px+0.5f,tc.x*0.7f,tc.y*0.7f,tc.z*0.7f,0.9f);
    }
    /* Helper macros: world→minimap pixel */
    #define W2MX(wx) (MX+((wx)-ppos.x+WR)/WR*0.5f*MS)
    #define W2MZ(wz) (MY+((wz)-ppos.z+WR)/WR*0.5f*MS)
    /* Quest reach markers (yellow diamond) */
    for(int i=0;i<qs->count;i++){Quest *q=&qs->quests[i];if(q->status!=Q_ACTIVE)continue;
        for(int j=0;j<q->obj_count;j++){Objective *o=&q->objs[j];if(o->type!=OBJ_REACH||o->done)continue;
            float ox=W2MX(o->loc.x),oz=W2MZ(o->loc.z);hud_rect(h,ox-5,oz-5,10,10,1,1,0,0.9f);}}
    /* Campfire (orange) */
    {float cx=W2MX(campfire_pos.x),cz=W2MZ(campfire_pos.z);hud_rect(h,cx-4,cz-4,8,8,1.0f,0.45f,0.1f,0.95f);}
    /* Enemies (red) */
    for(int i=0;i<ne;i++){Enemy *e=&enemies[i];if(!e->active||e->state==ES_DEAD)continue;
        float ex=W2MX(e->phys.pos.x),ez=W2MZ(e->phys.pos.z);
        if(ex>=MX&&ex<MX+MS&&ez>=MY&&ez<MY+MS)hud_rect(h,ex-4,ez-4,8,8,0.9f,0.1f,0.1f,0.95f);}
    /* Player dot + direction arrow */
    hud_rect(h,MX+MS/2-4,MY+MS/2-4,8,8,1,1,1,1);
    {float ax=MX+MS/2-sinf(pyaw)*10,az=MY+MS/2+cosf(pyaw)*10;hud_rect(h,ax-2,az-2,4,4,0.7f,0.7f,1,0.9f);}
    /* Border */
    hud_rect(h,MX,MY,MS,1,0.6f,0.6f,0.6f,0.8f);hud_rect(h,MX,MY+MS-1,MS,1,0.6f,0.6f,0.6f,0.8f);
    hud_rect(h,MX,MY,1,MS,0.6f,0.6f,0.6f,0.8f);hud_rect(h,MX+MS-1,MY,1,MS,0.6f,0.6f,0.6f,0.8f);
    /* "MAP" label */
    hud_str(h,MX+MS/2-13,MY-12,1.0f,"MAP",0.8f,0.8f,0.8f,0.8f);
    #undef W2MX
    #undef W2MZ
}

