static void world_fx_editor_reset(WorldFxEditor *ed){
    WorldFx fx;
    if(!ed) return;
    world_fx_apply_defaults(&fx,WORLD_FX_FIRE);
    ed->kind=fx.kind;
    ed->scale=fx.scale;
    ed->height=fx.height;
    ed->intensity=fx.intensity;
    ed->color=fx.color;
    ed->light_enabled=fx.light_enabled;
    ed->light_color=fx.light_color;
    ed->light_radius=fx.light_radius;
    ed->light_intensity=fx.light_intensity;
    ed->has_ghost=false;
}

static void world_fx_editor_sync_from_fx(WorldFxEditor *ed,const WorldFx *fx){
    if(!ed||!fx) return;
    ed->kind=fx->kind;
    ed->scale=fx->scale;
    ed->height=fx->height;
    ed->intensity=fx->intensity;
    ed->color=fx->color;
    ed->light_enabled=fx->light_enabled;
    ed->light_color=fx->light_color;
    ed->light_radius=fx->light_radius;
    ed->light_intensity=fx->light_intensity;
}

static void world_fx_sync_to_selected(WorldFxSystem *sys,WorldFxEditor *ed){
    WorldFx *fx;
    if(!sys||!ed||sys->selected<0||sys->selected>=sys->count) return;
    fx=&sys->items[sys->selected];
    if(!fx->active) return;
    fx->kind=ed->kind;
    fx->scale=ed->scale;
    fx->height=ed->height;
    fx->intensity=ed->intensity;
    fx->color=ed->color;
    fx->light_enabled=ed->light_enabled;
    fx->light_color=ed->light_color;
    fx->light_radius=ed->light_radius;
    fx->light_intensity=ed->light_intensity;
}

static bool world_fx_apply_editor_live(WorldFxSystem *sys,LightingSystem *ls,const WorldFxEditor *ed){
    WorldFx before;
    WorldFx *fx;
    if(!sys||!ls||!ed||sys->selected<0||sys->selected>=sys->count) return false;
    fx=&sys->items[sys->selected];
    if(!fx->active) return false;
    before=*fx;
    world_fx_sync_to_selected(sys,(WorldFxEditor*)ed);
    if(!before.light_enabled && fx->light_enabled) world_fx_add_light(fx,ls);
    else if(before.light_enabled && !fx->light_enabled) world_fx_disable_light(fx,ls);
    if(fx->light_enabled&&fx->light_idx>=0&&fx->light_idx<ls->num_points){
        PointLight *pl=&ls->points[fx->light_idx];
        pl->pos=(Vec3){fx->pos.x,fx->pos.y+0.65f*fx->height,fx->pos.z};
        pl->color=fx->light_color;
        pl->radius=fx->light_radius;
        pl->intensity=fx->light_intensity;
    }
    return memcmp(&before,fx,sizeof(before))!=0;
}

static int world_fx_pick_nearest(WorldFxSystem *sys,Vec3 hit,float max_dist){
    float best=max_dist*max_dist;
    int bi=-1;
    if(!sys) return -1;
    for(int i=0;i<sys->count;i++){
        WorldFx *fx=&sys->items[i];
        if(!fx->active) continue;
        {
            float dx=fx->pos.x-hit.x,dz=fx->pos.z-hit.z;
            float d2=dx*dx+dz*dz;
            if(d2<best){best=d2;bi=i;}
        }
    }
    return bi;
}

static int world_fx_alloc(WorldFxSystem *sys){
    if(!sys) return -1;
    for(int i=0;i<WORLD_FX_MAX;i++){
        if(!sys->items[i].active){
            if(i>=sys->count) sys->count=i+1;
            return i;
        }
    }
    return -1;
}

static bool placer_has_supported_ext(const char *name){
    const char *dot=strrchr(name,'.');
    char ext[8];
    size_t i=0;
    if(!dot||dot[1]=='\0') return false;
    dot++;
    for(;dot[i]&&i<sizeof(ext)-1;i++) ext[i]=(char)tolower((unsigned char)dot[i]);
    ext[i]='\0';
    return strcmp(ext,"fbx")==0||strcmp(ext,"glb")==0||strcmp(ext,"gltf")==0;
}

static bool placer_palette_add(PropPlacer *pp,const char *path){
    if(!pp||!path||pp->palette_count>=PROP_PALETTE_MAX) return false;
    for(int i=0;i<pp->palette_count;i++){
        if(strcmp(pp->palette[i],path)==0) return false;
    }
    snprintf(pp->palette[pp->palette_count],256,"%s",path);
    pp->palette_count++;
    return true;
}

static bool str_contains_ci(const char *haystack,const char *needle){
    size_t nlen;
    if(!haystack||!needle) return false;
    if(needle[0]=='\0') return true;
    nlen=strlen(needle);
    for(const char *h=haystack;*h;h++){
        size_t i=0;
        while(i<nlen&&h[i]&&tolower((unsigned char)h[i])==tolower((unsigned char)needle[i])) i++;
        if(i==nlen) return true;
    }
    return false;
}

enum{
    BROWSER_CAT_ALL=0,
    BROWSER_CAT_STRUCTURE,
    BROWSER_CAT_NATURE,
    BROWSER_CAT_PROP,
    BROWSER_CAT_LIGHTING,
    BROWSER_CAT_GAMEPLAY,
    BROWSER_CAT_COUNT
};

static const char *browser_category_name(int cat){
    switch(cat){
        case BROWSER_CAT_STRUCTURE: return "Structure";
        case BROWSER_CAT_NATURE: return "Nature";
        case BROWSER_CAT_PROP: return "Set Dressing";
        case BROWSER_CAT_LIGHTING: return "Lighting / FX";
        case BROWSER_CAT_GAMEPLAY: return "Gameplay";
        case BROWSER_CAT_ALL:
        default: return "All";
    }
}

static int browser_category_for_path(const char *path){
    if(!path) return BROWSER_CAT_PROP;
    if(str_contains_ci(path,"house")||str_contains_ci(path,"tower")||str_contains_ci(path,"wall")||
       str_contains_ci(path,"fence")||str_contains_ci(path,"bridge")||str_contains_ci(path,"stairs")||
       str_contains_ci(path,"gate")||str_contains_ci(path,"door")||str_contains_ci(path,"arch")||
       str_contains_ci(path,"pillar")||str_contains_ci(path,"building")||str_contains_ci(path,"ruin"))
        return BROWSER_CAT_STRUCTURE;
    if(str_contains_ci(path,"tree")||str_contains_ci(path,"grass")||str_contains_ci(path,"flower")||
       str_contains_ci(path,"rock")||str_contains_ci(path,"boulder")||str_contains_ci(path,"cliff")||
       str_contains_ci(path,"bush")||str_contains_ci(path,"fern")||str_contains_ci(path,"vine"))
        return BROWSER_CAT_NATURE;
    if(str_contains_ci(path,"torch")||str_contains_ci(path,"lantern")||str_contains_ci(path,"fire")||
       str_contains_ci(path,"light")||str_contains_ci(path,"fx")||str_contains_ci(path,"portal"))
        return BROWSER_CAT_LIGHTING;
    if(str_contains_ci(path,"spawn")||str_contains_ci(path,"marker")||str_contains_ci(path,"trigger")||
       str_contains_ci(path,"collision")||str_contains_ci(path,"quest")||str_contains_ci(path,"gameplay"))
        return BROWSER_CAT_GAMEPLAY;
    return BROWSER_CAT_PROP;
}

static const char *browser_tags_for_path(const char *path,char *buf,size_t buf_sz){
    const char *ext;
    int cat;
    if(!buf||buf_sz==0) return "";
    buf[0]=0;
    if(!path||!path[0]) return "";
    cat=browser_category_for_path(path);
    snprintf(buf,buf_sz,"%s",browser_category_name(cat));
    if(str_contains_ci(path,"interior")||str_contains_ci(path,"apartment")||str_contains_ci(path,"room"))
        strncat(buf," interior",buf_sz-strlen(buf)-1);
    if(str_contains_ci(path,"shire")||str_contains_ci(path,"village")||str_contains_ci(path,"farm"))
        strncat(buf," world",buf_sz-strlen(buf)-1);
    if(str_contains_ci(path,"collision")||str_contains_ci(path,"stairs")||str_contains_ci(path,"bridge"))
        strncat(buf," collision",buf_sz-strlen(buf)-1);
    ext=strrchr(path,'.');
    if(ext){
        strncat(buf," ",buf_sz-strlen(buf)-1);
        strncat(buf,ext+1,buf_sz-strlen(buf)-1);
    }
    return buf;
}

static bool browser_asset_valid(const char *path){
    struct stat st;
    if(!path||!path[0]) return false;
    return stat(path,&st)==0&&S_ISREG(st.st_mode);
}

static bool browser_recent_flag(int recent_serial,int current_counter){
    if(recent_serial<=0||current_counter<=0) return false;
    return (current_counter-recent_serial)<=8;
}

static void placer_mark_recent(PropPlacer *pp,int palette_idx){
    if(!pp||palette_idx<0||palette_idx>=pp->palette_count) return;
    pp->recent_serial[palette_idx]=++pp->recent_counter;
}

static void prefab_mark_recent(PrefabLibrary *lib,int prefab_idx){
    if(!lib||prefab_idx<0||prefab_idx>=lib->count) return;
    lib->items[prefab_idx].recent_serial=++lib->recent_counter;
}

static const char *placer_selected_model(const PropPlacer *pp);
static void placer_apply_selected_defaults(PropPlacer *pp);

static void placer_rebuild_filter(PropPlacer *pp){
    if(!pp) return;
    pp->filtered_count=0;
    for(int i=0;i<pp->palette_count;i++){
        const char *full=pp->palette[i];
        const char *name=strrchr(full,'/');
        int cat=browser_category_for_path(full);
        name=name?name+1:full;
        if(pp->filter_favorites_only&&!pp->favorite[i]) continue;
        if(pp->filter_recent_only&&!browser_recent_flag(pp->recent_serial[i],pp->recent_counter)) continue;
        if(pp->category_filter>0&&cat!=pp->category_filter) continue;
        if(pp->search[0]=='\0'||str_contains_ci(full,pp->search)||str_contains_ci(name,pp->search)){
            pp->filtered[pp->filtered_count++]=i;
        }
    }
    if(pp->filtered_count<=0){
        pp->palette_sel=0;
        pp->palette_scroll=0;
        return;
    }
    if(pp->palette_sel>=pp->filtered_count) pp->palette_sel=pp->filtered_count-1;
    if(pp->palette_sel<0) pp->palette_sel=0;
    if(pp->palette_scroll>pp->palette_sel) pp->palette_scroll=pp->palette_sel;
    if(pp->palette_scroll<0) pp->palette_scroll=0;
    placer_apply_selected_defaults(pp);
}

static const char *placer_selected_model(const PropPlacer *pp){
    int idx;
    if(!pp||pp->filtered_count<=0||pp->palette_sel<0||pp->palette_sel>=pp->filtered_count) return NULL;
    idx=pp->filtered[pp->palette_sel];
    if(idx<0||idx>=pp->palette_count) return NULL;
    return pp->palette[idx];
}

static int placer_path_depth(const char *path){
    int depth=0;
    if(!path) return 0;
    for(const char *c=path;*c;c++) if(*c=='/'||*c=='\\') depth++;
    return depth;
}

static int placer_palette_cmp(const void *a,const void *b){
    const char *pa=(const char *)a;
    const char *pb=(const char *)b;
    int da=placer_path_depth(pa);
    int db=placer_path_depth(pb);
    if(da!=db) return da-db;
    return strcmp(pa,pb);
}

static const char *prop_coll_name(PropCollType coll){
    switch(coll){
        case PROP_COLL_NONE: return "None";
        case PROP_COLL_AABB: return "AABB";
        case PROP_COLL_MESH: return "Mesh";
        default: return "Unknown";
    }
}

static void prop_apply_collision_mode(int prop_idx,PropCollType coll){
    if(prop_idx<0||prop_idx>=g_props.count) return;
    {
        Prop *p=&g_props.list[prop_idx];
        if(!p->active) return;
        p->coll_type=coll;
        if(!prop_uses_scene_renderer(p)){
            if(p->stream_state==PROP_LOADED) prop_unload_gpu(p);
            if(p->coll_type!=PROP_COLL_NONE||prop_has_custom_collision(p)) stream_request(&g_stream,prop_idx);
        }else{
            prop_refresh_collision(p);
        }
        if(g_placer.selected_prop==prop_idx) g_placer.place_coll=p->coll_type;
        printf("[PropEdit] Prop %d collision -> %s\n",prop_idx,prop_coll_name(p->coll_type));
    }
}

static PropCollType placer_default_coll_type(const char *path){
    if(!path) return PROP_COLL_AABB;
    if(str_contains_ci(path,"bridge")||str_contains_ci(path,"deck")||str_contains_ci(path,"stairs")||
       str_contains_ci(path,"steps")||str_contains_ci(path,"ramp")||str_contains_ci(path,"platform")||
       str_contains_ci(path,"pier")||str_contains_ci(path,"dock"))
        return PROP_COLL_MESH;
    if(str_contains_ci(path,"torch")||str_contains_ci(path,"fire")||str_contains_ci(path,"lantern")||
       str_contains_ci(path,"barrel")||str_contains_ci(path,"crate")||str_contains_ci(path,"bench")||
       str_contains_ci(path,"grass")||str_contains_ci(path,"flower"))
        return PROP_COLL_NONE;
    return PROP_COLL_AABB;
}

static bool placer_is_boulder_source(const char *path){
    if(!path) return false;
    return str_contains_ci(path,"boulder")||str_contains_ci(path,"rock")||
           str_contains_ci(path,"stone")||str_contains_ci(path,"cliff")||
           str_contains_ci(path,"rubble")||str_contains_ci(path,"pebble");
}

static void placer_apply_selected_defaults(PropPlacer *pp){
    const char *path=placer_selected_model(pp);
    if(!pp||!path) return;
    pp->place_coll=placer_default_coll_type(path);
}

#if defined(_WIN32)
static void placer_scan_models_dir_win(PropPlacer *pp,const char *dir){
    char pattern[512];
    WIN32_FIND_DATAA fd;
    HANDLE h;
    snprintf(pattern,sizeof(pattern),"%s\\*",dir);
    h=FindFirstFileA(pattern,&fd);
    if(h==INVALID_HANDLE_VALUE) return;
    do{
        if(strcmp(fd.cFileName,".")==0||strcmp(fd.cFileName,"..")==0) continue;
        if(fd.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY){
            char child[512];
            snprintf(child,sizeof(child),"%s\\%s",dir,fd.cFileName);
            placer_scan_models_dir_win(pp,child);
        }else if(placer_has_supported_ext(fd.cFileName)){
            char path[512];
            snprintf(path,sizeof(path),"%s/%s",dir,fd.cFileName);
            for(char *c=path;*c;c++) if(*c=='\\') *c='/';
            placer_palette_add(pp,path);
        }
    }while(pp->palette_count<PROP_PALETTE_MAX&&FindNextFileA(h,&fd));
    FindClose(h);
}
#else
static void placer_scan_models_dir_posix(PropPlacer *pp,const char *dir){
    #include <dirent.h>
    DIR *d=opendir(dir);
    if(!d) return;
    struct dirent *ent;
    while((ent=readdir(d))!=NULL&&pp->palette_count<PROP_PALETTE_MAX){
        char path[512];
        struct stat st;
        const char *n=ent->d_name;
        if(strcmp(n,".")==0||strcmp(n,"..")==0) continue;
        if(n[0]=='.') continue;
        snprintf(path,sizeof(path),"%s/%s",dir,n);
        if(stat(path,&st)!=0) continue;
        if(S_ISDIR(st.st_mode)){
            placer_scan_models_dir_posix(pp,path);
        }else if(placer_has_supported_ext(n)){
            placer_palette_add(pp,path);
        }
    }
    closedir(d);
}
#endif

static int props_pick_nearest(PropList *pl,Vec3 hit,float max_dist){
    float best=max_dist*max_dist;
    int bi=-1;
    if(!pl) return -1;
    for(int i=0;i<pl->count;i++){
        Prop *p=&pl->list[i];
        if(!p->active) continue;
        {
            float dx=p->pos.x-hit.x,dz=p->pos.z-hit.z;
            float d2=dx*dx+dz*dz;
            if(d2<best){best=d2;bi=i;}
        }
    }
    return bi;
}

static int props_pick_screen(PropList *pl,int mx,int my,int win_w,int win_h,Mat4 proj,Mat4 view,float max_px){
    float best=max_px*max_px;
    int bi=-1;
    if(!pl) return -1;
    for(int i=0;i<pl->count;i++){
        Prop *p=&pl->list[i];
        if(!p->active) continue;
        {
            float sx,sy;
            Vec3 anchor={p->pos.x,p->pos.y+fmaxf(1.0f,p->scale*1.2f),p->pos.z};
            if(!world_to_ndc(anchor,proj,view,&sx,&sy)) continue;
            {
                float px=(sx*0.5f+0.5f)*(float)win_w;
                float py=(1.0f-(sy*0.5f+0.5f))*(float)win_h;
                float dx=px-(float)mx;
                float dy=py-(float)my;
                float d2=dx*dx+dy*dy;
                if(d2<best){ best=d2; bi=i; }
            }
        }
    }
    return bi;
}

static int props_first_active(PropList *pl){
    if(!pl) return -1;
    for(int i=0;i<pl->count;i++) if(pl->list[i].active) return i;
    return -1;
}

static int props_next_active(PropList *pl,int start){
    if(!pl||pl->count<=0) return -1;
    for(int step=1;step<=pl->count;step++){
        int idx=(start+step)%pl->count;
        if(pl->list[idx].active) return idx;
    }
    return -1;
}

static int g_thumbnail_budget=4;
static unsigned g_thumbnail_generation;
static GLuint placer_thumb_pixels(uint8_t *px,int w,int h){
    if(!px) return 0;
    while(w>192||h>192){
        int nw=w>1?w/2:1,nh=h>1?h/2:1; uint8_t *small=rgba_downsample_half(px,w,h);
        if(!small) break;
        stbi_image_free(px); px=small; w=nw; h=nh;
    }
    GLuint tex=0;
    glGenTextures(1,&tex);
    glBindTexture(GL_TEXTURE_2D,tex);
    glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,px);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
    stbi_image_free(px);
    return tex;
}

static void placer_thumbnail_pump(PropPlacer *pp){
    ThumbnailResult result;
    // At most one small GL upload per frame; file IO, parse and decode stay on the worker.
    if(thumbnail_poll(&result)){
        if(result.generation==g_thumbnail_generation&&result.index>=0&&result.index<pp->palette_count)
            pp->thumb_tex[result.index]=placer_thumb_pixels(result.pixels,result.width,result.height);
        else stbi_image_free(result.pixels);
    }
}

static void placer_sync_from_prop(PropPlacer *pp,const Prop *p){
    if(!pp||!p) return;
    pp->place_ry=p->rot_y;
    pp->place_scale=p->scale;
    pp->place_coll=p->coll_type;
}

/* Scan models/ directory recursively for supported model files and populate palette */
static void placer_scan_models(PropPlacer *pp){
    g_thumbnail_generation=thumbnail_new_generation();
    pp->palette_count=0;
#if defined(_WIN32)
    placer_scan_models_dir_win(pp,"models");
    placer_scan_models_dir_win(pp,"imports/models");
    placer_scan_models_dir_win(pp,"assets/models");
#else
    placer_scan_models_dir_posix(pp,"models");
    placer_scan_models_dir_posix(pp,"imports/models");
    placer_scan_models_dir_posix(pp,"assets/models");
    if(pp->palette_count==0){
        /* No models/ dir — seed with some common names so editor isn't empty */
        const char *defaults[]={"models/village/House_FBX/House_1/House_1.fbx","models/village/Tree_FBX/Birch1.fbx",
            "models/barrel/barrel.fbx","models/village/Benches/Crate.fbx","models/torch.fbx",
            "models/well.fbx","models/village/Fence/fence_1.fbx","models/tower.fbx",NULL};
        for(int i=0;defaults[i]&&pp->palette_count<PROP_PALETTE_MAX;i++){
            placer_palette_add(pp,defaults[i]);
        }
    }
#endif
    if(pp->palette_count>1)
        qsort(pp->palette,(size_t)pp->palette_count,sizeof(pp->palette[0]),placer_palette_cmp);
    if(pp->palette_count==0){
        /* ultimate fallback */
        strncpy(pp->palette[0],"models/house.fbx",255);
        pp->palette_count=1;
    }
    for(int i=0;i<PROP_PALETTE_MAX;i++){
        if(pp->thumb_tex[i]){ glDeleteTextures(1,&pp->thumb_tex[i]); pp->thumb_tex[i]=0; }
        pp->thumb_attempted[i]=false;
    }
    /* Thumbnails are loaded for visible browser entries, never for the entire
       multi-gigabyte library during startup. */
    pp->search[0]='\0';
    placer_rebuild_filter(pp);
    printf("[PropPlacer] Found %d models in palette\n",pp->palette_count);
}

static void placer_init(PropPlacer *pp){
    memset(pp,0,sizeof(*pp));
    pp->place_scale=1.0f;
    pp->place_coll=PROP_COLL_AABB;
    pp->snap_y=true;
    pp->prefab_sel=0;
    pp->prefab_capture_radius=10.0f;
    pp->bulk_scatter_radius=12.0f;
    pp->bulk_scatter_count=8;
    pp->bulk_path_spacing=4.0f;
    pp->selected_prop=-1;
    pp->search[0]='\0';
    pp->search_focus=false;
    pp->filtered_count=0;
    placer_scan_models(pp);
}

static bool editor_import_model(PropPlacer *placer,const char *source,char *message,size_t capacity){
    cgltf_options options={0};
    cgltf_data *data=NULL;
    char destination[256];
    if(!source||cgltf_parse_file(&options,source,&data)!=cgltf_result_success){
        snprintf(message,capacity,"Could not parse model. Choose a valid GLB 2.0 file.");
        return false;
    }
    bool valid=cgltf_load_buffers(&options,data,source)==cgltf_result_success&&cgltf_validate(data)==cgltf_result_success;
    for(size_t i=0;i<data->buffers_count;i++) if(data->buffers[i].uri&&strncmp(data->buffers[i].uri,"data:",5)) valid=false;
    for(size_t i=0;i<data->images_count;i++) if(data->images[i].uri&&strncmp(data->images[i].uri,"data:",5)) valid=false;
    cgltf_free(data);
    if(!valid){snprintf(message,capacity,"Use a valid GLB with embedded meshes and textures.");return false;}
    if(!engine_project_import_glb(source,destination,sizeof(destination),message,capacity)) return false;
    placer_scan_models(placer);
    for(int i=0;i<placer->filtered_count;i++){
        if(!strcmp(placer->palette[placer->filtered[i]],destination)){
            placer->palette_sel=i;
            placer_apply_selected_defaults(placer);
            break;
        }
    }
    return true;
}

static PropList g_scene_prop_store[SCENE_COUNT];
static SceneID  g_props_active_scene=SCENE_SHIRE;
static bool     g_scene_prop_store_loaded[SCENE_COUNT]={false};
static void     placer_load(PropList *pl);

static const char *scene_prop_file(SceneID scene){
    switch(scene){
        case SCENE_APARTMENT: return APARTMENT_PROP_PLACER_FILE;
        case SCENE_SHIRE:
        default: return PROP_PLACER_FILE;
    }
}

static SceneID scene_id_for_props(const PropList *pl){
    if(pl==&g_props) return g_props_active_scene;
    if(pl==&g_scene_prop_store[SCENE_APARTMENT]) return SCENE_APARTMENT;
    if(pl==&g_scene_prop_store[SCENE_SHIRE]) return SCENE_SHIRE;
    return g_props_active_scene;
}

static bool scene_props_preload_immediate(SceneID scene){
    /* Apartment startup should not force every interior prop to fully load at
       once. Streaming avoids a large one-frame CPU/RAM spike on scene entry. */
    (void)scene;
    return false;
}

static void scene_props_apply_overrides(PropList *pl){
    if(!pl) return;
    {
        const char *mesh_props[]={"house.fbx","steps.fbx","tower.fbx","house_large.fbx","House_1.fbx",NULL};
        for(int pi=0;pi<pl->count;pi++){
            Prop *p=&pl->list[pi];
            for(int mi=0;mesh_props[mi];mi++){
                if(strstr(p->path,mesh_props[mi])){
                    p->coll_type=PROP_COLL_MESH;
                    break;
                }
            }
        }
    }
}

static void collision_volumes_activate(SceneID scene);

static const char *scene_name(SceneID scene){
    switch(scene){
        case SCENE_APARTMENT: return "Apartment";
        case SCENE_SHIRE: return "Shire";
        default: return "Unknown";
    }
}

static void stream_rebind(StreamSystem *ss,PropList *pl){
    if(!ss||!ss->mutex) return;
    printf("[Stream] Rebind -> %s props=%d\n",scene_name(scene_id_for_props(pl)),pl?pl->count:0);
    SDL_LockMutex(ss->mutex);
    ss->generation++;
    while(ss->rdy_count>0){
        StreamJob *job=ss->ready[ss->rdy_head%STREAM_QUEUE_CAP];
        ss->rdy_head++;
        ss->rdy_count--;
        stream_job_free(job);
    }
    ss->req_head=ss->req_tail=ss->req_count=0;
    ss->props=pl;
    SDL_UnlockMutex(ss->mutex);
}

static void props_prepare_for_storage(PropList *pl){
    if(!pl) return;
    for(int i=0;i<pl->count;i++){
        Prop *p=&pl->list[i];
        if(!p->active) continue;
        if(p->ready_job){
            stream_job_free(p->ready_job);
            p->ready_job=NULL;
        }
        if(p->stream_state==PROP_QUEUED||p->stream_state==PROP_READY||p->stream_state==PROP_UPLOADING){
            if(p->num_meshes>0) prop_unload_gpu(p);
            else{
                trimesh_free(&p->trimesh);
                p->stream_state=PROP_UNLOADED;
            }
        }
    }
}

static void scene_props_activate(SceneID scene){
    if(scene<0||scene>=SCENE_COUNT||scene==g_props_active_scene) return;
    if(!g_scene_prop_store_loaded[scene]){
        placer_load(&g_scene_prop_store[scene]);
        scene_props_apply_overrides(&g_scene_prop_store[scene]);
        g_scene_prop_store_loaded[scene]=true;
    }
    printf("[SceneProps] Activate %s (from %s)\n",scene_name(scene),scene_name(g_props_active_scene));
    props_prepare_for_storage(&g_props);
    g_scene_prop_store[g_props_active_scene]=g_props;
    memset(&g_props,0,sizeof(g_props));
    g_props=g_scene_prop_store[scene];
    memset(&g_scene_prop_store[scene],0,sizeof(g_scene_prop_store[scene]));
    g_props_active_scene=scene;
    printf("[SceneProps] Active now %s props=%d | stored Shire=%d Apartment=%d\n",
           scene_name(g_props_active_scene),g_props.count,
           g_scene_prop_store[SCENE_SHIRE].count,
           g_scene_prop_store[SCENE_APARTMENT].count);
    props_visibility_invalidate();
    stream_rebind(&g_stream,&g_props);
    static_collision_world_mark_dirty();
}

static void scene_layout_activate(SceneID scene){
    scene_props_activate(scene);
    surface_pieces_activate(scene);
    collision_volumes_activate(scene);
}

