/* Save placed props to file + print C array */
static void placer_save(PropList *pl){
    SceneID scene=scene_id_for_props(pl);
    const char *file=scene_prop_file(scene);
    FILE *f=fopen(file,"w");
    if(f){
        fprintf(f,"# Props placed in editor — %d total\n",pl->count);
        /* Only save props that were placed via the editor (path present, active) */
        int saved=0;
        for(int i=0;i<pl->count;i++){
            Prop *p=&pl->list[i];
            if(!p->active)continue;
            fprintf(f,"PROP %s %.3f %.3f %.3f %.3f %.3f %.3f %.3f %d %d %d %d %d %d %.3f %.3f %d\n",
                    p->path,
                    (double)p->pos.x,(double)p->pos.y,(double)p->pos.z,
                    (double)p->rot_x,(double)p->rot_y,(double)p->rot_z,
                    (double)p->scale,(int)p->coll_type,
                    p->pickable?1:0,(int)p->pickup_item,p->pickup_count,
                    p->custom_coll_enabled?1:0,
                    (int)p->interact_type,(double)p->interact_radius,(double)p->door_open_angle,
                    p->uid);
            if(p->custom_coll_count>0){
                for(int ci=0;ci<p->custom_coll_count;ci++){
                    PropCustomCollisionBox *box=&p->custom_coll[ci];
                    fprintf(f,"BOX %d %.3f %.3f %.3f %.3f %.3f %.3f %.3f\n",
                            prop_custom_collision_shape_sanitize(box->shape),
                            (double)box->center.x,(double)box->center.y,(double)box->center.z,
                            (double)box->half.x,(double)box->half.y,(double)box->half.z,
                            (double)box->yaw_deg);
                }
            }
            for(int ai=0;ai<p->action_count&&ai<PROP_ACTION_MAX;ai++){
                PropAction *action=&p->actions[ai];
                if(action->type==PROP_ACTION_NONE) continue;
                fprintf(f,"ACT %d %.3f %d %d %d %d %.1f\n",
                        (int)action->type,(double)action->radius,
                        action->target_index,(int)action->condition_type,action->condition_flag,
                        action->sound_idx,(double)action->sound_volume);
                if(action->type==PROP_ACTION_PLAY_SOUND&&action->sound_path[0]){
                    fputs("SFX ",f);
                    text_write_escaped(f,action->sound_path);
                    fputc('\n',f);
                }
                if(action->type==PROP_ACTION_READ_PROMPT&&action->prompt_text[0]){
                    fputs("READ ",f);
                    text_write_escaped(f,action->prompt_text);
                    fputc('\n',f);
                }
            }
            fprintf(f,"END\n");
            saved++;
        }
        fclose(f);
        printf("[PropPlacer] Saved %d props to %s\n",saved,file);
    }
    /* Also print C array */
    printf("[PropPlacer] C array:\n");
    for(int i=0;i<pl->count;i++){
        Prop *p=&pl->list[i];
        if(!p->active)continue;
        printf("    prop_register(&g_props,\"%s\", %.2ff,%.2ff,%.2ff, 0,%.1ff,0, %.3ff, %s,0,0,0,0); /* pickable=%d item=%d count=%d */\n",
               p->path,
               (double)p->pos.x,(double)p->pos.y,(double)p->pos.z,
               (double)p->rot_y,(double)p->scale,
               p->coll_type==PROP_COLL_MESH?"PROP_COLL_MESH":
               p->coll_type==PROP_COLL_AABB?"PROP_COLL_AABB":"PROP_COLL_NONE",
               p->pickable?1:0,(int)p->pickup_item,p->pickup_count);
    }
}

/* Load previously saved props at startup */
static void placer_load(PropList *pl){
    SceneID scene=scene_id_for_props(pl);
    const char *file=scene_prop_file(scene);
    FILE *f=fopen(file,"r");
    if(!f)return;
    char line[512];int loaded=0;int current_prop_idx=-1;
    while(fgets(line,sizeof(line),f)){
        if(line[0]=='#')continue;
        if(strncmp(line,"BOX ",4)==0){
            if(current_prop_idx>=0&&current_prop_idx<pl->count&&pl->list[current_prop_idx].active){
                Prop *p=&pl->list[current_prop_idx];
                if(p->custom_coll_count<PROP_CUSTOM_COLL_MAX){
                    PropCustomCollisionBox box;
                    int shape=PROP_CUSTOM_COLL_SHAPE_BOX;
                    char *cursor=line+4;
                    char *endptr=NULL;
                    bool parsed=false;
                    memset(&box,0,sizeof(box));
                    strtol(cursor,&endptr,10);
                    if(endptr&&endptr>cursor&&(*endptr==' '||*endptr=='\t')&&
                       sscanf(cursor,"%d %f %f %f %f %f %f %f",
                              &shape,
                              &box.center.x,&box.center.y,&box.center.z,
                              &box.half.x,&box.half.y,&box.half.z,&box.yaw_deg)==8){
                        box.shape=prop_custom_collision_shape_sanitize(shape);
                        parsed=true;
                    }else if(sscanf(line+4,"%f %f %f %f %f %f %f",
                              &box.center.x,&box.center.y,&box.center.z,
                              &box.half.x,&box.half.y,&box.half.z,&box.yaw_deg)==7){
                        box.shape=PROP_CUSTOM_COLL_SHAPE_BOX;
                        parsed=true;
                    }
                    if(parsed){
                        prop_custom_collision_clamp_box(&box);
                        p->custom_coll[p->custom_coll_count++]=box;
                        p->custom_coll_enabled=true;
                    }
                }
            }
            continue;
        }
        if(strncmp(line,"ACT ",4)==0){
            if(current_prop_idx>=0&&current_prop_idx<pl->count&&pl->list[current_prop_idx].active){
                Prop *p=&pl->list[current_prop_idx];
                if(p->action_count<PROP_ACTION_MAX){
                    int action_type=0;
                    float action_radius=8.0f;
                    int target_index=-1;
                    int condition_type=(int)PROP_ACTION_COND_NONE;
                    int condition_flag=0;
                    int sound_idx=0;
                    float sound_volume=85.0f;
                    if(sscanf(line+4,"%d %f %d %d %d %d %f",
                              &action_type,&action_radius,&target_index,&condition_type,&condition_flag,
                              &sound_idx,&sound_volume)>=1){
                        PropAction *action=&p->actions[p->action_count++];
                        memset(action,0,sizeof(*action));
                        switch(action_type){
                            case PROP_ACTION_TOGGLE_NEAREST_LIGHT:
                            case PROP_ACTION_TOGGLE_TARGET_LIGHT:
                            case PROP_ACTION_TOGGLE_TARGET_COLLISION_VOLUME:
                            case PROP_ACTION_TOGGLE_TARGET_DOOR:
                            case PROP_ACTION_SET_WORLD_FLAG:
                            case PROP_ACTION_CLEAR_WORLD_FLAG:
                            case PROP_ACTION_PLAY_SOUND:
                            case PROP_ACTION_READ_PROMPT:
                                action->type=(PropActionType)action_type;
                                break;
                            default:
                                action->type=PROP_ACTION_NONE;
                                break;
                        }
                        action->radius=(action_radius>0.1f)?action_radius:8.0f;
                        action->target_index=target_index;
                        action->condition_type=(condition_type==PROP_ACTION_COND_FLAG_SET)
                            ?PROP_ACTION_COND_FLAG_SET
                            :(condition_type==PROP_ACTION_COND_FLAG_CLEAR?PROP_ACTION_COND_FLAG_CLEAR:PROP_ACTION_COND_NONE);
                        action->condition_flag=(condition_flag>=0&&condition_flag<WORLD_FLAG_MAX)?condition_flag:0;
                        action->sound_idx=(sound_idx>=0&&sound_idx<PROP_ACTION_SOUND_COUNT)?sound_idx:0;
                        action->sound_volume=clampf(sound_volume,1.0f,128.0f);
                        action->sound_path[0]=0;
                        action->prompt_text[0]=0;
                    }
                }
            }
            continue;
        }
        if(strncmp(line,"SFX ",4)==0){
            if(current_prop_idx>=0&&current_prop_idx<pl->count&&pl->list[current_prop_idx].active){
                Prop *p=&pl->list[current_prop_idx];
                if(p->action_count>0){
                    PropAction *action=&p->actions[p->action_count-1];
                    text_unescape_copy(action->sound_path,sizeof(action->sound_path),line+4);
                    action->type=PROP_ACTION_PLAY_SOUND;
                }
            }
            continue;
        }
        if(strncmp(line,"READ ",5)==0){
            if(current_prop_idx>=0&&current_prop_idx<pl->count&&pl->list[current_prop_idx].active){
                Prop *p=&pl->list[current_prop_idx];
                if(p->action_count>0){
                    PropAction *action=&p->actions[p->action_count-1];
                    text_unescape_copy(action->prompt_text,sizeof(action->prompt_text),line+5);
                    action->type=PROP_ACTION_READ_PROMPT;
                }
            }
            continue;
        }
        if(strncmp(line,"END",3)==0){
            current_prop_idx=-1;
            continue;
        }
        char path[256]; float x,y,z,rx,ry,rz,sc; int coll;
        int pickable=0;
        int pickup_item=(int)ITEM_NONE;
        int pickup_count=1;
        int custom_enabled=0;
        int interact_type=(int)PROP_INTERACT_NONE;
        float interact_radius=2.5f;
        float door_open_angle=90.0f;
        int uid=0;
        int fields;
        if(strncmp(line,"PROP ",5)==0){
            fields=sscanf(line+5,"%255s %f %f %f %f %f %f %f %d %d %d %d %d %d %f %f %d",
                          path,&x,&y,&z,&rx,&ry,&rz,&sc,&coll,
                          &pickable,&pickup_item,&pickup_count,&custom_enabled,
                          &interact_type,&interact_radius,&door_open_angle,&uid);
        }else{
            fields=sscanf(line,"%255s %f %f %f %f %f %f %f %d %d %d %d %d %f %f %d",
                          path,&x,&y,&z,&rx,&ry,&rz,&sc,&coll,
                          &pickable,&pickup_item,&pickup_count,&interact_type,
                          &interact_radius,&door_open_angle,&uid);
        }
        if(fields>=9){
            int idx=props_next_slot(pl);
            if(scene_props_preload_immediate(scene))
                prop_place(pl,path,x,y,z,rx,ry,rz,sc,(PropCollType)coll,0,0,0,0);
            else
                prop_register(pl,path,x,y,z,rx,ry,rz,sc,(PropCollType)coll,0,0,0,0);
            if(idx>=0&&idx<pl->count&&pl->list[idx].active){
                Prop *p=&pl->list[idx];
                p->pickable=(fields>=10)&&pickable!=0;
                if(fields>=11&&pickup_item>ITEM_NONE&&pickup_item<ITEM_COUNT) p->pickup_item=(ItemType)pickup_item;
                else p->pickup_item=ITEM_NONE;
                p->pickup_count=(fields>=12&&pickup_count>0)?pickup_count:1;
                p->custom_coll_enabled=(fields>=13)&&custom_enabled!=0;
                p->custom_coll_count=0;
                p->custom_coll_selected=0;
                p->interact_type=(fields>=14&&interact_type==PROP_INTERACT_DOOR)?PROP_INTERACT_DOOR:PROP_INTERACT_NONE;
                p->interact_radius=(fields>=15&&interact_radius>0.1f)?interact_radius:2.5f;
                p->door_open_angle=(fields>=16)?door_open_angle:90.0f;
                if(fields>=17&&uid>0){ p->uid=uid; world_observe_prop_uid(uid); }
                p->door_closed_yaw=p->rot_y;
                p->door_is_open=false;
                p->action_count=0;
                p->action_selected=0;
                memset(p->actions,0,sizeof(p->actions));
                if(!p->pickable){
                    p->pickup_item=ITEM_NONE;
                    p->pickup_count=1;
                }
                current_prop_idx=idx;
            }
            loaded++;
        }
    }
    fclose(f);
    printf("[PropPlacer] Loaded %d props from %s\n",loaded,file);
}

static bool str_contains_nocase(const char *haystack,const char *needle){
    if(!haystack||!needle||!*needle) return false;
    size_t nlen=strlen(needle);
    for(const char *p=haystack;*p;p++){
        size_t i=0;
        while(i<nlen&&p[i]){
            char a=p[i],b=needle[i];
            if(a>='A'&&a<='Z') a=(char)(a-'A'+'a');
            if(b>='A'&&b<='Z') b=(char)(b-'A'+'a');
            if(a!=b) break;
            i++;
        }
        if(i==nlen) return true;
    }
    return false;
}

static bool prop_is_campfire_anchor(const Prop *p){
    if(!p||!p->active) return false;
    return str_contains_nocase(p->path,"campfire")||
           str_contains_nocase(p->path,"camp_fire")||
           str_contains_nocase(p->path,"bonfire")||
           str_contains_nocase(p->path,"bon_fire")||
           str_contains_nocase(p->path,"firepit")||
           str_contains_nocase(p->path,"fire_pit");
}

static bool starter_campfire_anchor_from_props(PropList *pl,float fallback_x,float fallback_z,Vec3 *out_pos){
    if(!pl||!out_pos) return false;
    float best=1e30f;
    int best_idx=-1;
    for(int i=0;i<pl->count;i++){
        Prop *p=&pl->list[i];
        if(!prop_is_campfire_anchor(p)) continue;
        float dx=p->pos.x-fallback_x;
        float dz=p->pos.z-fallback_z;
        float d2=dx*dx+dz*dz;
        if(d2<best){
            best=d2;
            best_idx=i;
        }
    }
    if(best_idx<0) return false;
    out_pos->x=pl->list[best_idx].pos.x;
    out_pos->z=pl->list[best_idx].pos.z;
    out_pos->y=terrain_h(out_pos->x,out_pos->z)+0.3f;
    printf("[Campfire] Anchor from prop %d: %s @ %.1f %.1f\n",
           best_idx,pl->list[best_idx].path,(double)out_pos->x,(double)out_pos->z);
    return true;
}

