static void world_fx_spawn_portal(ParticleSystem *ps,WorldFx *fx,float dt,float total_time){
    int ring_count=(int)(16.0f*fx->intensity*dt*60.0f)+3;
    int core_count=(int)(7.0f*fx->intensity*dt*60.0f)+1;
    float radius=fmaxf(0.35f,fx->scale*0.52f);
    float half_h=fmaxf(0.55f,fx->height*0.50f);
    for(int i=0;i<ring_count;i++){
        float ang=((float)rand()/(float)RAND_MAX)*(float)(2.0*M_PI)+total_time*1.55f+fx->phase*0.35f;
        float rim=0.88f+0.18f*((float)rand()/(float)RAND_MAX);
        float thickness=(((float)rand()/(float)RAND_MAX)-0.5f)*fx->scale*0.12f;
        float inner_spin=0.08f*sinf(total_time*3.2f+ang*2.0f+fx->phase);
        Vec3 pos={
            fx->pos.x+cosf(ang)*(radius*rim),
            fx->pos.y+half_h+sinf(ang)*(half_h*rim)+inner_spin,
            fx->pos.z+thickness
        };
        Vec3 vel={
            -cosf(ang)*0.05f,
            0.02f+0.06f*cosf(ang+total_time*0.7f),
            thickness*0.55f+0.08f*sinf(ang+total_time*1.6f)
        };
        ps_spawn_typed(ps,pos,vel,
                       0.26f+0.14f*((float)rand()/(float)RAND_MAX),
                       0.045f*fx->scale+0.025f*((float)rand()/(float)RAND_MAX),
                       fx->color.x,fx->color.y,fx->color.z,PT_MAGIC);
        if((i%2)==0){
            ps_spawn_typed(ps,pos,(Vec3){vel.x*0.25f,vel.y*0.35f,vel.z*0.40f},
                           0.20f+0.10f*((float)rand()/(float)RAND_MAX),
                           0.030f*fx->scale+0.020f*((float)rand()/(float)RAND_MAX),
                           fx->color.x*0.70f,fx->color.y*0.92f,1.0f,PT_NORMAL);
        }
    }
    for(int i=0;i<core_count;i++){
        float h=(((float)rand()/(float)RAND_MAX)-0.5f)*half_h*1.5f;
        float swirl=total_time*2.6f+fx->phase+(float)i*0.9f;
        float inner_r=radius*(0.14f+0.18f*((float)rand()/(float)RAND_MAX));
        Vec3 pos={
            fx->pos.x+cosf(swirl)*inner_r,
            fx->pos.y+half_h+h,
            fx->pos.z+0.05f*sinf(swirl*1.8f)
        };
        Vec3 vel={
            -sinf(swirl)*0.14f,
            0.03f+0.05f*((float)rand()/(float)RAND_MAX),
            0.12f*cosf(swirl*1.4f)
        };
        ps_spawn_typed(ps,pos,vel,
                       0.22f+0.12f*((float)rand()/(float)RAND_MAX),
                       0.028f*fx->scale+0.015f*((float)rand()/(float)RAND_MAX),
                       fx->color.x*0.82f,fx->color.y,1.0f,PT_MAGIC);
        if((i%2)==0){
            ps_spawn_typed(ps,pos,(Vec3){0.0f,0.02f,0.0f},
                           0.26f,0.045f*fx->scale,0.16f,0.28f,0.40f,PT_DUST);
        }
    }
}

