        snprintf(buf,sizeof(buf),"Size: %.2fx",brush_size);
        hud_str(h,px+4,py,1.2f,buf,0.9f,0.9f,0.8f,1.0f); py+=lh;
        snprintf(buf,sizeof(buf),"H Min: %.2fx",brush_hmin);
        hud_str(h,px+4,py,1.2f,buf,0.9f,0.9f,0.8f,1.0f); py+=lh;
