static float affix_val_for(ItemRarity r,ItemAffix a){
    float base,bonus;
    switch(a){case AFFIX_SWIFT:base=0.08f;bonus=0.04f;break;case AFFIX_TOUGH:base=0.04f;bonus=0.04f;break;case AFFIX_MIGHTY:base=3.0f;bonus=4.0f;break;default:return 0.0f;}
    float t=(r==RARITY_LEGENDARY)?1.0f:(r==RARITY_RARE)?0.5f:0.0f;
    return base+t*bonus;
}

