static void surface_piece_aabb(const SurfacePiece *sp,AABB *out_box){
    float hx,hy,hz;
    float c,s,ex,ez;
    if(!sp||!out_box) return;
    hx=sp->width*0.5f;
    hy=(sp->kind==SURFACE_PIECE_WALL)?(sp->height*0.5f):(sp->thickness*0.5f);
    hz=(sp->kind==SURFACE_PIECE_WALL)?(sp->thickness*0.5f):(sp->height*0.5f);
    c=fabsf(cosf(sp->yaw_deg*(float)M_PI/180.0f));
    s=fabsf(sinf(sp->yaw_deg*(float)M_PI/180.0f));
    ex=c*hx+s*hz;
    ez=s*hx+c*hz;
    out_box->min=(Vec3){sp->pos.x-ex,sp->pos.y-hy,sp->pos.z-ez};
    out_box->max=(Vec3){sp->pos.x+ex,sp->pos.y+hy,sp->pos.z+ez};
}

