static int collision_volume_shape_sanitize(int shape){
    return (shape==COLLISION_VOLUME_SHAPE_OVAL)?COLLISION_VOLUME_SHAPE_OVAL:COLLISION_VOLUME_SHAPE_BOX;
}

static const char *collision_volume_shape_name(int shape){
    return collision_volume_shape_sanitize(shape)==COLLISION_VOLUME_SHAPE_OVAL?"Oval":"Box";
}

static void collision_volume_aabb(const CollisionVolume *cv,AABB *out_box){
    float hx,hy,hz;
    if(!cv||!out_box) return;
    hx=cv->width*0.5f;
    hy=cv->height*0.5f;
    hz=cv->depth*0.5f;
    if(collision_volume_shape_sanitize(cv->shape)==COLLISION_VOLUME_SHAPE_OVAL||fabsf(cv->pitch_deg)<=0.001f){
        float c=fabsf(cosf(cv->yaw_deg*(float)M_PI/180.0f));
        float s=fabsf(sinf(cv->yaw_deg*(float)M_PI/180.0f));
        float ex=c*hx+s*hz;
        float ez=s*hx+c*hz;
        out_box->min=(Vec3){cv->runtime_pos.x-ex,cv->runtime_pos.y-hy,cv->runtime_pos.z-ez};
        out_box->max=(Vec3){cv->runtime_pos.x+ex,cv->runtime_pos.y+hy,cv->runtime_pos.z+ez};
    }else{
        Mat4 world=mat4_mul(mat4_translate(cv->runtime_pos.x,cv->runtime_pos.y,cv->runtime_pos.z),
                            mat4_mul(mat4_rot_y(cv->yaw_deg*(float)M_PI/180.0f),
                                     mat4_rot_x(cv->pitch_deg*(float)M_PI/180.0f)));
        Vec3 corners[8]={
            {-hx,-hy,-hz},{ hx,-hy,-hz},{-hx, hy,-hz},{ hx, hy,-hz},
            {-hx,-hy, hz},{ hx,-hy, hz},{-hx, hy, hz},{ hx, hy, hz}
        };
        Vec3 p=mat4_transform_point(world,corners[0]);
        out_box->min=p;
        out_box->max=p;
        for(int i=1;i<8;i++){
            p=mat4_transform_point(world,corners[i]);
            out_box->min.x=fminf(out_box->min.x,p.x);
            out_box->min.y=fminf(out_box->min.y,p.y);
            out_box->min.z=fminf(out_box->min.z,p.z);
            out_box->max.x=fmaxf(out_box->max.x,p.x);
            out_box->max.y=fmaxf(out_box->max.y,p.y);
            out_box->max.z=fmaxf(out_box->max.z,p.z);
        }
    }
}

static void collision_volume_debug_wireframe(const CollisionVolume *cv,float r,float g,float b){
    static const int box_edges[12][2]={
        {0,1},{1,3},{3,2},{2,0},
        {4,5},{5,7},{7,6},{6,4},
        {0,4},{1,5},{2,6},{3,7}
    };
    if(!cv||!cv->active) return;
    if(collision_volume_shape_sanitize(cv->shape)==COLLISION_VOLUME_SHAPE_OVAL){
        const int segs=24;
        float hy=cv->height*0.5f;
        float rx=cv->width*0.5f;
        float rz=cv->depth*0.5f;
        float yaw=cv->yaw_deg*(float)M_PI/180.0f;
        float c=cosf(yaw);
        float s=sinf(yaw);
        for(int i=0;i<segs;i++){
            float a0=((float)i/(float)segs)*(2.0f*(float)M_PI);
            float a1=((float)(i+1)/(float)segs)*(2.0f*(float)M_PI);
            Vec3 p0_local={(cosf(a0)*rx),-hy,(sinf(a0)*rz)};
            Vec3 p1_local={(cosf(a1)*rx),-hy,(sinf(a1)*rz)};
            Vec3 p2_local={(cosf(a0)*rx), hy,(sinf(a0)*rz)};
            Vec3 p3_local={(cosf(a1)*rx), hy,(sinf(a1)*rz)};
            Vec3 p0={cv->runtime_pos.x+p0_local.x*c-p0_local.z*s,cv->runtime_pos.y+p0_local.y,cv->runtime_pos.z+p0_local.x*s+p0_local.z*c};
            Vec3 p1={cv->runtime_pos.x+p1_local.x*c-p1_local.z*s,cv->runtime_pos.y+p1_local.y,cv->runtime_pos.z+p1_local.x*s+p1_local.z*c};
            Vec3 p2={cv->runtime_pos.x+p2_local.x*c-p2_local.z*s,cv->runtime_pos.y+p2_local.y,cv->runtime_pos.z+p2_local.x*s+p2_local.z*c};
            Vec3 p3={cv->runtime_pos.x+p3_local.x*c-p3_local.z*s,cv->runtime_pos.y+p3_local.y,cv->runtime_pos.z+p3_local.x*s+p3_local.z*c};
            lr_push(p0,p1,r,g,b);
            lr_push(p2,p3,r,g,b);
            if((i%6)==0) lr_push(p0,p2,r,g,b);
        }
    }else{
        float hx=cv->width*0.5f;
        float hy=cv->height*0.5f;
        float hz=cv->depth*0.5f;
        Mat4 world=mat4_mul(mat4_translate(cv->runtime_pos.x,cv->runtime_pos.y,cv->runtime_pos.z),
                            mat4_mul(mat4_rot_y(cv->yaw_deg*(float)M_PI/180.0f),
                                     mat4_rot_x(cv->pitch_deg*(float)M_PI/180.0f)));
        Vec3 corners[8]={
            {-hx,-hy,-hz},{ hx,-hy,-hz},{-hx, hy,-hz},{ hx, hy,-hz},
            {-hx,-hy, hz},{ hx,-hy, hz},{-hx, hy, hz},{ hx, hy, hz}
        };
        Vec3 arrow_base=mat4_transform_point(world,(Vec3){0.0f,hy+0.08f,0.0f});
        Vec3 arrow_tip=mat4_transform_point(world,(Vec3){0.0f,hy+0.08f,fmaxf(hz*0.55f,hz+0.25f)});
        Vec3 arrow_left=mat4_transform_point(world,(Vec3){-0.16f,hy+0.08f,fmaxf(hz*0.55f,hz+0.25f)-0.18f});
        Vec3 arrow_right=mat4_transform_point(world,(Vec3){0.16f,hy+0.08f,fmaxf(hz*0.55f,hz+0.25f)-0.18f});
        for(int i=0;i<8;i++) corners[i]=mat4_transform_point(world,corners[i]);
        for(int i=0;i<12;i++) lr_push(corners[box_edges[i][0]],corners[box_edges[i][1]],r,g,b);
        lr_push(arrow_base,arrow_tip,r,g,b);
        lr_push(arrow_tip,arrow_left,r,g,b);
        lr_push(arrow_tip,arrow_right,r,g,b);
    }
}

static int collision_volumes_next_slot(CollisionVolumeList *list){
    if(!list) return -1;
    for(int i=0;i<list->count;i++) if(!list->items[i].active) return i;
    if(list->count>=COLLISION_VOLUME_MAX) return -1;
    return list->count;
}

static int collision_volume_register(CollisionVolumeList *list,Vec3 pos,int shape,float yaw_deg,float pitch_deg,
                                     float width,float height,float depth,
                                     bool enabled,bool nav_blocker){
    int idx=collision_volumes_next_slot(list);
    CollisionVolume *cv;
    if(idx<0||!list) return -1;
    cv=&list->items[idx];
    memset(cv,0,sizeof(*cv));
    cv->active=true;
    cv->uid=world_alloc_collision_volume_uid();
    cv->pos=pos;
    cv->runtime_pos=pos;
    cv->prev_runtime_pos=pos;
    cv->shape=collision_volume_shape_sanitize(shape);
    cv->yaw_deg=yaw_deg;
    cv->pitch_deg=(cv->shape==COLLISION_VOLUME_SHAPE_OVAL)?0.0f:clampf(pitch_deg,-89.0f,89.0f);
    cv->width=clampf(width,0.25f,64.0f);
    cv->height=clampf(height,0.25f,64.0f);
    cv->depth=clampf(depth,0.25f,64.0f);
    cv->enabled=enabled;
    cv->nav_blocker=nav_blocker;
    cv->motion_enabled=false;
    cv->motion_offset=(Vec3){0,0,0};
    cv->motion_period=2.0f;
    cv->motion_phase=0.0f;
    if(idx==list->count) list->count++;
    return idx;
}

static bool collision_volume_query(int idx,float *out_width,float *out_height,float *out_depth,
                                   bool *out_enabled,bool *out_nav_blocker){
    if(idx<0||idx>=g_collision_volumes.count||!g_collision_volumes.items[idx].active) return false;
    if(out_width) *out_width=g_collision_volumes.items[idx].width;
    if(out_height) *out_height=g_collision_volumes.items[idx].height;
    if(out_depth) *out_depth=g_collision_volumes.items[idx].depth;
    if(out_enabled) *out_enabled=g_collision_volumes.items[idx].enabled;
    if(out_nav_blocker) *out_nav_blocker=g_collision_volumes.items[idx].nav_blocker;
    return true;
}

static bool collision_volume_shape_query(int idx,int *out_shape,float *out_pitch){
    if(idx<0||idx>=g_collision_volumes.count||!g_collision_volumes.items[idx].active) return false;
    if(out_shape) *out_shape=collision_volume_shape_sanitize(g_collision_volumes.items[idx].shape);
    if(out_pitch) *out_pitch=g_collision_volumes.items[idx].pitch_deg;
    return true;
}

static bool collision_volume_describe(int idx,Vec3 *out_pos,float *out_yaw,float *out_width,
                                      float *out_height,float *out_depth,
                                      bool *out_enabled,bool *out_nav_blocker){
    CollisionVolume *cv;
    if(idx<0||idx>=g_collision_volumes.count||!g_collision_volumes.items[idx].active) return false;
    cv=&g_collision_volumes.items[idx];
    if(out_pos) *out_pos=cv->pos;
    if(out_yaw) *out_yaw=cv->yaw_deg;
    if(out_width) *out_width=cv->width;
    if(out_height) *out_height=cv->height;
    if(out_depth) *out_depth=cv->depth;
    if(out_enabled) *out_enabled=cv->enabled;
    if(out_nav_blocker) *out_nav_blocker=cv->nav_blocker;
    return true;
}

static bool collision_volume_motion_describe(int idx,bool *out_motion_enabled,
                                             Vec3 *out_motion_offset,float *out_motion_period,
                                             float *out_motion_phase){
    CollisionVolume *cv;
    if(idx<0||idx>=g_collision_volumes.count||!g_collision_volumes.items[idx].active) return false;
    cv=&g_collision_volumes.items[idx];
    if(out_motion_enabled) *out_motion_enabled=cv->motion_enabled;
    if(out_motion_offset) *out_motion_offset=cv->motion_offset;
    if(out_motion_period) *out_motion_period=cv->motion_period;
    if(out_motion_phase) *out_motion_phase=cv->motion_phase;
    return true;
}

static bool collision_volume_get_pos(int idx,Vec3 *out_pos){
    return collision_volume_describe(idx,out_pos,NULL,NULL,NULL,NULL,NULL,NULL);
}

static void prop_custom_collision_proxy_from_prop(const Prop *p,const PropCustomCollisionBox *box,SurfacePiece *out_proxy){
    Mat4 world;
    Vec3 center;
    float radius;
    if(!p||!box||!out_proxy) return;
    world=mat4_mul(prop_world((Prop*)p),
                   mat4_mul(mat4_translate(box->center.x,box->center.y,box->center.z),
                            mat4_rot_y(box->yaw_deg*(float)M_PI/180.0f)));
    center=mat4_transform_point(world,(Vec3){0,0,0});
    memset(out_proxy,0,sizeof(*out_proxy));
    out_proxy->active=true;
    out_proxy->kind=SURFACE_PIECE_WALL;
    out_proxy->pos=center;
    out_proxy->yaw_deg=p->rot_y+box->yaw_deg;
    if(box->shape==PROP_CUSTOM_COLL_SHAPE_SPHERE){
        radius=fmaxf(0.05f,box->half.x);
        out_proxy->width=fmaxf(0.10f,radius*2.0f*p->scale);
        out_proxy->height=fmaxf(0.10f,radius*2.0f*p->scale);
        out_proxy->thickness=fmaxf(0.10f,radius*2.0f*p->scale);
    }else if(box->shape==PROP_CUSTOM_COLL_SHAPE_CIRCLE){
        radius=fmaxf(0.05f,box->half.x);
        out_proxy->width=fmaxf(0.10f,radius*2.0f*p->scale);
        out_proxy->height=fmaxf(0.10f,box->half.y*2.0f*p->scale);
        out_proxy->thickness=fmaxf(0.10f,radius*2.0f*p->scale);
    }else{
        out_proxy->width=fmaxf(0.10f,box->half.x*2.0f*p->scale);
        out_proxy->height=fmaxf(0.10f,box->half.y*2.0f*p->scale);
        out_proxy->thickness=fmaxf(0.10f,box->half.z*2.0f*p->scale);
    }
}

static void prop_custom_collision_apply_proxy(Prop *p,PropCustomCollisionBox *box,const SurfacePiece *proxy){
    Mat4 inv_world;
    Vec3 local_center;
    float inv_scale;
    float radius;
    if(!p||!box||!proxy) return;
    inv_world=mat4_inverse_affine(prop_world(p));
    local_center=mat4_transform_point(inv_world,proxy->pos);
    inv_scale=(fabsf(p->scale)>1e-4f)?(1.0f/p->scale):1.0f;
    box->center=local_center;
    box->half.x=fmaxf(0.05f,proxy->width*0.5f*inv_scale);
    box->half.y=fmaxf(0.05f,proxy->height*0.5f*inv_scale);
    box->half.z=fmaxf(0.05f,proxy->thickness*0.5f*inv_scale);
    box->yaw_deg=proxy->yaw_deg-p->rot_y;
    if(box->shape==PROP_CUSTOM_COLL_SHAPE_SPHERE){
        radius=fmaxf(box->half.x,fmaxf(box->half.y,box->half.z));
        box->half.x=radius;
        box->half.y=radius;
        box->half.z=radius;
        box->yaw_deg=0.0f;
    }else if(box->shape==PROP_CUSTOM_COLL_SHAPE_CIRCLE){
        radius=fmaxf(box->half.x,box->half.z);
        box->half.x=radius;
        box->half.z=radius;
        box->yaw_deg=0.0f;
    }
    prop_custom_collision_clamp_box(box);
}

static Vec3 collision_volume_delta(int idx){
    if(idx<0||idx>=g_collision_volumes.count||!g_collision_volumes.items[idx].active) return (Vec3){0,0,0};
    return vec3_sub(g_collision_volumes.items[idx].runtime_pos,g_collision_volumes.items[idx].prev_runtime_pos);
}

static int surface_piece_collision_type(int idx){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return PROP_COLL_NONE;
    return (int)g_surfaces.items[idx].coll_type;
}

int surface_piece_nav_obstacle_count(void){
    return g_surfaces.count;
}

bool surface_piece_nav_obstacle_aabb(int idx,AABB *out_box){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    if(g_surfaces.items[idx].coll_type==PROP_COLL_NONE||g_surfaces.items[idx].kind!=SURFACE_PIECE_WALL) return false;
    surface_piece_aabb(&g_surfaces.items[idx],out_box);
    return true;
}

#define STATIC_COLL_CELL 8.0f
#define STATIC_COLL_GRID_W 176
#define STATIC_COLL_GRID_H 176
#define STATIC_COLL_MAX (MAX_PROPS + SURFACE_PIECE_MAX + COLLISION_VOLUME_MAX)
#define STATIC_COLL_CELL_CAP 64

typedef enum{
    STATIC_COLL_SHAPE_AABB=0,
    STATIC_COLL_SHAPE_MESH,
    STATIC_COLL_SHAPE_OBOX,
    STATIC_COLL_SHAPE_SPHERE,
    STATIC_COLL_SHAPE_CIRCLE,
    STATIC_COLL_SHAPE_OVAL,
    STATIC_COLL_SHAPE_MESH_VOLUME
}StaticColliderShape;

typedef enum{
    STATIC_COLL_SOURCE_PROP=0,
    STATIC_COLL_SOURCE_SURFACE,
    STATIC_COLL_SOURCE_COLLISION_VOLUME
}StaticColliderSource;

typedef struct{
    StaticColliderShape  shape;
    StaticColliderSource source;
    int                  source_idx;
    bool                 nav_blocker;
    AABB                 bounds;
    Vec3                 center;
    Vec3                 half;
    float                yaw_deg;
    float                pitch_deg;
    float                radius;
    CTri                 mesh_tris[12];
    int                  mesh_tri_count;
}StaticCollider;

typedef struct{
    StaticCollider colliders[STATIC_COLL_MAX];
    int            collider_count;
    int            obstacle_indices[STATIC_COLL_MAX];
    int            obstacle_count;
    int            cell_counts[STATIC_COLL_GRID_W*STATIC_COLL_GRID_H];
    int            cell_items[STATIC_COLL_GRID_W*STATIC_COLL_GRID_H][STATIC_COLL_CELL_CAP];
    uint32_t       query_marks[STATIC_COLL_MAX];
    uint32_t       query_stamp;
    bool           dirty;
}StaticCollisionWorld;

static StaticCollisionWorld g_static_collision_world={.dirty=true};

static int static_collision_world_cell_x(float wx){
    int cell=(int)floorf((wx+WORLD_HALF)/STATIC_COLL_CELL);
    if(cell<0) return 0;
    if(cell>=STATIC_COLL_GRID_W) return STATIC_COLL_GRID_W-1;
    return cell;
}

static int static_collision_world_cell_z(float wz){
    int cell=(int)floorf((wz+WORLD_HALF)/STATIC_COLL_CELL);
    if(cell<0) return 0;
    if(cell>=STATIC_COLL_GRID_H) return STATIC_COLL_GRID_H-1;
    return cell;
}

static int static_collision_world_cell_index(int cx,int cz){
    return cz*STATIC_COLL_GRID_W+cx;
}

static void static_collision_world_insert(StaticCollisionWorld *cw,
                                          StaticColliderShape shape,
                                          StaticColliderSource source,
                                          int source_idx,
                                          bool nav_blocker,
                                          const AABB *bounds,
                                          const Vec3 *center,
                                          const Vec3 *half,
                                          float yaw_deg,
                                          float pitch_deg,
                                          float radius){
    int idx,x0,x1,z0,z1;
    if(!cw||!bounds||cw->collider_count>=STATIC_COLL_MAX) return;
    idx=cw->collider_count++;
    cw->colliders[idx].shape=shape;
    cw->colliders[idx].source=source;
    cw->colliders[idx].source_idx=source_idx;
    cw->colliders[idx].nav_blocker=nav_blocker;
    cw->colliders[idx].bounds=*bounds;
    cw->colliders[idx].center=center?*center:(Vec3){0,0,0};
    cw->colliders[idx].half=half?*half:(Vec3){0,0,0};
    cw->colliders[idx].yaw_deg=yaw_deg;
    cw->colliders[idx].pitch_deg=pitch_deg;
    cw->colliders[idx].radius=radius;
    cw->colliders[idx].mesh_tri_count=0;
    if(nav_blocker) cw->obstacle_indices[cw->obstacle_count++]=idx;
    x0=static_collision_world_cell_x(bounds->min.x);
    x1=static_collision_world_cell_x(bounds->max.x);
    z0=static_collision_world_cell_z(bounds->min.z);
    z1=static_collision_world_cell_z(bounds->max.z);
    for(int z=z0;z<=z1;z++){
        for(int x=x0;x<=x1;x++){
            int cell=static_collision_world_cell_index(x,z);
            int count=cw->cell_counts[cell];
            if(count<STATIC_COLL_CELL_CAP) cw->cell_items[cell][count]=idx;
            if(count<STATIC_COLL_CELL_CAP) cw->cell_counts[cell]=count+1;
        }
    }
}

static Vec3 static_collision_rotate_y(Vec3 v,float yaw_deg){
    float a=yaw_deg*(float)M_PI/180.0f;
    float c=cosf(a);
    float s=sinf(a);
    return (Vec3){v.x*c-v.z*s,v.y,v.x*s+v.z*c};
}

static Vec3 static_collision_rotate_x(Vec3 v,float pitch_deg){
    float a=pitch_deg*(float)M_PI/180.0f;
    float c=cosf(a);
    float s=sinf(a);
    return (Vec3){v.x,v.y*c-v.z*s,v.y*s+v.z*c};
}

static void collision_volume_box_build_mesh(const CollisionVolume *cv,CTri out_tris[12],AABB *out_bounds){
    float hx,hy,hz;
    Mat4 world;
    Vec3 corners[8];
    static const int tri_idx[12][3]={
        {0,2,3},{0,3,1},
        {4,5,7},{4,7,6},
        {0,1,5},{0,5,4},
        {2,6,7},{2,7,3},
        {0,4,6},{0,6,2},
        {1,3,7},{1,7,5}
    };
    if(!cv||!out_tris) return;
    hx=cv->width*0.5f;
    hy=cv->height*0.5f;
    hz=cv->depth*0.5f;
    world=mat4_mul(mat4_translate(cv->runtime_pos.x,cv->runtime_pos.y,cv->runtime_pos.z),
                   mat4_mul(mat4_rot_y(cv->yaw_deg*(float)M_PI/180.0f),
                            mat4_rot_x(cv->pitch_deg*(float)M_PI/180.0f)));
    corners[0]=mat4_transform_point(world,(Vec3){-hx,-hy,-hz});
    corners[1]=mat4_transform_point(world,(Vec3){ hx,-hy,-hz});
    corners[2]=mat4_transform_point(world,(Vec3){-hx, hy,-hz});
    corners[3]=mat4_transform_point(world,(Vec3){ hx, hy,-hz});
    corners[4]=mat4_transform_point(world,(Vec3){-hx,-hy, hz});
    corners[5]=mat4_transform_point(world,(Vec3){ hx,-hy, hz});
    corners[6]=mat4_transform_point(world,(Vec3){-hx, hy, hz});
    corners[7]=mat4_transform_point(world,(Vec3){ hx, hy, hz});
    if(out_bounds){
        out_bounds->min=corners[0];
        out_bounds->max=corners[0];
        for(int i=1;i<8;i++){
            out_bounds->min.x=fminf(out_bounds->min.x,corners[i].x);
            out_bounds->min.y=fminf(out_bounds->min.y,corners[i].y);
            out_bounds->min.z=fminf(out_bounds->min.z,corners[i].z);
            out_bounds->max.x=fmaxf(out_bounds->max.x,corners[i].x);
            out_bounds->max.y=fmaxf(out_bounds->max.y,corners[i].y);
            out_bounds->max.z=fmaxf(out_bounds->max.z,corners[i].z);
        }
    }
    for(int i=0;i<12;i++){
        Vec3 a=corners[tri_idx[i][0]];
        Vec3 b=corners[tri_idx[i][1]];
        Vec3 c=corners[tri_idx[i][2]];
        Vec3 ab=vec3_sub(b,a),ac=vec3_sub(c,a);
        out_tris[i].a=a;
        out_tris[i].b=b;
        out_tris[i].c=c;
        out_tris[i].n=vec3_norm(vec3_cross(ab,ac));
    }
}

static void prop_custom_collision_world_shape(const Prop *p,const PropCustomCollisionBox *box,
                                              Vec3 *out_center,Vec3 *out_half,float *out_yaw_deg,float *out_radius){
    Vec3 center={0};
    Vec3 half={0};
    float scale=1.0f;
    if(!p||!box) return;
    center=mat4_transform_point(prop_world((Prop*)p),box->center);
    scale=fabsf(p->scale);
    if(scale<1e-4f) scale=1.0f;
    half=(Vec3){box->half.x*scale,box->half.y*scale,box->half.z*scale};
    if(out_center) *out_center=center;
    if(out_half) *out_half=half;
    if(out_yaw_deg) *out_yaw_deg=p->rot_y+box->yaw_deg;
    if(out_radius) *out_radius=fmaxf(half.x,half.z);
}

static void static_collision_world_rebuild(void){
    StaticCollisionWorld *cw=&g_static_collision_world;
    memset(cw->cell_counts,0,sizeof(cw->cell_counts));
    cw->collider_count=0;
    cw->obstacle_count=0;

    for(int pi=0;pi<g_props.count;pi++){
        AABB bounds;
        Prop *p=&g_props.list[pi];
        if(!p->active||p->stream_state!=PROP_LOADED) continue;
        if(prop_has_custom_collision(p)){
            for(int ci=0;ci<p->custom_coll_count;ci++){
                Vec3 center,half;
                float yaw_deg=0.0f;
                float radius=0.0f;
                prop_custom_collision_world_aabb(p,&p->custom_coll[ci],&bounds);
                prop_custom_collision_world_shape(p,&p->custom_coll[ci],&center,&half,&yaw_deg,&radius);
                static_collision_world_insert(cw,
                                              p->custom_coll[ci].shape==PROP_CUSTOM_COLL_SHAPE_SPHERE?STATIC_COLL_SHAPE_SPHERE:
                                              (p->custom_coll[ci].shape==PROP_CUSTOM_COLL_SHAPE_CIRCLE?STATIC_COLL_SHAPE_CIRCLE:
                                               (p->custom_coll[ci].shape==PROP_CUSTOM_COLL_SHAPE_OVAL?STATIC_COLL_SHAPE_OVAL:STATIC_COLL_SHAPE_OBOX)),
                                              STATIC_COLL_SOURCE_PROP,
                                              pi,
                                              true,
                                              &bounds,
                                              &center,
                                              &half,
                                              yaw_deg,
                                              0.0f,
                                              radius);
            }
            continue;
        }
        if(p->coll_type==PROP_COLL_NONE) continue;
        if(p->coll_type==PROP_COLL_AABB) bounds=p->aabb;
        else prop_compute_world_bounds_box(p,&bounds);
        static_collision_world_insert(cw,
                                      (p->coll_type==PROP_COLL_MESH)?STATIC_COLL_SHAPE_MESH:STATIC_COLL_SHAPE_AABB,
                                      STATIC_COLL_SOURCE_PROP,
                                      pi,
                                      true,
                                      &bounds,
                                      NULL,NULL,0.0f,0.0f,0.0f);
    }

    for(int si=0;si<g_surfaces.count;si++){
        SurfacePiece *sp=&g_surfaces.items[si];
        AABB bounds;
        if(!sp->active||sp->coll_type==PROP_COLL_NONE) continue;
        surface_piece_aabb(sp,&bounds);
        static_collision_world_insert(cw,
                                      STATIC_COLL_SHAPE_AABB,
                                      STATIC_COLL_SOURCE_SURFACE,
                                      si,
                                      sp->kind==SURFACE_PIECE_WALL,
                                      &bounds,
                                      NULL,NULL,0.0f,0.0f,0.0f);
    }

    for(int ci=0;ci<g_collision_volumes.count;ci++){
        CollisionVolume *cv=&g_collision_volumes.items[ci];
        AABB bounds;
        Vec3 center,half;
        if(!cv->active||!cv->enabled) continue;
        collision_volume_aabb(cv,&bounds);
        center=cv->runtime_pos;
        half=(Vec3){cv->width*0.5f,cv->height*0.5f,cv->depth*0.5f};
        if(collision_volume_shape_sanitize(cv->shape)==COLLISION_VOLUME_SHAPE_OVAL){
            static_collision_world_insert(cw,
                                          STATIC_COLL_SHAPE_OVAL,
                                          STATIC_COLL_SOURCE_COLLISION_VOLUME,
                                          ci,
                                          cv->nav_blocker,
                                          &bounds,
                                          &center,&half,
                                          cv->yaw_deg,0.0f,0.0f);
        }else if(fabsf(cv->pitch_deg)<=0.001f){
            static_collision_world_insert(cw,
                                          STATIC_COLL_SHAPE_OBOX,
                                          STATIC_COLL_SOURCE_COLLISION_VOLUME,
                                          ci,
                                          cv->nav_blocker,
                                          &bounds,
                                          &center,&half,
                                          cv->yaw_deg,0.0f,0.0f);
        }else{
            int insert_idx;
            CTri tris[12];
            collision_volume_box_build_mesh(cv,tris,&bounds);
            insert_idx=cw->collider_count;
            static_collision_world_insert(cw,
                                          STATIC_COLL_SHAPE_MESH_VOLUME,
                                          STATIC_COLL_SOURCE_COLLISION_VOLUME,
                                          ci,
                                          cv->nav_blocker,
                                          &bounds,
                                          &center,&half,
                                          cv->yaw_deg,cv->pitch_deg,0.0f);
            if(insert_idx<cw->collider_count){
                memcpy(cw->colliders[insert_idx].mesh_tris,tris,sizeof(tris));
                cw->colliders[insert_idx].mesh_tri_count=12;
            }
        }
    }

    cw->dirty=false;
}

static void static_collision_world_ensure_ready(void){
    if(g_static_collision_world.dirty) static_collision_world_rebuild();
}

static void static_collision_world_mark_dirty(void){
    g_static_collision_world.dirty=true;
    props_visibility_invalidate();
}

static int static_collision_query_compare(const void *lhs,const void *rhs){
    const int a=*(const int*)lhs;
    const int b=*(const int*)rhs;
    return (a>b)-(a<b);
}

static int static_collision_world_query(const AABB *query_box,int *out_indices,int max_indices){
    StaticCollisionWorld *cw=&g_static_collision_world;
    int count=0;
    int x0,x1,z0,z1;
    if(!query_box||!out_indices||max_indices<=0) return 0;
    static_collision_world_ensure_ready();
    if(++cw->query_stamp==0){
        memset(cw->query_marks,0,sizeof(cw->query_marks));
        cw->query_stamp=1;
    }
    x0=static_collision_world_cell_x(query_box->min.x);
    x1=static_collision_world_cell_x(query_box->max.x);
    z0=static_collision_world_cell_z(query_box->min.z);
    z1=static_collision_world_cell_z(query_box->max.z);
    for(int z=z0;z<=z1;z++){
        for(int x=x0;x<=x1;x++){
            int cell=static_collision_world_cell_index(x,z);
            int cell_count=cw->cell_counts[cell];
            for(int j=0;j<cell_count;j++){
                int ci=cw->cell_items[cell][j];
                const AABB *b=&cw->colliders[ci].bounds;
                if(cw->query_marks[ci]!=cw->query_stamp &&
                   query_box->min.x<=b->max.x&&query_box->max.x>=b->min.x&&
                   query_box->min.y<=b->max.y&&query_box->max.y>=b->min.y&&
                   query_box->min.z<=b->max.z&&query_box->max.z>=b->min.z){
                    cw->query_marks[ci]=cw->query_stamp;
                    if(count<max_indices) out_indices[count++]=ci;
                }
            }
        }
    }
    qsort(out_indices,(size_t)count,sizeof(out_indices[0]),static_collision_query_compare);
    return count;
}

static bool static_collision_resolve_aabb(const AABB *box,Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    float py,ptop,left,right,front,back,ox,oz;
    bool over_box;
    if(!box||!pos||!vel||!on_ground) return false;
    py=pos->y;
    ptop=py+height;
    if(py>box->max.y+0.05f||ptop<box->min.y-0.05f) return false;
    if(pos->x+radius<box->min.x||pos->x-radius>box->max.x) return false;
    if(pos->z+radius<box->min.z||pos->z-radius>box->max.z) return false;
    over_box=(pos->x>box->min.x-radius&&pos->x<box->max.x+radius&&
              pos->z>box->min.z-radius&&pos->z<box->max.z+radius);
    if(over_box&&py<=box->max.y+0.25f&&py>=box->max.y-0.5f&&vel->y<=0.0f){
        pos->y=box->max.y;
        vel->y=0.0f;
        *on_ground=true;
        return true;
    }
    if(over_box&&ptop>=box->min.y-0.05f&&py<box->min.y&&vel->y>0.0f){
        pos->y=box->min.y-height-0.02f;
        vel->y=0.0f;
        return true;
    }
    left=pos->x+radius-box->min.x;
    right=box->max.x-(pos->x-radius);
    front=pos->z+radius-box->min.z;
    back=box->max.z-(pos->z-radius);
    if(left<0||right<0||front<0||back<0) return false;
    ox=left<right?-left:right;
    oz=front<back?-front:back;
    if(fabsf(ox)<fabsf(oz)) pos->x+=ox;
    else pos->z+=oz;
    return true;
}

int static_collision_world_obstacle_count(void){
    static_collision_world_ensure_ready();
    return g_static_collision_world.obstacle_count;
}

bool static_collision_world_obstacle_aabb(int idx,AABB *out_box){
    StaticCollisionWorld *cw=&g_static_collision_world;
    static_collision_world_ensure_ready();
    if(idx<0||idx>=cw->obstacle_count||!out_box) return false;
    *out_box=cw->colliders[cw->obstacle_indices[idx]].bounds;
    return true;
}

static bool static_collision_capsule_overlaps_aabb(Vec3 pos,float height,float radius,const AABB *box){
    float py,ptop;
    if(!box) return false;
    py=pos.y;
    ptop=py+height;
    if(py>box->max.y+0.05f||ptop<box->min.y-0.05f) return false;
    if(pos.x+radius<box->min.x||pos.x-radius>box->max.x) return false;
    if(pos.z+radius<box->min.z||pos.z-radius>box->max.z) return false;
    return true;
}

static bool static_collision_capsule_overlaps_round(Vec3 pos,float height,float radius,const StaticCollider *coll){
    Vec3 d;
    float py,ptop,rr,dist2;
    if(!coll) return false;
    py=pos.y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    d=(Vec3){pos.x-coll->center.x,0.0f,pos.z-coll->center.z};
    rr=radius+coll->radius;
    dist2=d.x*d.x+d.z*d.z;
    return dist2<=rr*rr;
}

static bool static_collision_capsule_overlaps_oval(Vec3 pos,float height,float radius,const StaticCollider *coll){
    Vec3 local;
    float py,ptop,ax,bz,norm;
    if(!coll) return false;
    py=pos.y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    local=static_collision_rotate_y(vec3_sub(pos,coll->center),-coll->yaw_deg);
    ax=fmaxf(0.05f,coll->half.x+radius);
    bz=fmaxf(0.05f,coll->half.z+radius);
    norm=(local.x*local.x)/(ax*ax)+(local.z*local.z)/(bz*bz);
    return norm<=1.0f;
}

static bool static_collision_capsule_overlaps_obox(Vec3 pos,float height,float radius,const StaticCollider *coll){
    Vec3 local;
    AABB box;
    float py,ptop;
    if(!coll) return false;
    py=pos.y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    local=static_collision_rotate_y(vec3_sub(pos,coll->center),-coll->yaw_deg);
    box.min=(Vec3){-coll->half.x,coll->center.y-coll->half.y,-coll->half.z};
    box.max=(Vec3){ coll->half.x,coll->center.y+coll->half.y, coll->half.z};
    return local.x+radius>=box.min.x&&local.x-radius<=box.max.x&&
           local.z+radius>=box.min.z&&local.z-radius<=box.max.z;
}

static bool static_collision_point_in_expanded_box_xz(Vec3 pos,float radius,const AABB *box){
    return box &&
           pos.x>=box->min.x-radius&&pos.x<=box->max.x+radius&&
           pos.z>=box->min.z-radius&&pos.z<=box->max.z+radius;
}

static bool static_collision_point_in_expanded_oval_xz(Vec3 pos,float radius,const StaticCollider *coll){
    Vec3 local;
    float ax,bz,norm;
    if(!coll) return false;
    local=static_collision_rotate_y(vec3_sub(pos,coll->center),-coll->yaw_deg);
    ax=fmaxf(0.05f,coll->half.x+radius);
    bz=fmaxf(0.05f,coll->half.z+radius);
    norm=(local.x*local.x)/(ax*ax)+(local.z*local.z)/(bz*bz);
    return norm<=1.0f;
}

static bool static_collision_point_in_expanded_obox_xz(Vec3 pos,float radius,const StaticCollider *coll){
    Vec3 local;
    if(!coll) return false;
    local=static_collision_rotate_y(vec3_sub(pos,coll->center),-coll->yaw_deg);
    return local.x>=-coll->half.x-radius&&local.x<=coll->half.x+radius&&
           local.z>=-coll->half.z-radius&&local.z<=coll->half.z+radius;
}

static bool static_collision_point_in_expanded_round_xz(Vec3 pos,float radius,const StaticCollider *coll){
    Vec3 d;
    float rr;
    if(!coll) return false;
    d=(Vec3){pos.x-coll->center.x,0.0f,pos.z-coll->center.z};
    rr=radius+coll->radius;
    return d.x*d.x+d.z*d.z<=rr*rr;
}

static bool static_collision_sweep_circle_aabb_xz(Vec3 start,Vec3 delta,float radius,const AABB *box,
                                                  float *out_t,Vec3 *out_normal){
    float exmin,exmax,ezmin,ezmax;
    float txmin=-1e30f,txmax=1e30f,tzmin=-1e30f,tzmax=1e30f;
    float t_enter,t_exit;
    Vec3 normal={0,0,0};
    if(!box||!out_t||!out_normal) return false;
    exmin=box->min.x-radius;
    exmax=box->max.x+radius;
    ezmin=box->min.z-radius;
    ezmax=box->max.z+radius;
    if(start.x>=exmin&&start.x<=exmax&&start.z>=ezmin&&start.z<=ezmax) return false;
    if(fabsf(delta.x)>1e-6f){
        float inv_dx=1.0f/delta.x;
        float tx1=(exmin-start.x)*inv_dx;
        float tx2=(exmax-start.x)*inv_dx;
        txmin=fminf(tx1,tx2);
        txmax=fmaxf(tx1,tx2);
    }else if(start.x<exmin||start.x>exmax){
        return false;
    }
    if(fabsf(delta.z)>1e-6f){
        float inv_dz=1.0f/delta.z;
        float tz1=(ezmin-start.z)*inv_dz;
        float tz2=(ezmax-start.z)*inv_dz;
        tzmin=fminf(tz1,tz2);
        tzmax=fmaxf(tz1,tz2);
    }else if(start.z<ezmin||start.z>ezmax){
        return false;
    }
    t_enter=fmaxf(txmin,tzmin);
    t_exit=fminf(txmax,tzmax);
    if(t_enter>t_exit||t_exit<0.0f||t_enter>1.0f) return false;
    if(txmin>tzmin){
        normal=(delta.x>0.0f)?(Vec3){-1,0,0}:(Vec3){1,0,0};
    }else{
        normal=(delta.z>0.0f)?(Vec3){0,0,-1}:(Vec3){0,0,1};
    }
    *out_t=clampf(t_enter,0.0f,1.0f);
    *out_normal=normal;
    return true;
}

static bool static_collision_sweep_circle_oval_xz(Vec3 start,Vec3 delta,float radius,const StaticCollider *coll,
                                                  float *out_t,Vec3 *out_normal){
    Vec3 local_start,local_delta;
    float ax,bz,a,b,c,disc,t_hit;
    if(!coll||!out_t||!out_normal) return false;
    local_start=static_collision_rotate_y(vec3_sub(start,coll->center),-coll->yaw_deg);
    local_delta=static_collision_rotate_y(delta,-coll->yaw_deg);
    ax=fmaxf(0.05f,coll->half.x+radius);
    bz=fmaxf(0.05f,coll->half.z+radius);
    if((local_start.x*local_start.x)/(ax*ax)+(local_start.z*local_start.z)/(bz*bz)<=1.0f) return false;
    a=(local_delta.x*local_delta.x)/(ax*ax)+(local_delta.z*local_delta.z)/(bz*bz);
    if(a<=1e-6f) return false;
    b=2.0f*((local_start.x*local_delta.x)/(ax*ax)+(local_start.z*local_delta.z)/(bz*bz));
    c=(local_start.x*local_start.x)/(ax*ax)+(local_start.z*local_start.z)/(bz*bz)-1.0f;
    disc=b*b-4.0f*a*c;
    if(disc<0.0f) return false;
    t_hit=(-b-sqrtf(disc))/(2.0f*a);
    if(t_hit<0.0f||t_hit>1.0f) return false;
    {
        Vec3 hit=vec3_add(local_start,vec3_scale(local_delta,t_hit));
        Vec3 local_n={(ax>1e-6f)?(hit.x/(ax*ax)):0.0f,0.0f,(bz>1e-6f)?(hit.z/(bz*bz)):1.0f};
        local_n=vec3_norm(local_n);
        if(vec3_len(local_n)<=1e-6f) local_n=(Vec3){0,0,1};
        *out_t=t_hit;
        *out_normal=static_collision_rotate_y(local_n,coll->yaw_deg);
    }
    return true;
}

static bool static_collision_sweep_circle_obox_xz(Vec3 start,Vec3 delta,float radius,const StaticCollider *coll,
                                                  float *out_t,Vec3 *out_normal){
    AABB box;
    Vec3 local_start,local_delta,local_normal;
    if(!coll||!out_t||!out_normal) return false;
    local_start=static_collision_rotate_y(vec3_sub(start,coll->center),-coll->yaw_deg);
    local_delta=static_collision_rotate_y(delta,-coll->yaw_deg);
    box.min=(Vec3){-coll->half.x,coll->center.y-coll->half.y,-coll->half.z};
    box.max=(Vec3){ coll->half.x,coll->center.y+coll->half.y, coll->half.z};
    if(!static_collision_sweep_circle_aabb_xz(local_start,local_delta,radius,&box,out_t,&local_normal)) return false;
    *out_normal=static_collision_rotate_y(local_normal,coll->yaw_deg);
    return true;
}

static bool static_collision_sweep_circle_round_xz(Vec3 start,Vec3 delta,float radius,const StaticCollider *coll,
                                                   float *out_t,Vec3 *out_normal){
    Vec3 rel;
    float a,b,c,disc,rr,t_hit;
    if(!coll||!out_t||!out_normal) return false;
    rel=(Vec3){start.x-coll->center.x,0.0f,start.z-coll->center.z};
    rr=radius+coll->radius;
    if(rel.x*rel.x+rel.z*rel.z<=rr*rr) return false;
    a=delta.x*delta.x+delta.z*delta.z;
    if(a<=1e-6f) return false;
    b=2.0f*(rel.x*delta.x+rel.z*delta.z);
    c=rel.x*rel.x+rel.z*rel.z-rr*rr;
    disc=b*b-4.0f*a*c;
    if(disc<0.0f) return false;
    t_hit=(-b-sqrtf(disc))/(2.0f*a);
    if(t_hit<0.0f||t_hit>1.0f) return false;
    {
        Vec3 hit=(Vec3){start.x+delta.x*t_hit,start.y,start.z+delta.z*t_hit};
        Vec3 n=vec3_norm((Vec3){hit.x-coll->center.x,0.0f,hit.z-coll->center.z});
        if(vec3_len(n)<=1e-6f) n=(Vec3){0,0,1};
        *out_t=t_hit;
        *out_normal=n;
    }
    return true;
}

static bool static_collision_mesh_volume_sweep_xz(const StaticCollider *coll,Vec3 start,Vec3 delta,float radius,float height,
                                                  float *out_t,Vec3 *out_normal){
    float sweep_min_x,sweep_max_x,sweep_min_z,sweep_max_z;
    float py,ptop;
    bool hit=false;
    float best_t=1.0f;
    Vec3 best_n={0,0,0};
    if(!coll||!out_t||!out_normal||coll->mesh_tri_count<=0) return false;
    sweep_min_x=fminf(start.x,start.x+delta.x)-radius;
    sweep_max_x=fmaxf(start.x,start.x+delta.x)+radius;
    sweep_min_z=fminf(start.z,start.z+delta.z)-radius;
    sweep_max_z=fmaxf(start.z,start.z+delta.z)+radius;
    if(sweep_max_x<coll->bounds.min.x||sweep_min_x>coll->bounds.max.x||
       sweep_max_z<coll->bounds.min.z||sweep_min_z>coll->bounds.max.z)
        return false;
    py=start.y;
    ptop=py+height;
    for(int ti=0;ti<coll->mesh_tri_count;ti++){
        const CTri *t=&coll->mesh_tris[ti];
        float tmin,tmax;
        Vec3 edges[3][2];
        if(fabsf(t->n.y)>0.3f) continue;
        tmin=fminf(t->a.y,fminf(t->b.y,t->c.y));
        tmax=fmaxf(t->a.y,fmaxf(t->b.y,t->c.y));
        if(py>tmax+0.05f||ptop<tmin-0.05f) continue;
        edges[0][0]=t->a; edges[0][1]=t->b;
        edges[1][0]=t->b; edges[1][1]=t->c;
        edges[2][0]=t->c; edges[2][1]=t->a;
        for(int e=0;e<3;e++){
            float hit_t;
            Vec3 hit_n;
            if(sweep_circle_segment_xz(start,delta,radius,edges[e][0],edges[e][1],&hit_t,&hit_n)&&hit_t<best_t){
                best_t=hit_t;
                best_n=hit_n;
                hit=true;
            }
        }
    }
    if(hit){
        *out_t=best_t;
        *out_normal=best_n;
    }
    return hit;
}

static bool static_collision_mesh_volume_resolve(const StaticCollider *coll,Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    float py,ptop;
    const float step_clearance=0.42f;
    const float floor_snap_up=0.75f;
    const float floor_snap_down=0.45f;
    const float head_clearance=0.08f;
    float best_floor_y=-1e9f;
    bool on_floor=false;
    bool changed=false;
    if(!coll||!pos||!vel||!on_ground||coll->mesh_tri_count<=0) return false;
    if(pos->x+radius<coll->bounds.min.x||pos->x-radius>coll->bounds.max.x||
       pos->z+radius<coll->bounds.min.z||pos->z-radius>coll->bounds.max.z||
       pos->y>coll->bounds.max.y+1.0f||pos->y+height<coll->bounds.min.y-1.0f)
        return false;

    py=pos->y; ptop=py+height;
    for(int ti=0;ti<coll->mesh_tri_count;ti++){
        const CTri *t=&coll->mesh_tris[ti];
        if(t->n.y<0.3f) continue;
        {
            float tmax=fmaxf(t->a.y,fmaxf(t->b.y,t->c.y));
            float tmin=fminf(t->a.y,fminf(t->b.y,t->c.y));
            float px=pos->x,pz=pos->z;
            float d0,d1,d2,floor_y;
            if(py>tmax+floor_snap_up||py<tmin-floor_snap_down) continue;
            d0=(px-t->a.x)*(t->b.z-t->a.z)-(pz-t->a.z)*(t->b.x-t->a.x);
            d1=(px-t->b.x)*(t->c.z-t->b.z)-(pz-t->b.z)*(t->c.x-t->b.x);
            d2=(px-t->c.x)*(t->a.z-t->c.z)-(pz-t->c.z)*(t->a.x-t->c.x);
            if(!((d0>=0&&d1>=0&&d2>=0)||(d0<=0&&d1<=0&&d2<=0))) continue;
            if(fabsf(t->n.y)>1e-4f){
                float D=t->n.x*t->a.x+t->n.y*t->a.y+t->n.z*t->a.z;
                floor_y=(D-t->n.x*px-t->n.z*pz)/t->n.y;
            }else{
                floor_y=tmax;
            }
            if(floor_y>best_floor_y){ best_floor_y=floor_y; on_floor=true; }
        }
    }
    if(on_floor&&py<best_floor_y+floor_snap_up&&py>best_floor_y-floor_snap_down){
        pos->y=best_floor_y;
        vel->y=0.0f;
        *on_ground=true;
        changed=true;
    }

    py=pos->y; ptop=py+height;
    for(int ti=0;ti<coll->mesh_tri_count;ti++){
        const CTri *t=&coll->mesh_tris[ti];
        float px,pz,d0,d1,d2,ceil_y;
        if(t->n.y>-0.3f) continue;
        if(ptop<fminf(t->a.y,fminf(t->b.y,t->c.y))-head_clearance) continue;
        px=pos->x; pz=pos->z;
        d0=(px-t->a.x)*(t->b.z-t->a.z)-(pz-t->a.z)*(t->b.x-t->a.x);
        d1=(px-t->b.x)*(t->c.z-t->b.z)-(pz-t->b.z)*(t->c.x-t->b.x);
        d2=(px-t->c.x)*(t->a.z-t->c.z)-(pz-t->c.z)*(t->a.x-t->c.x);
        if(!((d0>=0&&d1>=0&&d2>=0)||(d0<=0&&d1<=0&&d2<=0))) continue;
        if(fabsf(t->n.y)>1e-4f){
            float D=t->n.x*t->a.x+t->n.y*t->a.y+t->n.z*t->a.z;
            ceil_y=(D-t->n.x*px-t->n.z*pz)/t->n.y;
        }else{
            ceil_y=fminf(t->a.y,fminf(t->b.y,t->c.y));
        }
        if(ptop>ceil_y-head_clearance&&py<ceil_y){
            pos->y=ceil_y-height-head_clearance;
            py=pos->y;
            ptop=py+height;
            if(vel->y>0.0f) vel->y=0.0f;
            changed=true;
        }
    }

    py=pos->y; ptop=py+height;
    for(int ti=0;ti<coll->mesh_tri_count;ti++){
        const CTri *t=&coll->mesh_tris[ti];
        float tmin,tmax,px,pz;
        float verts[3][2];
        float d0,d1,d2;
        bool inside;
        if(t->n.y>0.3f||t->n.y<-0.3f) continue;
        tmin=fminf(t->a.y,fminf(t->b.y,t->c.y));
        tmax=fmaxf(t->a.y,fmaxf(t->b.y,t->c.y));
        if(on_floor&&tmax<=py+step_clearance) continue;
        if(py>tmax+0.05f||ptop<tmin-0.05f) continue;
        px=pos->x; pz=pos->z;
        verts[0][0]=t->a.x; verts[0][1]=t->a.z;
        verts[1][0]=t->b.x; verts[1][1]=t->b.z;
        verts[2][0]=t->c.x; verts[2][1]=t->c.z;
        d0=(px-verts[0][0])*(verts[1][1]-verts[0][1])-(pz-verts[0][1])*(verts[1][0]-verts[0][0]);
        d1=(px-verts[1][0])*(verts[2][1]-verts[1][1])-(pz-verts[1][1])*(verts[2][0]-verts[1][0]);
        d2=(px-verts[2][0])*(verts[0][1]-verts[2][1])-(pz-verts[2][1])*(verts[0][0]-verts[2][0]);
        inside=(d0>=0&&d1>=0&&d2>=0)||(d0<=0&&d1<=0&&d2<=0);
        if(inside){
            float nl=sqrtf(t->n.x*t->n.x+t->n.z*t->n.z);
            if(nl>0.01f){
                pos->x+=t->n.x/nl*radius;
                pos->z+=t->n.z/nl*radius;
                changed=true;
            }
            continue;
        }
        for(int e=0;e<3;e++){
            float ax=verts[e][0],az=verts[e][1],bx=verts[(e+1)%3][0],bz=verts[(e+1)%3][1];
            float nx,nz;
            float d=seg_dist_xz(px,pz,ax,az,bx,bz,&nx,&nz);
            if(d<radius&&d>1e-5f){
                float pen=radius-d;
                pos->x+=nx/d*pen;
                pos->z+=nz/d*pen;
                changed=true;
            }
        }
    }
    return changed;
}

static bool static_collision_collider_blocks_side(const StaticCollider *coll,Vec3 pos,float height){
    if(!coll) return false;
    if(coll->source==STATIC_COLL_SOURCE_SURFACE){
        SurfacePiece *sp=&g_surfaces.items[coll->source_idx];
        if(!sp->active||sp->kind==SURFACE_PIECE_FLOOR) return false;
    }
    if(coll->bounds.max.y<=pos.y+0.05f) return false;
    if(coll->bounds.min.y>=pos.y+height-0.05f) return false;
    return true;
}

static bool static_collision_try_step_move(Vec3 *io_pos,Vec3 remaining,float height,float radius,
                                           const StaticCollider *hit_coll){
    const float step_up=0.72f;
    const float step_down=0.85f;
    Vec3 stepped;
    AABB probe_box;
    int candidates[STATIC_COLL_MAX];
    int count;
    if(!io_pos||!hit_coll) return false;
    {
        float top_y=(hit_coll->shape==STATIC_COLL_SHAPE_OBOX||hit_coll->shape==STATIC_COLL_SHAPE_SPHERE||hit_coll->shape==STATIC_COLL_SHAPE_CIRCLE||hit_coll->shape==STATIC_COLL_SHAPE_OVAL)
            ?(hit_coll->center.y+hit_coll->half.y)
            :hit_coll->bounds.max.y;
        if(hit_coll->shape==STATIC_COLL_SHAPE_MESH||hit_coll->shape==STATIC_COLL_SHAPE_MESH_VOLUME) return false;
        if(top_y<io_pos->y-step_down||top_y>io_pos->y+step_up) return false;
        stepped=*io_pos;
        stepped.y=top_y+0.02f;
    }
    probe_box.min=(Vec3){
        fminf(stepped.x,stepped.x+remaining.x)-radius,
        stepped.y-0.1f,
        fminf(stepped.z,stepped.z+remaining.z)-radius
    };
    probe_box.max=(Vec3){
        fmaxf(stepped.x,stepped.x+remaining.x)+radius,
        stepped.y+height+0.1f,
        fmaxf(stepped.z,stepped.z+remaining.z)+radius
    };
    count=static_collision_world_query(&probe_box,candidates,STATIC_COLL_MAX);
    for(int i=0;i<count;i++){
        StaticCollider *coll=&g_static_collision_world.colliders[candidates[i]];
        Vec3 test_end;
        if(coll==hit_coll) continue;
        if(!static_collision_collider_blocks_side(coll,stepped,height)) continue;
        test_end=vec3_add(stepped,remaining);
        if((coll->shape==STATIC_COLL_SHAPE_AABB &&
            (static_collision_capsule_overlaps_aabb(test_end,height,radius,&coll->bounds)||
             static_collision_point_in_expanded_box_xz(test_end,radius,&coll->bounds)))||
           (coll->shape==STATIC_COLL_SHAPE_OBOX &&
            (static_collision_capsule_overlaps_obox(test_end,height,radius,coll)||
             static_collision_point_in_expanded_obox_xz(test_end,radius,coll)))||
           (coll->shape==STATIC_COLL_SHAPE_OVAL &&
            (static_collision_capsule_overlaps_oval(test_end,height,radius,coll)||
             static_collision_point_in_expanded_oval_xz(test_end,radius,coll)))||
           (coll->shape==STATIC_COLL_SHAPE_MESH_VOLUME &&
            static_collision_capsule_overlaps_aabb(test_end,height,radius,&coll->bounds))||
           ((coll->shape==STATIC_COLL_SHAPE_SPHERE||coll->shape==STATIC_COLL_SHAPE_CIRCLE) &&
            (static_collision_capsule_overlaps_round(test_end,height,radius,coll)||
             static_collision_point_in_expanded_round_xz(test_end,radius,coll)))){
            return false;
        }
    }
    *io_pos=vec3_add(stepped,remaining);
    return true;
}

void static_collision_world_move_capsule(Vec3 *pos,Vec3 move,Vec3 *vel,bool *on_ground,float height,float radius){
    const float slide_epsilon=0.0025f;
    const int max_slides=4;
    Vec3 cur;
    Vec3 remaining;
    if(!pos||!vel||!on_ground) return;
    static_collision_world_ensure_ready();
    cur=*pos;
    cur.y+=move.y;
    remaining=(Vec3){move.x,0.0f,move.z};
    for(int iter=0;iter<max_slides;iter++){
        AABB sweep_box;
        int candidates[STATIC_COLL_MAX];
        int count;
        float best_t=1.0f;
        Vec3 best_n={0,0,0};
        StaticCollider *best_coll=NULL;
        if((remaining.x*remaining.x+remaining.z*remaining.z)<=1e-6f) break;
        sweep_box.min=(Vec3){
            fminf(cur.x,cur.x+remaining.x)-radius,
            cur.y-0.2f,
            fminf(cur.z,cur.z+remaining.z)-radius
        };
        sweep_box.max=(Vec3){
            fmaxf(cur.x,cur.x+remaining.x)+radius,
            cur.y+height+0.8f,
            fmaxf(cur.z,cur.z+remaining.z)+radius
        };
        count=static_collision_world_query(&sweep_box,candidates,STATIC_COLL_MAX);
        for(int i=0;i<count;i++){
            StaticCollider *coll=&g_static_collision_world.colliders[candidates[i]];
            float hit_t;
            Vec3 hit_n;
            if(!static_collision_collider_blocks_side(coll,cur,height)) continue;
            if(coll->shape==STATIC_COLL_SHAPE_AABB){
                if(static_collision_sweep_circle_aabb_xz(cur,remaining,radius,&coll->bounds,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }else if(coll->shape==STATIC_COLL_SHAPE_OBOX){
                if(static_collision_sweep_circle_obox_xz(cur,remaining,radius,coll,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }else if(coll->shape==STATIC_COLL_SHAPE_OVAL){
                if(static_collision_sweep_circle_oval_xz(cur,remaining,radius,coll,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }else if(coll->shape==STATIC_COLL_SHAPE_MESH_VOLUME){
                if(static_collision_mesh_volume_sweep_xz(coll,cur,remaining,radius,height,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }else if(coll->shape==STATIC_COLL_SHAPE_SPHERE||coll->shape==STATIC_COLL_SHAPE_CIRCLE){
                if(static_collision_sweep_circle_round_xz(cur,remaining,radius,coll,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }else if(coll->source==STATIC_COLL_SOURCE_PROP){
                Prop *p=&g_props.list[coll->source_idx];
                if(trimesh_sweep_walls(&p->trimesh,cur,remaining,radius,height,&hit_t,&hit_n) &&
                   hit_t<best_t){
                    best_t=hit_t;
                    best_n=hit_n;
                    best_coll=coll;
                }
            }
        }
        if(!best_coll){
            cur=vec3_add(cur,remaining);
            remaining=(Vec3){0,0,0};
            break;
        }
        if(best_t>0.0f){
            float safe_t=fmaxf(0.0f,best_t-slide_epsilon/fmaxf(vec3_len(remaining),0.001f));
            cur=vec3_add(cur,vec3_scale(remaining,safe_t));
        }
        {
            Vec3 rem_after=vec3_scale(remaining,fmaxf(0.0f,1.0f-best_t));
            if(static_collision_try_step_move(&cur,rem_after,height,radius,best_coll)){
                remaining=(Vec3){0,0,0};
                *on_ground=true;
                if(vel->y<0.0f) vel->y=0.0f;
                break;
            }
            cur=vec3_add(cur,vec3_scale(best_n,slide_epsilon));
            {
                float into=vec3_dot(rem_after,best_n);
                if(into<0.0f) rem_after=vec3_sub(rem_after,vec3_scale(best_n,into));
                remaining=(Vec3){rem_after.x,0.0f,rem_after.z};
                if(fabsf(best_n.x)>0.5f) vel->x=0.0f;
                if(fabsf(best_n.z)>0.5f) vel->z=0.0f;
            }
        }
    }
    *pos=cur;
}

static bool static_collision_resolve_obox(const StaticCollider *coll,Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    Vec3 local_pos,delta_local,delta_world;
    AABB box;
    float py,ptop,left,right,front,back,ox,oz;
    bool over_box;
    if(!coll||!pos||!vel||!on_ground) return false;
    py=pos->y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    local_pos=static_collision_rotate_y(vec3_sub(*pos,coll->center),-coll->yaw_deg);
    box.min=(Vec3){-coll->half.x,coll->center.y-coll->half.y,-coll->half.z};
    box.max=(Vec3){ coll->half.x,coll->center.y+coll->half.y, coll->half.z};
    if(local_pos.x+radius<box.min.x||local_pos.x-radius>box.max.x) return false;
    if(local_pos.z+radius<box.min.z||local_pos.z-radius>box.max.z) return false;
    over_box=(local_pos.x>box.min.x-radius&&local_pos.x<box.max.x+radius&&
              local_pos.z>box.min.z-radius&&local_pos.z<box.max.z+radius);
    if(over_box&&py<=coll->center.y+coll->half.y+0.25f&&py>=coll->center.y+coll->half.y-0.5f&&vel->y<=0.0f){
        pos->y=coll->center.y+coll->half.y;
        vel->y=0.0f;
        *on_ground=true;
        return true;
    }
    if(over_box&&ptop>=coll->center.y-coll->half.y-0.05f&&py<coll->center.y-coll->half.y&&vel->y>0.0f){
        pos->y=coll->center.y-coll->half.y-height-0.02f;
        vel->y=0.0f;
        return true;
    }
    left=local_pos.x+radius-box.min.x;
    right=box.max.x-(local_pos.x-radius);
    front=local_pos.z+radius-box.min.z;
    back=box.max.z-(local_pos.z-radius);
    if(left<0||right<0||front<0||back<0) return false;
    ox=left<right?-left:right;
    oz=front<back?-front:back;
    delta_local=(fabsf(ox)<fabsf(oz))?(Vec3){ox,0,0}:(Vec3){0,0,oz};
    delta_world=static_collision_rotate_y(delta_local,coll->yaw_deg);
    pos->x+=delta_world.x;
    pos->z+=delta_world.z;
    return true;
}

static bool static_collision_resolve_round(const StaticCollider *coll,Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    Vec3 d,push;
    float py,ptop,dist2,dist,rr;
    if(!coll||!pos||!vel||!on_ground) return false;
    py=pos->y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    d=(Vec3){pos->x-coll->center.x,0.0f,pos->z-coll->center.z};
    dist2=d.x*d.x+d.z*d.z;
    rr=radius+coll->radius;
    if(dist2>rr*rr) return false;
    if(dist2<1e-6f) d=(Vec3){1,0,0};
    dist=sqrtf(fmaxf(dist2,1e-6f));
    if(py<=coll->center.y+coll->half.y+0.25f&&py>=coll->center.y+coll->half.y-0.5f&&vel->y<=0.0f&&dist<=coll->radius){
        pos->y=coll->center.y+coll->half.y;
        vel->y=0.0f;
        *on_ground=true;
        return true;
    }
    if(ptop>=coll->center.y-coll->half.y-0.05f&&py<coll->center.y-coll->half.y&&vel->y>0.0f&&dist<=coll->radius){
        pos->y=coll->center.y-coll->half.y-height-0.02f;
        vel->y=0.0f;
        return true;
    }
    push=vec3_scale(vec3_norm(d),rr-dist);
    pos->x+=push.x;
    pos->z+=push.z;
    return true;
}

static bool static_collision_resolve_oval(const StaticCollider *coll,Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    Vec3 local,nudge_local,nudge_world;
    float py,ptop,ax,bz,norm;
    if(!coll||!pos||!vel||!on_ground) return false;
    py=pos->y;
    ptop=py+height;
    if(py>coll->center.y+coll->half.y+0.05f||ptop<coll->center.y-coll->half.y-0.05f) return false;
    local=static_collision_rotate_y(vec3_sub(*pos,coll->center),-coll->yaw_deg);
    ax=fmaxf(0.05f,coll->half.x+radius);
    bz=fmaxf(0.05f,coll->half.z+radius);
    norm=(local.x*local.x)/(ax*ax)+(local.z*local.z)/(bz*bz);
    if(norm>1.0f) return false;
    if(py<=coll->center.y+coll->half.y+0.25f&&py>=coll->center.y+coll->half.y-0.5f&&vel->y<=0.0f&&
       ((local.x*local.x)/(fmaxf(0.05f,coll->half.x)*fmaxf(0.05f,coll->half.x))+
        (local.z*local.z)/(fmaxf(0.05f,coll->half.z)*fmaxf(0.05f,coll->half.z)))<=1.0f){
        pos->y=coll->center.y+coll->half.y;
        vel->y=0.0f;
        *on_ground=true;
        return true;
    }
    if(ptop>=coll->center.y-coll->half.y-0.05f&&py<coll->center.y-coll->half.y&&vel->y>0.0f&&
       ((local.x*local.x)/(fmaxf(0.05f,coll->half.x)*fmaxf(0.05f,coll->half.x))+
        (local.z*local.z)/(fmaxf(0.05f,coll->half.z)*fmaxf(0.05f,coll->half.z)))<=1.0f){
        pos->y=coll->center.y-coll->half.y-height-0.02f;
        vel->y=0.0f;
        return true;
    }
    if(norm<1e-6f){
        if(ax>=bz) nudge_local=(Vec3){ax,0,0};
        else nudge_local=(Vec3){0,0,bz};
    }else{
        nudge_local=(Vec3){local.x/sqrtf(norm)-local.x,0.0f,local.z/sqrtf(norm)-local.z};
    }
    nudge_world=static_collision_rotate_y(nudge_local,coll->yaw_deg);
    pos->x+=nudge_world.x;
    pos->z+=nudge_world.z;
    return true;
}

void static_collision_world_resolve_capsule(Vec3 *pos,Vec3 *vel,bool *on_ground,float height,float radius){
    int candidates[STATIC_COLL_MAX];
    AABB query_box;
    int count;
    float pad;
    if(!pos||!vel||!on_ground) return;
    pad=radius+1.0f;
    query_box.min=(Vec3){pos->x-pad,pos->y-1.0f,pos->z-pad};
    query_box.max=(Vec3){pos->x+pad,pos->y+height+1.0f,pos->z+pad};
    count=static_collision_world_query(&query_box,candidates,STATIC_COLL_MAX);
    for(int i=0;i<count;i++){
        StaticCollider *coll=&g_static_collision_world.colliders[candidates[i]];
        if(coll->shape==STATIC_COLL_SHAPE_AABB){
            static_collision_resolve_aabb(&coll->bounds,pos,vel,on_ground,height,radius);
        }else if(coll->shape==STATIC_COLL_SHAPE_OBOX){
            static_collision_resolve_obox(coll,pos,vel,on_ground,height,radius);
        }else if(coll->shape==STATIC_COLL_SHAPE_OVAL){
            static_collision_resolve_oval(coll,pos,vel,on_ground,height,radius);
        }else if(coll->shape==STATIC_COLL_SHAPE_MESH_VOLUME){
            static_collision_mesh_volume_resolve(coll,pos,vel,on_ground,height,radius);
        }else if(coll->shape==STATIC_COLL_SHAPE_SPHERE||coll->shape==STATIC_COLL_SHAPE_CIRCLE){
            static_collision_resolve_round(coll,pos,vel,on_ground,height,radius);
        }else if(coll->source==STATIC_COLL_SOURCE_PROP){
            Prop *p=&g_props.list[coll->source_idx];
            float prev_y=pos->y;
            if(trimesh_resolve(&p->trimesh,pos,radius,height) && vel->y<=0.0f){
                vel->y=0.0f;
                *on_ground=true;
            }
            if(pos->y<prev_y&&vel->y>0.0f) vel->y=0.0f;
        }
    }
}

static bool surface_piece_query(int idx,int *out_kind,float *out_width,float *out_height,float *out_thickness,int *out_material_id){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    if(out_kind) *out_kind=(int)g_surfaces.items[idx].kind;
    if(out_width) *out_width=g_surfaces.items[idx].width;
    if(out_height) *out_height=g_surfaces.items[idx].height;
    if(out_thickness) *out_thickness=g_surfaces.items[idx].thickness;
    if(out_material_id) *out_material_id=g_surfaces.items[idx].material_id;
    return true;
}

static bool surface_piece_describe(int idx,Vec3 *out_pos,float *out_yaw,int *out_kind,float *out_width,float *out_height,float *out_thickness,int *out_material_id){
    if(!surface_piece_query(idx,out_kind,out_width,out_height,out_thickness,out_material_id)) return false;
    if(out_pos) *out_pos=g_surfaces.items[idx].pos;
    if(out_yaw) *out_yaw=g_surfaces.items[idx].yaw_deg;
    return true;
}

static bool surface_piece_material_supported(int material_idx,int kind){
    if(material_idx<0||material_idx>=g_interior_material_count) return false;
    return (g_interior_materials[material_idx].surface_flags&surface_piece_surface_flag(kind))!=0;
}

static bool surface_piece_get_pos(int idx,Vec3 *out_pos){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active||!out_pos) return false;
    *out_pos=g_surfaces.items[idx].pos;
    return true;
}

static void interior_materials_load(void){
    FILE *f;
    char line[1024];
    g_interior_material_count=0;
    interior_material_add_builtin("white_brick","White Brick","",2.5f,INTERIOR_SURFACE_FLAG_WALL,0.84f,0.84f,0.82f);
    interior_material_add_builtin("oak_floor","Oak Floor","",3.0f,INTERIOR_SURFACE_FLAG_FLOOR,0.46f,0.31f,0.18f);
    interior_material_add_builtin("painted_ceiling","Painted Ceiling","",2.0f,INTERIOR_SURFACE_FLAG_CEILING,0.83f,0.83f,0.80f);
    interior_material_add_builtin("plaster_grey","Grey Plaster","",2.2f,INTERIOR_SURFACE_FLAG_WALL,0.62f,0.64f,0.68f);
    interior_material_add_builtin("dark_stone","Dark Stone","",2.4f,INTERIOR_SURFACE_FLAG_FLOOR|INTERIOR_SURFACE_FLAG_WALL,0.22f,0.20f,0.18f);
    f=fopen(INTERIOR_MATERIALS_FILE,"r");
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        char *tok[8]={0};
        int ntok=0;
        char *p=line;
        if(line[0]=='#'||line[0]=='\n'||line[0]=='\r') continue;
        while(ntok<8){
            tok[ntok++]=p;
            p=strchr(p,'|');
            if(!p) break;
            *p++=0;
        }
        for(int i=0;i<ntok;i++){
            char *end;
            while(tok[i]&&(*tok[i]==' '||*tok[i]=='\t')) tok[i]++;
            if(!tok[i]) continue;
            end=tok[i]+strlen(tok[i]);
            while(end>tok[i]&&(end[-1]=='\n'||end[-1]=='\r'||end[-1]==' '||end[-1]=='\t')) *--end=0;
        }
        if(ntok<7||!tok[0]||!tok[1]||!tok[3]||!tok[4]||!tok[5]||!tok[6]) continue;
        {
            unsigned int flags=0;
            const char *flag_str=tok[4];
            float r=(float)atof(tok[5]);
            float g=(float)atof(tok[6]);
            float b=(ntok>7&&tok[7])?(float)atof(tok[7]):r;
            if(strchr(flag_str,'W')) flags|=INTERIOR_SURFACE_FLAG_WALL;
            if(strchr(flag_str,'F')) flags|=INTERIOR_SURFACE_FLAG_FLOOR;
            if(strchr(flag_str,'C')) flags|=INTERIOR_SURFACE_FLAG_CEILING;
            if(flags==0) flags=INTERIOR_SURFACE_FLAG_WALL|INTERIOR_SURFACE_FLAG_FLOOR|INTERIOR_SURFACE_FLAG_CEILING;
            interior_material_add_builtin(tok[0],tok[1],tok[2],(float)atof(tok[3]),flags,r,g,b);
        }
    }
    fclose(f);
}

static void interior_materials_init_gpu(void){
    for(int i=0;i<g_interior_material_count;i++){
        InteriorMaterial *mat=&g_interior_materials[i];
        mat->albedo_tex=0;
        if(mat->albedo_path[0]){
            mat->albedo_tex=GLH_texture_file_srgb_streamed(mat->albedo_path);
            if(mat->albedo_tex){
                glBindTexture(GL_TEXTURE_2D,mat->albedo_tex);
                glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);
                glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);
                glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAX_LEVEL,1000);
                glGenerateMipmap(GL_TEXTURE_2D);
                glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);
                glBindTexture(GL_TEXTURE_2D,0);
            }
        }
    }
}

/* Add an interior — returns index */
static int interior_add(const char *name,Vec3 center,float hw,float hh,float hd,
                        float wr,float wg,float wb,
                        float fr,float fg,float fb,
                        float cr,float cg,float cb,
                        Vec3 door,
                        float ar,float ag,float ab){
    if(g_interior_count>=INTERIOR_MAX)return -1;
    InteriorDef *d=&g_interiors[g_interior_count];
    d->name=name; d->center=center;
    d->hw=hw; d->hh=hh; d->hd=hd;
    d->material_ids[INTERIOR_SURFACE_WALL]=-1;
    d->material_ids[INTERIOR_SURFACE_FLOOR]=-1;
    d->material_ids[INTERIOR_SURFACE_CEILING]=-1;
    d->door=door;
    d->amb_r=ar; d->amb_g=ag; d->amb_b=ab;
    d->prop_count=0;
    {
        int wall_idx=interior_material_index_by_id("plaster_grey");
        int floor_idx=interior_material_index_by_id("oak_floor");
        int ceil_idx=interior_material_index_by_id("painted_ceiling");
        float wall_d=1e9f,floor_d=1e9f,ceil_d=1e9f;
        for(int i=0;i<g_interior_material_count;i++){
            float dr,dg,db,dist;
            dr=g_interior_materials[i].fallback_r-wr;
            dg=g_interior_materials[i].fallback_g-wg;
            db=g_interior_materials[i].fallback_b-wb;
            dist=dr*dr+dg*dg+db*db;
            if((g_interior_materials[i].surface_flags&INTERIOR_SURFACE_FLAG_WALL)&&dist<wall_d){ wall_d=dist; wall_idx=i; }
            dr=g_interior_materials[i].fallback_r-fr;
            dg=g_interior_materials[i].fallback_g-fg;
            db=g_interior_materials[i].fallback_b-fb;
            dist=dr*dr+dg*dg+db*db;
            if((g_interior_materials[i].surface_flags&INTERIOR_SURFACE_FLAG_FLOOR)&&dist<floor_d){ floor_d=dist; floor_idx=i; }
            dr=g_interior_materials[i].fallback_r-cr;
            dg=g_interior_materials[i].fallback_g-cg;
            db=g_interior_materials[i].fallback_b-cb;
            dist=dr*dr+dg*dg+db*db;
            if((g_interior_materials[i].surface_flags&INTERIOR_SURFACE_FLAG_CEILING)&&dist<ceil_d){ ceil_d=dist; ceil_idx=i; }
        }
        d->material_ids[INTERIOR_SURFACE_WALL]=wall_idx;
        d->material_ids[INTERIOR_SURFACE_FLOOR]=floor_idx;
        d->material_ids[INTERIOR_SURFACE_CEILING]=ceil_idx;
    }
    return g_interior_count++;
}
static void interior_add_prop(int idx,Vec3 offset,float yaw,float scale,const char *path){
    if(idx<0||idx>=g_interior_count)return;
    InteriorDef *d=&g_interiors[idx];
    if(d->prop_count>=INTERIOR_PROP_MAX)return;
    IntProp *p=&d->props[d->prop_count++];
    p->offset=offset; p->yaw=yaw; p->scale=scale; p->path=path;
}

static void interior_material_assignments_save(void){
    FILE *f=fopen(INTERIOR_ASSIGNMENTS_FILE,"w");
    if(!f) return;
    fprintf(f,"# interior_name|wall_material_id|floor_material_id|ceiling_material_id\n");
    for(int i=0;i<g_interior_count;i++){
        const InteriorDef *d=&g_interiors[i];
        const char *wall=(d->material_ids[INTERIOR_SURFACE_WALL]>=0&&d->material_ids[INTERIOR_SURFACE_WALL]<g_interior_material_count)?g_interior_materials[d->material_ids[INTERIOR_SURFACE_WALL]].id:"";
        const char *floor=(d->material_ids[INTERIOR_SURFACE_FLOOR]>=0&&d->material_ids[INTERIOR_SURFACE_FLOOR]<g_interior_material_count)?g_interior_materials[d->material_ids[INTERIOR_SURFACE_FLOOR]].id:"";
        const char *ceil=(d->material_ids[INTERIOR_SURFACE_CEILING]>=0&&d->material_ids[INTERIOR_SURFACE_CEILING]<g_interior_material_count)?g_interior_materials[d->material_ids[INTERIOR_SURFACE_CEILING]].id:"";
        fprintf(f,"%s|%s|%s|%s\n",d->name?d->name:"Interior",wall,floor,ceil);
    }
    fclose(f);
}

static void interior_material_assignments_load(void){
    FILE *f=fopen(INTERIOR_ASSIGNMENTS_FILE,"r");
    char line[1024];
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        char *tok[4]={0};
        int ntok=0;
        char *p=line;
        if(line[0]=='#'||line[0]=='\n'||line[0]=='\r') continue;
        while(ntok<4){
            tok[ntok++]=p;
            p=strchr(p,'|');
            if(!p) break;
            *p++=0;
        }
        for(int i=0;i<ntok;i++){
            char *end;
            while(tok[i]&&(*tok[i]==' '||*tok[i]=='\t')) tok[i]++;
            if(!tok[i]) continue;
            end=tok[i]+strlen(tok[i]);
            while(end>tok[i]&&(end[-1]=='\n'||end[-1]=='\r'||end[-1]==' '||end[-1]=='\t')) *--end=0;
        }
        if(ntok<4||!tok[0]) continue;
        for(int i=0;i<g_interior_count;i++){
            if(g_interiors[i].name&&strcmp(g_interiors[i].name,tok[0])==0){
                int wall=interior_material_index_by_id(tok[1]);
                int floor=interior_material_index_by_id(tok[2]);
                int ceil=interior_material_index_by_id(tok[3]);
                if(wall>=0) g_interiors[i].material_ids[INTERIOR_SURFACE_WALL]=wall;
                if(floor>=0) g_interiors[i].material_ids[INTERIOR_SURFACE_FLOOR]=floor;
                if(ceil>=0) g_interiors[i].material_ids[INTERIOR_SURFACE_CEILING]=ceil;
                break;
            }
        }
    }
    fclose(f);
}

/* Build vertex buffer: 6 faces of box, each a quad (2 triangles).
   Vertex layout: x,y,z,nx,ny,nz,r,g,b (9 floats) */
static void room_renderer_init(RoomRenderer *rr){
    const char *vs=
        "#version 330 core\n"
        "layout(location=0)in vec3 aPos;\n"
        "layout(location=1)in vec3 aNorm;\n"
        "layout(location=2)in vec3 aColor;\n"
        "uniform mat4 uProj,uView;\n"
        "out vec3 vColor;out vec3 vNorm;out vec3 vPos;\n"
        "void main(){\n"
        "  gl_Position=uProj*uView*vec4(aPos,1.0);\n"
        "  vPos=aPos;vNorm=aNorm;vColor=aColor;\n"
        "}\n";
    const char *fs=
        "#version 330 core\n"
        "in vec3 vColor;in vec3 vNorm;in vec3 vPos;\n"
        LIGHTING_UNIFORMS
        "uniform vec3 uRoomAmbient;uniform vec3 uRoomCenter;\n"
        "uniform sampler2D uTex;uniform bool uHasTex;uniform float uUvScale;\n"
        "uniform int uSurfaceKind;\n"
        "out vec4 F;\n"
        "void main(){\n"
        "  vec3 local=vPos-uRoomCenter;\n"
        "  vec2 uv=local.xz;\n"
        "  if(uSurfaceKind==0){\n"
        "    uv=(abs(vNorm.x)>0.5)?vec2(local.z,local.y):vec2(local.x,local.y);\n"
        "  }else if(uSurfaceKind==2){\n"
        "    uv=vec2(local.x,-local.z);\n"
        "  }\n"
        "  uv*=uUvScale;\n"
        "  vec3 n=normalize(vNorm);\n"
        "  float d=max(dot(n,normalize(-uSunDir)),0.0);\n"
        "  vec3 base=uHasTex?texture(uTex,uv).rgb:vColor;\n"
        "  vec3 col=base*(uAmbient+uRoomAmbient+uSunColor*d*0.22);\n"
        "  for(int i=0;i<uNumLights;i++){\n"
        "    vec3 lv=uLightPos[i]-vPos;float dist=length(lv);\n"
        "    vec3 ldir=normalize(lv);\n"
        "    float att=1.0-clamp(dist/uLightRadius[i],0.0,1.0);\n"
        "    float cone=1.0;\n"
        "    if(uLightParams[i].x>0.5) cone=smoothstep(uLightParams[i].z,uLightParams[i].y,dot(normalize(uLightDir[i]),-ldir));\n"
        "    att*=att*cone;\n"
        "    col+=base*uLightColor[i]*max(dot(n,ldir),0.0)*att;\n"
        "  }\n"
        "  col=min(col*1.05,vec3(1.0));\n"
        "  F=vec4(col,1.0);\n"
        "}\n";
    rr->prog=GLH_program(vs,fs);
    glGenVertexArrays(1,&rr->vao);
    glGenBuffers(1,&rr->vbo);
    glBindVertexArray(rr->vao);
    glBindBuffer(GL_ARRAY_BUFFER,rr->vbo);
    /* 6 faces * 6 verts (2 tris) * 9 floats = 324 floats max */
    glBufferData(GL_ARRAY_BUFFER,324*sizeof(float),NULL,GL_DYNAMIC_DRAW);
    glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,36,(void*)0);
    glEnableVertexAttribArray(1);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,36,(void*)12);
    glEnableVertexAttribArray(2);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,36,(void*)24);
    glBindVertexArray(0);
    rr->vcount=0;
}

static void room_draw_material_pass(RoomRenderer *rr,const InteriorMaterial *mat,
                                    const InteriorDef *d,LightingSystem *ls,Mat4 proj,Mat4 view,
                                    int surface_kind,int first,int count){
    Vec3 room_ambient;
    if(!rr||!d||count<=0) return;
    if(ls) lighting_push(ls,rr->prog);
    else glUseProgram(rr->prog);
    GLH_mat4(rr->prog,"uProj",proj.m);
    GLH_mat4(rr->prog,"uView",view.m);
    room_ambient=(Vec3){d->amb_r*0.18f,d->amb_g*0.18f,d->amb_b*0.18f};
    GLH_vec3(rr->prog,"uRoomAmbient",room_ambient.x,room_ambient.y,room_ambient.z);
    GLH_vec3(rr->prog,"uRoomCenter",d->center.x,d->center.y,d->center.z);
    GLH_float(rr->prog,"uUvScale",mat?mat->uv_scale:1.0f);
    GLH_int(rr->prog,"uSurfaceKind",surface_kind);
    GLH_bool(rr->prog,"uHasTex",mat&&mat->albedo_tex!=0);
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D,(mat&&mat->albedo_tex)?mat->albedo_tex:0);
    GLH_int(rr->prog,"uTex",0);
    glBindVertexArray(rr->vao);
    glDrawArrays(GL_TRIANGLES,first,count);
}

/* Upload room geometry for a given interior def */
static void room_upload(RoomRenderer *rr,const InteriorDef *d){
    float cx=d->center.x,cy=d->center.y,cz=d->center.z;
    float hw=d->hw,hh=d->hh,hd=d->hd;
    /* 6 faces: floor, ceil, N, S, E, W */
    /* Each face: 6 verts (2 tris), format: x,y,z, nx,ny,nz, r,g,b */
    float verts[6*6*9];
    int vi=0;
    #define V(px,py,pz,nx,ny,nz,r,g,b) \
        verts[vi++]=(px);verts[vi++]=(py);verts[vi++]=(pz); \
        verts[vi++]=(nx);verts[vi++]=(ny);verts[vi++]=(nz); \
        verts[vi++]=(r); verts[vi++]=(g); verts[vi++]=(b)
    #define QUAD(ax,ay,az, bx,by,bz, cx2,cy2,cz2, dx,dy,dz, nx,ny,nz, r,g,b) \
        V(ax,ay,az,nx,ny,nz,r,g,b);V(bx,by,bz,nx,ny,nz,r,g,b);V(cx2,cy2,cz2,nx,ny,nz,r,g,b); \
        V(ax,ay,az,nx,ny,nz,r,g,b);V(cx2,cy2,cz2,nx,ny,nz,r,g,b);V(dx,dy,dz,nx,ny,nz,r,g,b)
    float x0=cx-hw,x1=cx+hw,y0=cy-hh,y1=cy+hh,z0=cz-hd,z1=cz+hd;
    const InteriorMaterial *wall=(d->material_ids[INTERIOR_SURFACE_WALL]>=0&&d->material_ids[INTERIOR_SURFACE_WALL]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_WALL]]:NULL;
    const InteriorMaterial *floor=(d->material_ids[INTERIOR_SURFACE_FLOOR]>=0&&d->material_ids[INTERIOR_SURFACE_FLOOR]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_FLOOR]]:NULL;
    const InteriorMaterial *ceil=(d->material_ids[INTERIOR_SURFACE_CEILING]>=0&&d->material_ids[INTERIOR_SURFACE_CEILING]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_CEILING]]:NULL;
    float wr=wall?wall->fallback_r:0.62f,wg=wall?wall->fallback_g:0.64f,wb=wall?wall->fallback_b:0.68f;
    float fr=floor?floor->fallback_r:0.22f,fg=floor?floor->fallback_g:0.18f,fb=floor?floor->fallback_b:0.14f;
    float cr=ceil?ceil->fallback_r:0.78f,cg=ceil?ceil->fallback_g:0.78f,cb=ceil?ceil->fallback_b:0.76f;
    /* Floor */
    QUAD(x0,y0,z0, x1,y0,z0, x1,y0,z1, x0,y0,z1, 0,1,0, fr,fg,fb);
    /* Ceiling */
    QUAD(x0,y1,z1, x1,y1,z1, x1,y1,z0, x0,y1,z0, 0,-1,0, cr,cg,cb);
    /* North wall (z=z0, facing +z) */
    QUAD(x0,y0,z0, x0,y1,z0, x1,y1,z0, x1,y0,z0, 0,0,1, wr,wg,wb);
    /* South wall (z=z1, facing -z) */
    QUAD(x1,y0,z1, x1,y1,z1, x0,y1,z1, x0,y0,z1, 0,0,-1, wr,wg,wb);
    /* East wall (x=x1, facing -x) */
    QUAD(x1,y0,z0, x1,y1,z0, x1,y1,z1, x1,y0,z1, -1,0,0, wr*0.85f,wg*0.85f,wb*0.85f);
    /* West wall (x=x0, facing +x) */
    QUAD(x0,y0,z1, x0,y1,z1, x0,y1,z0, x0,y0,z0, 1,0,0, wr*0.85f,wg*0.85f,wb*0.85f);
    #undef V
    #undef QUAD
    glBindVertexArray(rr->vao);
    glBindBuffer(GL_ARRAY_BUFFER,rr->vbo);
    glBufferSubData(GL_ARRAY_BUFFER,0,vi*sizeof(float),verts);
    glBindVertexArray(0);
    rr->vcount=vi/9; /* 9 floats per vertex */
}

static void room_draw(RoomRenderer *rr,const InteriorDef *d,LightingSystem *ls,Mat4 proj,Mat4 view){
    const InteriorMaterial *wall;
    const InteriorMaterial *floor;
    const InteriorMaterial *ceil;
    if(!rr->prog)return;
    room_upload(rr,d);
    wall=(d->material_ids[INTERIOR_SURFACE_WALL]>=0&&d->material_ids[INTERIOR_SURFACE_WALL]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_WALL]]:NULL;
    floor=(d->material_ids[INTERIOR_SURFACE_FLOOR]>=0&&d->material_ids[INTERIOR_SURFACE_FLOOR]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_FLOOR]]:NULL;
    ceil=(d->material_ids[INTERIOR_SURFACE_CEILING]>=0&&d->material_ids[INTERIOR_SURFACE_CEILING]<g_interior_material_count)?&g_interior_materials[d->material_ids[INTERIOR_SURFACE_CEILING]]:NULL;
    glDisable(GL_CULL_FACE);
    room_draw_material_pass(rr,floor,d,ls,proj,view,INTERIOR_SURFACE_FLOOR,0,6);
    if(!g_room_hide_ceiling)
        room_draw_material_pass(rr,ceil,d,ls,proj,view,INTERIOR_SURFACE_CEILING,6,6);
    room_draw_material_pass(rr,wall,d,ls,proj,view,INTERIOR_SURFACE_WALL,12,24);
    glBindVertexArray(0);
    glEnable(GL_CULL_FACE);
}

static const char *scene_surface_file(SceneID scene){
    switch(scene){
        case SCENE_APARTMENT: return APARTMENT_SURFACE_PIECES_FILE;
        case SCENE_SHIRE:
        default: return SURFACE_PIECES_FILE;
    }
}

static SceneID scene_id_for_surfaces(const SurfacePieceList *sl){
    if(sl==&g_surfaces) return g_surfaces_active_scene;
    if(sl==&g_scene_surface_store[SCENE_APARTMENT]) return SCENE_APARTMENT;
    if(sl==&g_scene_surface_store[SCENE_SHIRE]) return SCENE_SHIRE;
    return g_surfaces_active_scene;
}

static void surface_pieces_activate(SceneID scene){
    if(scene<0||scene>=SCENE_COUNT||scene==g_surfaces_active_scene) return;
    if(!g_scene_surface_store_loaded[scene]){
        surface_pieces_load(&g_scene_surface_store[scene]);
        g_scene_surface_store_loaded[scene]=true;
    }
    g_scene_surface_store[g_surfaces_active_scene]=g_surfaces;
    memset(&g_surfaces,0,sizeof(g_surfaces));
    g_surfaces=g_scene_surface_store[scene];
    memset(&g_scene_surface_store[scene],0,sizeof(g_scene_surface_store[scene]));
    g_surfaces_active_scene=scene;
    static_collision_world_mark_dirty();
}

static const char *scene_collision_volume_file(SceneID scene){
    switch(scene){
        case SCENE_APARTMENT: return APARTMENT_COLLISION_VOLUMES_FILE;
        case SCENE_SHIRE:
        default: return COLLISION_VOLUMES_FILE;
    }
}

static SceneID scene_id_for_collision_volumes(const CollisionVolumeList *list){
    if(list==&g_collision_volumes) return g_collision_volumes_active_scene;
    if(list==&g_scene_collision_volume_store[SCENE_APARTMENT]) return SCENE_APARTMENT;
    if(list==&g_scene_collision_volume_store[SCENE_SHIRE]) return SCENE_SHIRE;
    return g_collision_volumes_active_scene;
}

static void collision_volumes_activate(SceneID scene){
    if(scene<0||scene>=SCENE_COUNT||scene==g_collision_volumes_active_scene) return;
    if(!g_scene_collision_volume_store_loaded[scene]){
        collision_volumes_load(&g_scene_collision_volume_store[scene]);
        g_scene_collision_volume_store_loaded[scene]=true;
    }
    g_scene_collision_volume_store[g_collision_volumes_active_scene]=g_collision_volumes;
    memset(&g_collision_volumes,0,sizeof(g_collision_volumes));
    g_collision_volumes=g_scene_collision_volume_store[scene];
    memset(&g_scene_collision_volume_store[scene],0,sizeof(g_scene_collision_volume_store[scene]));
    g_collision_volumes_active_scene=scene;
    static_collision_world_mark_dirty();
}

static int surface_piece_default_material(int kind){
    int want_flag=(int)surface_piece_surface_flag(kind);
    for(int i=0;i<g_interior_material_count;i++){
        if((int)g_interior_materials[i].surface_flags&want_flag) return i;
    }
    return 0;
}

static int surface_pieces_next_slot(SurfacePieceList *sl){
    if(!sl) return -1;
    for(int i=0;i<sl->count;i++) if(!sl->items[i].active) return i;
    if(sl->count>=SURFACE_PIECE_MAX) return -1;
    return sl->count;
}

static int surface_piece_register(SurfacePieceList *sl,int kind,Vec3 pos,float yaw_deg,
                                  float width,float height,float thickness,int material_id){
    int idx=surface_pieces_next_slot(sl);
    SurfacePiece *sp;
    if(idx<0||!sl) return -1;
    sp=&sl->items[idx];
    memset(sp,0,sizeof(*sp));
    sp->active=true;
    sp->kind=(kind==SURFACE_PIECE_FLOOR)?SURFACE_PIECE_FLOOR:SURFACE_PIECE_WALL;
    sp->pos=pos;
    sp->yaw_deg=yaw_deg;
    sp->width=(width>0.05f)?width:1.0f;
    sp->height=(height>0.05f)?height:1.0f;
    sp->thickness=(thickness>0.02f)?thickness:0.10f;
    sp->coll_type=PROP_COLL_AABB;
    if(material_id<0||material_id>=g_interior_material_count) material_id=surface_piece_default_material(kind);
    sp->material_id=material_id;
    if(idx==sl->count) sl->count++;
    return idx;
}

static bool surface_piece_set_material_id(int idx,int material_id){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    if(!surface_piece_material_supported(material_id,(int)g_surfaces.items[idx].kind)) return false;
    g_surfaces.items[idx].material_id=material_id;
    surface_piece_save_active_scene();
    return true;
}

static bool surface_piece_set_kind(int idx,int kind){
    SurfacePiece *sp;
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    sp=&g_surfaces.items[idx];
    sp->kind=(kind==SURFACE_PIECE_FLOOR)?SURFACE_PIECE_FLOOR:SURFACE_PIECE_WALL;
    if(!surface_piece_material_supported(sp->material_id,(int)sp->kind))
        sp->material_id=surface_piece_default_material((int)sp->kind);
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_set_width_value(int idx,float value){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].width=clampf(value,0.25f,64.0f);
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_set_height_value(int idx,float value){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].height=clampf(value,0.25f,64.0f);
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_set_thickness_value(int idx,float value){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].thickness=clampf(value,0.05f,8.0f);
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_set_collision_type(int idx,int coll_type){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].coll_type=(coll_type==PROP_COLL_NONE)?PROP_COLL_NONE:PROP_COLL_AABB;
    surface_pieces_save(&g_surfaces);
    return true;
}

static void surface_piece_save_active_scene(void){
    surface_pieces_save(&g_surfaces);
}

static void surface_pieces_save(SurfacePieceList *sl){
    SceneID scene=scene_id_for_surfaces(sl);
    const char *file=scene_surface_file(scene);
    FILE *f=fopen(file,"w");
    if(!sl||!f) return;
    fprintf(f,"# kind x y z yaw width height thickness material_id coll_type\n");
    for(int i=0;i<sl->count;i++){
        SurfacePiece *sp=&sl->items[i];
        if(!sp->active) continue;
        fprintf(f,"%d %.3f %.3f %.3f %.3f %.3f %.3f %.3f %d %d\n",
                (int)sp->kind,
                (double)sp->pos.x,(double)sp->pos.y,(double)sp->pos.z,
                (double)sp->yaw_deg,(double)sp->width,(double)sp->height,(double)sp->thickness,
                sp->material_id,(int)sp->coll_type);
    }
    fclose(f);
    if(sl==&g_surfaces) static_collision_world_mark_dirty();
}

static bool surface_piece_move_y(int idx,float delta_y,bool snap_to_ground){
    SurfacePiece *sp;
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    sp=&g_surfaces.items[idx];
    if(snap_to_ground){
        float ground_y=scene_ground_y(sp->pos.x,sp->pos.z);
        sp->pos.y=ground_y+((sp->kind==SURFACE_PIECE_WALL)?(sp->height*0.5f):(sp->thickness*0.5f));
    }else{
        sp->pos.y+=delta_y;
    }
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_move_planar(int idx,Vec3 delta){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].pos.x+=delta.x;
    g_surfaces.items[idx].pos.z+=delta.z;
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_adjust_yaw(int idx,float delta_deg){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].yaw_deg+=delta_deg;
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_scale_uniform(int idx,float mul){
    SurfacePiece *sp;
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    sp=&g_surfaces.items[idx];
    sp->width=clampf(sp->width*mul,0.25f,64.0f);
    sp->height=clampf(sp->height*mul,0.25f,64.0f);
    sp->thickness=clampf(sp->thickness*mul,0.05f,8.0f);
    surface_pieces_save(&g_surfaces);
    return true;
}

static bool surface_piece_snap_grid(int idx,float grid){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active||grid<=0.0f) return false;
    g_surfaces.items[idx].pos.x=roundf(g_surfaces.items[idx].pos.x/grid)*grid;
    g_surfaces.items[idx].pos.z=roundf(g_surfaces.items[idx].pos.z/grid)*grid;
    surface_pieces_save(&g_surfaces);
    return true;
}

static int surface_piece_duplicate_idx(int idx,Vec3 offset,bool snap_to_ground,bool snap_to_grid){
    SurfacePiece *src;
    float new_x,new_y,new_z;
    int new_idx;
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return -1;
    src=&g_surfaces.items[idx];
    new_x=src->pos.x+offset.x;
    new_z=src->pos.z+offset.z;
    new_y=src->pos.y;
    if(snap_to_grid){
        new_x=roundf(new_x/0.5f)*0.5f;
        new_z=roundf(new_z/0.5f)*0.5f;
    }
    if(snap_to_ground){
        float ground_y=scene_ground_y(new_x,new_z);
        new_y=ground_y+((src->kind==SURFACE_PIECE_WALL)?(src->height*0.5f):(src->thickness*0.5f));
    }
    new_idx=surface_piece_register(&g_surfaces,(int)src->kind,(Vec3){new_x,new_y,new_z},src->yaw_deg,
                                   src->width,src->height,src->thickness,src->material_id);
    if(new_idx>=0) surface_pieces_save(&g_surfaces);
    return new_idx;
}

static bool surface_piece_delete_idx(int idx){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].active=false;
    surface_pieces_save(&g_surfaces);
    return true;
}

static void surface_trim_trailing_inactive(void){
    while(g_surfaces.count>0&&!g_surfaces.items[g_surfaces.count-1].active)
        g_surfaces.count--;
}

static bool surface_piece_snapshot(int idx, void *out_snap){
    SurfaceSnap *snap=(SurfaceSnap*)out_snap;
    SurfacePiece *sp;
    if(!snap||idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    sp=&g_surfaces.items[idx];
    memset(snap,0,sizeof(*snap));
    snap->active=sp->active;
    snap->kind=(int)sp->kind;
    snap->pos=sp->pos;
    snap->yaw_deg=sp->yaw_deg;
    snap->width=sp->width;
    snap->height=sp->height;
    snap->thickness=sp->thickness;
    snap->coll_type=sp->coll_type;
    snap->material_id=sp->material_id;
    return true;
}

static bool surface_piece_restore_from_snap(int idx, const void *snap_ptr, bool save_now){
    const SurfaceSnap *snap=(const SurfaceSnap*)snap_ptr;
    SurfacePiece *sp;
    if(!snap||idx<0||idx>=SURFACE_PIECE_MAX) return false;
    sp=&g_surfaces.items[idx];
    memset(sp,0,sizeof(*sp));
    sp->active=snap->active;
    sp->kind=(snap->kind==SURFACE_PIECE_FLOOR)?SURFACE_PIECE_FLOOR:SURFACE_PIECE_WALL;
    sp->pos=snap->pos;
    sp->yaw_deg=snap->yaw_deg;
    sp->width=clampf(snap->width,0.25f,64.0f);
    sp->height=clampf(snap->height,0.25f,64.0f);
    sp->thickness=clampf(snap->thickness,0.05f,8.0f);
    sp->coll_type=(snap->coll_type==PROP_COLL_NONE)?PROP_COLL_NONE:PROP_COLL_AABB;
    sp->material_id=snap->material_id;
    if(!surface_piece_material_supported(sp->material_id,(int)sp->kind))
        sp->material_id=surface_piece_default_material((int)sp->kind);
    if(idx>=g_surfaces.count) g_surfaces.count=idx+1;
    if(save_now) surface_piece_save_active_scene();
    return true;
}

static bool surface_piece_deactivate_at(int idx, bool save_now){
    if(idx<0||idx>=g_surfaces.count||!g_surfaces.items[idx].active) return false;
    g_surfaces.items[idx].active=false;
    surface_trim_trailing_inactive();
    if(save_now) surface_piece_save_active_scene();
    return true;
}

static bool editor_command_surface_patch(int idx,const SurfaceSnap *updated,
                                         EditorCommandKind kind,EditorCommandResult *out){
    SurfaceSnap before;
    editor_command_result_reset(out,EDITOR_COMMAND_DOMAIN_SURFACE,kind);
    if(!updated) return false;
    if(!surface_piece_snapshot(idx,&before)) return false;
    if(before.active==updated->active&&before.kind==updated->kind&&
       fabsf(before.pos.x-updated->pos.x)<=0.0001f&&
       fabsf(before.pos.y-updated->pos.y)<=0.0001f&&
       fabsf(before.pos.z-updated->pos.z)<=0.0001f&&
       fabsf(before.yaw_deg-updated->yaw_deg)<=0.0001f&&
       fabsf(before.width-updated->width)<=0.0001f&&
       fabsf(before.height-updated->height)<=0.0001f&&
       fabsf(before.thickness-updated->thickness)<=0.0001f&&
       before.coll_type==updated->coll_type&&
       before.material_id==updated->material_id)
        return false;
    if(!surface_piece_restore_from_snap(idx,updated,false)) return false;
    undo_push_surface_edit(idx,before,*(SurfaceSnap*)updated);
    surface_piece_save_active_scene();
    if(out){
        out->changed=true;
        out->primary_index=idx;
    }
    editor_command_runtime_note_change(editor_commands_runtime());
    return true;
}

static bool editor_command_surface_create(int kind,Vec3 pos,float yaw_deg,
                                          float width,float height,float thickness,
                                          int material_id,int coll_type,
                                          int *out_idx,EditorCommandResult *out){
    int idx;
    UndoSnap snap;
    editor_command_result_reset(out,EDITOR_COMMAND_DOMAIN_SURFACE,
                                EDITOR_COMMAND_KIND_SURFACE_CREATE);
    if(out_idx) *out_idx=-1;
    idx=surface_piece_register(&g_surfaces,kind,pos,yaw_deg,width,height,thickness,material_id);
    if(idx<0) return false;
    g_surfaces.items[idx].coll_type=(coll_type==PROP_COLL_NONE)?PROP_COLL_NONE:PROP_COLL_AABB;
    memset(&snap,0,sizeof(snap));
    surface_piece_snapshot(idx,&snap.surface);
    undo_push_place(UNDO_SURFACE_PLACE,idx,g_surfaces.count-1,snap);
    surface_piece_save_active_scene();
    if(out_idx) *out_idx=idx;
    if(out){
        out->changed=true;
        out->primary_index=idx;
    }
    editor_command_runtime_note_change(editor_commands_runtime());
    return true;
}

static bool editor_command_surface_delete(int idx,EditorCommandResult *out){
    UndoSnap snap;
    editor_command_result_reset(out,EDITOR_COMMAND_DOMAIN_SURFACE,
                                EDITOR_COMMAND_KIND_SURFACE_DELETE);
    if(!surface_piece_snapshot(idx,&snap.surface)) return false;
    undo_push_delete(UNDO_SURFACE_DELETE,idx,g_surfaces.count,snap);
    if(!surface_piece_deactivate_at(idx,true)) return false;
    if(out){
        out->changed=true;
        out->primary_index=idx;
    }
    editor_command_runtime_note_change(editor_commands_runtime());
    return true;
}

