static bool editor_command_surface_commit_xform(int idx,
                                                Vec3 before_pos,float before_yaw_deg,
                                                float before_width,float before_height,float before_thickness,
                                                EditorCommandResult *out){
    SurfaceSnap before, after;
    editor_command_result_reset(out,EDITOR_COMMAND_DOMAIN_SURFACE,
                                EDITOR_COMMAND_KIND_SURFACE_COMMIT_XFORM);
    if(!surface_piece_snapshot(idx,&after)) return false;
    before=after;
    before.pos=before_pos;
    before.yaw_deg=before_yaw_deg;
    before.width=clampf(before_width,0.25f,64.0f);
    before.height=clampf(before_height,0.25f,64.0f);
    before.thickness=clampf(before_thickness,0.05f,8.0f);
    if(before.active==after.active&&before.kind==after.kind&&
       fabsf(before.pos.x-after.pos.x)<=0.0001f&&
       fabsf(before.pos.y-after.pos.y)<=0.0001f&&
       fabsf(before.pos.z-after.pos.z)<=0.0001f&&
       fabsf(before.yaw_deg-after.yaw_deg)<=0.0001f&&
       fabsf(before.width-after.width)<=0.0001f&&
       fabsf(before.height-after.height)<=0.0001f&&
       fabsf(before.thickness-after.thickness)<=0.0001f)
        return false;
    undo_push_surface_edit(idx,before,after);
    surface_piece_save_active_scene();
    if(out){
        out->changed=true;
        out->primary_index=idx;
    }
    editor_command_runtime_note_change(editor_commands_runtime());
    return true;
}

static void surface_pieces_load(SurfacePieceList *sl){
    SceneID scene=scene_id_for_surfaces(sl);
    const char *file=scene_surface_file(scene);
    FILE *f=fopen(file,"r");
    char line[512];
    if(!sl){ return; }
    memset(sl,0,sizeof(*sl));
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        int kind,material_id,coll_type=PROP_COLL_AABB;
        float x,y,z,yaw_deg,width,height,thickness;
        if(line[0]=='#') continue;
        if(sscanf(line,"%d %f %f %f %f %f %f %f %d %d",
                  &kind,&x,&y,&z,&yaw_deg,&width,&height,&thickness,&material_id,&coll_type)>=9){
            int idx=surface_piece_register(sl,kind,(Vec3){x,y,z},yaw_deg,width,height,thickness,material_id);
            if(idx>=0) sl->items[idx].coll_type=(coll_type==PROP_COLL_NONE)?PROP_COLL_NONE:PROP_COLL_AABB;
        }
    }
    fclose(f);
}

static void collision_volume_trim_trailing_inactive(void){
    while(g_collision_volumes.count>0&&!g_collision_volumes.items[g_collision_volumes.count-1].active)
        g_collision_volumes.count--;
}

static void collision_volumes_save(CollisionVolumeList *list){
    SceneID scene=scene_id_for_collision_volumes(list);
    const char *file=scene_collision_volume_file(scene);
    FILE *f=fopen(file,"w");
    if(!list||!f) return;
    fprintf(f,"# uid x y z yaw pitch width height depth shape enabled nav_blocker motion_enabled move_x move_y move_z motion_period motion_phase\n");
    for(int i=0;i<list->count;i++){
        CollisionVolume *cv=&list->items[i];
        if(!cv->active) continue;
        fprintf(f,"%d %.3f %.3f %.3f %.3f %.3f %.3f %.3f %.3f %d %d %d %d %.3f %.3f %.3f %.3f %.3f\n",
                cv->uid,(double)cv->pos.x,(double)cv->pos.y,(double)cv->pos.z,
                (double)cv->yaw_deg,(double)cv->pitch_deg,(double)cv->width,(double)cv->height,(double)cv->depth,
                collision_volume_shape_sanitize(cv->shape),
                cv->enabled?1:0,cv->nav_blocker?1:0,
                cv->motion_enabled?1:0,
                (double)cv->motion_offset.x,(double)cv->motion_offset.y,(double)cv->motion_offset.z,
                (double)cv->motion_period,(double)cv->motion_phase);
    }
    fclose(f);
    if(list==&g_collision_volumes) static_collision_world_mark_dirty();
}

static void collision_volume_save_active_scene(void){
    collision_volumes_save(&g_collision_volumes);
}

static void collision_volumes_load(CollisionVolumeList *list){
    SceneID scene=scene_id_for_collision_volumes(list);
    const char *file=scene_collision_volume_file(scene);
    FILE *f=fopen(file,"r");
    char line[512];
    if(!list) return;
    memset(list,0,sizeof(*list));
    if(!f) return;
    while(fgets(line,sizeof(line),f)){
        int token_count=0;
        int uid=0;
        float x,y,z,yaw_deg,pitch_deg=0.0f,width,height,depth;
        int shape=COLLISION_VOLUME_SHAPE_BOX;
        int enabled=1;
        int nav_blocker=1;
        int motion_enabled=0;
        float move_x=0.0f,move_y=0.0f,move_z=0.0f,motion_period=2.0f,motion_phase=0.0f;
        if(line[0]=='#') continue;
        for(char *p=line;*p;){
            char *endptr=NULL;
            while(*p&&isspace((unsigned char)*p)) p++;
            if(!*p||*p=='#') break;
            strtod(p,&endptr);
            if(endptr==p) break;
            token_count++;
            p=endptr;
        }
        if(token_count>=18&&sscanf(line,"%d %f %f %f %f %f %f %f %f %d %d %d %d %f %f %f %f %f",
                  &uid,&x,&y,&z,&yaw_deg,&pitch_deg,&width,&height,&depth,&shape,&enabled,&nav_blocker,
                  &motion_enabled,&move_x,&move_y,&move_z,&motion_period,&motion_phase)>=18){
            int idx=collision_volume_register(list,(Vec3){x,y,z},shape,yaw_deg,pitch_deg,width,height,depth,
                                              enabled!=0,nav_blocker!=0);
            if(idx>=0){
                if(uid>0){ list->items[idx].uid=uid; world_observe_collision_volume_uid(uid); }
                list->items[idx].motion_enabled=motion_enabled!=0;
                list->items[idx].motion_offset=(Vec3){move_x,move_y,move_z};
                list->items[idx].motion_period=fmaxf(0.1f,motion_period);
                list->items[idx].motion_phase=motion_phase;
            }
        }else if(token_count>=16&&sscanf(line,"%d %f %f %f %f %f %f %f %d %d %d %f %f %f %f %f",
                  &uid,&x,&y,&z,&yaw_deg,&width,&height,&depth,&enabled,&nav_blocker,
                  &motion_enabled,&move_x,&move_y,&move_z,&motion_period,&motion_phase)>=16){
            int idx=collision_volume_register(list,(Vec3){x,y,z},COLLISION_VOLUME_SHAPE_BOX,yaw_deg,0.0f,width,height,depth,
                                              enabled!=0,nav_blocker!=0);
            if(idx>=0){
                if(uid>0){ list->items[idx].uid=uid; world_observe_collision_volume_uid(uid); }
                list->items[idx].motion_enabled=motion_enabled!=0;
                list->items[idx].motion_offset=(Vec3){move_x,move_y,move_z};
                list->items[idx].motion_period=fmaxf(0.1f,motion_period);
                list->items[idx].motion_phase=motion_phase;
            }
        }else if(token_count>=15&&sscanf(line,"%f %f %f %f %f %f %f %d %d %d %f %f %f %f %f",
                  &x,&y,&z,&yaw_deg,&width,&height,&depth,&enabled,&nav_blocker,
                  &motion_enabled,&move_x,&move_y,&move_z,&motion_period,&motion_phase)>=15){
            int idx=collision_volume_register(list,(Vec3){x,y,z},COLLISION_VOLUME_SHAPE_BOX,yaw_deg,0.0f,width,height,depth,
                                              enabled!=0,nav_blocker!=0);
            if(idx>=0){
                list->items[idx].motion_enabled=motion_enabled!=0;
                list->items[idx].motion_offset=(Vec3){move_x,move_y,move_z};
                list->items[idx].motion_period=fmaxf(0.1f,motion_period);
                list->items[idx].motion_phase=motion_phase;
            }
        }
    }
    fclose(f);
}

