    cv=&g_collision_volumes.items[idx];
    cv->width=clampf(cv->width*mul,0.25f,64.0f);
    cv->height=clampf(cv->height*mul,0.25f,64.0f);
    cv->depth=clampf(cv->depth*mul,0.25f,64.0f);
