static void frame_set_title_cb(void *window,const char *title){
    (void)title;
    if(strcmp(SDL_GetWindowTitle((SDL_Window*)window),g_project.name))
        SDL_SetWindowTitle((SDL_Window*)window,g_project.name);
}
static void frame_swap_cb(void *window){
    if(g_launch.active) engine_perf_frame();
    engine_launch_frame((SDL_Window*)window);
    Uint64 present_begin=SDL_GetPerformanceCounter();
    SDL_GL_SwapWindow((SDL_Window*)window);
    g_engine_perf.present_ms=perf_counter_ms(present_begin,SDL_GetPerformanceCounter());
}
static void frame_depth_cb(bool enabled){
    if(enabled) glEnable(GL_DEPTH_TEST);
    else glDisable(GL_DEPTH_TEST);
}

static const char *intro_music_resolve_path(void){
    static const char *preferred[]={
        "intro.mp3",
        "intro.ogg",
        "intro.wav",
        "background_music/intro.mp3",
        "background_music/intro.ogg",
        "background_music/intro.wav",
        NULL
    };
    static const char *candidates[]={
        "intro_mus.mp4",
        "intro_mus.ogg",
        "intro_mus.mp3",
        "intro_mus.wav",
        "background_music/intro_mus.mp4",
        "background_music/intro_mus.ogg",
        "background_music/intro_mus.mp3",
        "background_music/intro_mus.wav",
        NULL
    };
    for(int i=0;preferred[i];i++){
        if(access(preferred[i],R_OK)==0) return preferred[i];
    }
    for(int i=0;candidates[i];i++){
        if(access(candidates[i],R_OK)==0) return candidates[i];
    }
    return NULL;
}

static const char *apartment_music_resolve_path(void){
    static const char *candidates[]={
        "gloomy.mp3",
        "gloomy.ogg",
        "gloomy.wav",
        "background_music/gloomy.mp3",
        "background_music/gloomy.ogg",
        "background_music/gloomy.wav",
        NULL
    };
    for(int i=0;candidates[i];i++){
        if(access(candidates[i],R_OK)==0) return candidates[i];
    }
    return NULL;
}

static void scene_music_update(SceneID scene,bool intro_active,
                               const char *intro_music_path,const char *apartment_music_path,
                               bool *apartment_music_active){
    bool should_play_apartment=(!intro_active&&scene==SCENE_APARTMENT&&
                                apartment_music_path&&apartment_music_path[0]);
    if(intro_active&&intro_music_path&&intro_music_path[0]){
        if(*apartment_music_active) *apartment_music_active=false;
        return;
    }
    if(should_play_apartment){
        if(!*apartment_music_active){
            audio_set_music_override_volume(0.38f);
            audio_play_music_file(apartment_music_path,1800);
            *apartment_music_active=true;
        }
        return;
    }
    if(*apartment_music_active){
        audio_clear_music_override(1800);
        *apartment_music_active=false;
    }
}

static FrameHUDAPI frame_hud_api_make(void){
    FrameHUDAPI api={0};
    api.rect=pause_rect_cb;
    api.text=pause_text_cb;
    api.flush=pause_flush_cb;
    api.set_window_title=frame_set_title_cb;
    api.swap_window=frame_swap_cb;
    api.set_depth_test=frame_depth_cb;
    return api;
}

/* ── Boss System ─────────────────────────────────────────────── */
static float g_screen_shake=0.0f;   /* current shake magnitude, decays each frame */

/* Draw the boss health bar at top of screen */
/* ── Death Screen ─────────────────────────────────────────────
   Drawn whenever player.state==PS_DEAD.  Fades in over 1.5s,
   shows "YOU DIED", a stat summary, and a single respawn button.
   Returns true when the player clicks Respawn (caller resets).  */
static bool death_screen_draw(HUD *h, float *fade_t, float dt,
                              int win_w, int win_h,
                              float hp_max, int gold, int level,
                              int mx, int my){
    float W=(float)win_w, H=(float)win_h;

    /* Fade in from black — 1.5s */
    *fade_t=clampf(*fade_t+dt/1.5f, 0.0f, 1.0f);
    float a=*fade_t;

    /* Dark warm veil */
    hud_rect(h,0,0,W,H, 0.03f,0.015f,0.01f, a*0.88f);

    if(a<0.25f){hud_flush(h);menu_text_flush(h);return false;} /* wait before showing text */

    float ta=clampf((a-0.25f)/0.75f,0,1); /* text alpha lags vignette */

    float pw=520.0f,ph=230.0f,px=W*0.5f-pw*0.5f,py=H*0.26f;
    hud_manuscript_panel(h,px,py,pw,ph,ta);

    /* "YOU DIED" */
    const char *title="ASHEN RETURN";
    float tsc=3.1f, tw=tsc*8.0f*(float)strlen(title);
    float ty=py+38.0f;
    hud_str(h,px+20.0f,py+18.0f,0.92f,"[FALLEN IN BATTLE]",0.48f,0.52f,0.58f,0.88f*ta);
    hud_str(h,W*0.5f-tw*0.5f,ty,tsc,title, 0.90f,0.74f,0.38f,ta);

    /* Stat summary */
    char buf[128];
    float sy=ty+56.0f, ssc=1.2f;
    snprintf(buf,sizeof(buf),"Level %d   Max HP %.0f   Gold %d",level,(double)hp_max,gold);
    float sw=ssc*8.0f*(float)strlen(buf);
    hud_str(h,W*0.5f-sw*0.5f,sy,ssc,buf, 0.84f,0.80f,0.72f,ta*0.88f);

    /* Respawn button — only show once fully faded in */
    if(ta>=0.98f){
        float bw=280,bh=42,bx=W*0.5f-bw*0.5f,by=py+ph-62.0f;
        bool hov=(mx>=bx&&mx<=bx+bw&&my>=by&&my<=by+bh);
        hud_rect(h,bx,by,bw,bh, hov?0.18f:0.13f,hov?0.145f:0.11f,hov?0.09f:0.08f,0.96f);
        hud_rect(h,bx+14.0f,by+bh-10.0f,bw-28.0f,1.0f,0.78f,0.60f,0.18f,0.95f);
        const char *rlbl="RESPAWN AT CAMPFIRE";
        float rw=1.18f*8.0f*(float)strlen(rlbl);
        hud_str(h,bx+(bw-rw)*0.5f,by+12.0f,1.18f,rlbl,
                0.90f,0.78f,0.48f,1.0f);

        bool lmb=(SDL_GetMouseState(NULL,NULL)&SDL_BUTTON(1))!=0;
        if(lmb&&hov){hud_flush(h);menu_text_flush(h);return true;}
    }

    hud_flush(h);
    menu_text_flush(h);
    return false;
}

static void boss_hud_draw(HUD *h,Enemy *boss,int win_w,int win_h){
    if(!boss||!boss->active||boss->state==ES_DEAD)return;
    if(boss->etype!=ETYPE_BOSS||boss->boss_phase<1)return; /* not a real boss */
    float W=(float)win_w, H=(float)win_h;
    float bw=W*0.5f, bh=18.0f;
    float bx=W*0.25f, by=18.0f;
    float frac=clampf(boss->health/boss->max_health,0,1);

    /* Background */
    hud_rect(h,bx-2,by-2,bw+4,bh+4, 0,0,0,0.75f);
    /* Health fill — color shifts by phase */
    float r=0.05f,g2=0.75f,b2=0.85f;
    if(boss->boss_phase==2){r=0.6f;g2=0.1f;b2=0.8f;}
    if(boss->boss_phase==3){r=0.9f;g2=0.05f;b2=0.05f;}
    hud_rect(h,bx,by,bw*frac,bh, r,g2,b2,0.9f);
    /* Boss name */
    const char *phase_str[]={"","  [ENRAGED]","  [BERSERK]"};
    char buf[64];snprintf(buf,sizeof(buf),"Lich King%s",phase_str[boss->boss_phase-1]);
    float tw=strlen(buf)*6.0f*1.4f;
    hud_str(h,W*0.5f-tw*0.5f,by-14.0f,1.4f,buf, r+0.1f,g2+0.1f,b2+0.1f,1.0f);
    /* Phase flash overlay */
    if(boss->phase_flash&&boss->phase_flash_t>0){
        float a=boss->phase_flash_t*0.45f;
        hud_rect(h,0,0,W,H, r,g2*0.3f,b2*0.3f,a);
    }
    (void)H;
}

