static void main_input_on_controller_button_down(const SDL_ControllerButtonEvent *button,void *userdata){
    MainInputContext *ctx=(MainInputContext*)userdata;
    if(intro_sequence_handle_controller_button(ctx->intro,button->button)) return;
    if(g_pause.state==PM_OPTIONS) options_handle_pad_bind_capture_button((SDL_GameControllerButton)button->button);
}

static void main_input_on_left_mouse_down(int x,int y,void *userdata){
    MainInputContext *ctx=(MainInputContext*)userdata;
    if(intro_sequence_handle_mouse_button(ctx->intro,SDL_BUTTON_LEFT)) return;
    EditorRuntimeState *editor=ctx->editor;
    if(g_readable_prompt.open){
        (void)x;
        (void)y;
        return;
    }
    bool npc_dialogue_capture=(editor->npc_ed_dlg_mode&&editor->npc_ed_dlg_npc>=0);
    bool editor_camera_active=editor->editor_mode||editor->path_edit||editor->wzone_edit||editor->river_edit||
                             editor->prop_edit||editor->prop_place_mode||editor->particle_fx_edit||
                             editor->marker_edit||editor->forest_edit||editor->wind_edit||
                             editor->sculpt_edit||editor->npc_edit_mode||editor->spawn_edit_mode||
                             editor->mount_edit_mode;

    if(g_skilltree.open){
        skilltree_click(&g_skilltree,x,y,*ctx->win_w,*ctx->win_h,
                        ctx->player,ctx->as,ctx->lvlsys,ctx->inv,*ctx->base_max_hp,ctx->save_note);
        return;
    }
    if(g_player_appearance.open){
        if(appearance_save_button_hit(x,y,*ctx->win_w,*ctx->win_h)){
            appearance_stage_saved_from_current(&g_player_appearance);
            appearance_sync_render_state(&g_player_appearance);
            g_player_tint_enabled=true;
            g_player_appearance.open=false;
            save_notify(ctx->save_note,"Appearance saved");
            audio_play(SND_MENU_CLICK,80);
        }
        return;
    }
    if(ctx->inv->open){
        inv_click(ctx->inv,x,y,*ctx->win_w,*ctx->win_h,ctx->player,ctx->as,ctx->qs,
                  *ctx->base_max_hp,ctx->save_note);
        return;
    }
    if(ctx->npcs->open&&ctx->npcs->active_npc>=0&&ctx->npcs->talk_state==NPC_STATE_CHAT){
        NpcDef *_nc=&ctx->npcs->npcs[ctx->npcs->active_npc];
        if(_nc->dlg_root_id>=0&&_nc->dlg_cur_node>=0&&_nc->dlg_cur_node<g_dlg_count){
            DialogueNode *_dn2=&g_dlg_nodes[_nc->dlg_cur_node];
            if(_dn2->num_choices>0){
                float _px2,_py2,_pw2,_ph2,_text_y2,_cy2;
                npc_dialogue_layout(_dn2,*ctx->win_w,*ctx->win_h,&_px2,&_py2,&_pw2,&_ph2,&_text_y2,&_cy2);
                for(int _ci2=0;_ci2<_dn2->num_choices;_ci2++,_cy2+=28.0f){
                    if(x>=_px2+18.0f&&x<=_px2+_pw2-18.0f&&y>=_cy2&&y<=_cy2+24.0f){
                        npc_dlg_pick(ctx->npcs,_ci2,ctx->qs);
                        return;
                    }
                }
            }
        }
    }
    if(editor_camera_active) return;
    if(ctx->player->aiming&&ctx->player->class_id==PLAYER_CLASS_RANGER&&
       !npc_dialogue_capture&&!editor->prop_place_mode&&!editor->particle_fx_edit&&!editor->forest_edit&&!editor->marker_edit&&!editor->wind_edit&&
       ctx->player->state!=PS_DEAD&&ctx->player->state!=PS_MOUNTED&&ctx->player->state!=PS_ATTACK&&ctx->player->state!=PS_ATTACK2&&
       ctx->player->state!=PS_ROLL&&!ctx->fishing->active&&!ctx->cooking->active){
        ctx->player->state=PS_ATTACK2;
        ctx->player->anim_idx=ctx->player_amap->attack2;
        ctx->player->attack_timer=0;
        ctx->player->attack_hit=false;
        ctx->player->attack_ranged=true;
        ctx->player->anim_time=0;
        return;
    }
    if(!g_skilltree.open&&!npc_dialogue_capture&&!editor->prop_place_mode&&!editor->particle_fx_edit&&!editor->forest_edit&&!editor->marker_edit&&!editor->wind_edit&&
       ctx->player->state!=PS_DEAD&&ctx->player->state!=PS_MOUNTED&&ctx->player->state!=PS_ATTACK&&ctx->player->state!=PS_ATTACK2){
        ctx->player->state=PS_ATTACK;
        ctx->player->anim_idx=ctx->player_amap->attack;
        ctx->player->attack_timer=0;
        ctx->player->attack_hit=false;
        ctx->player->attack_ranged=false;
        ctx->player->anim_time=0;
        audio_play(SND_ATTACK,100);
    }
}

static void main_input_on_right_mouse_down(int x,int y,void *userdata){
    MainInputContext *ctx=(MainInputContext*)userdata;
    if(intro_sequence_handle_mouse_button(ctx->intro,SDL_BUTTON_RIGHT)) return;
    EditorRuntimeState *editor=ctx->editor;
    if(g_readable_prompt.open){
        (void)x;
        (void)y;
        return;
    }
    bool npc_dialogue_capture=(editor->npc_ed_dlg_mode&&editor->npc_ed_dlg_npc>=0);
    bool editor_camera_active=editor->editor_mode||editor->path_edit||editor->wzone_edit||editor->river_edit||
                             editor->prop_edit||editor->prop_place_mode||editor->particle_fx_edit||
                             editor->marker_edit||editor->forest_edit||editor->wind_edit||
                             editor->sculpt_edit||editor->npc_edit_mode||editor->spawn_edit_mode||
                             editor->mount_edit_mode;
    (void)x;
    (void)y;
    if(editor_camera_active) return;
    if(ctx->player->class_id!=PLAYER_CLASS_RANGER||ctx->player->state==PS_MOUNTED) return;
    if(g_skilltree.open||g_player_appearance.open||ctx->inv->open||ctx->map_screen->open||ctx->npcs->open||
       npc_dialogue_capture||editor->prop_place_mode||editor->particle_fx_edit||editor->forest_edit||editor->marker_edit||editor->wind_edit||
       ctx->fishing->active||ctx->cooking->active||ctx->player->state==PS_DEAD){
        return;
    }
    ctx->player->aiming=true;
}

static void main_input_on_right_mouse_up(int x,int y,void *userdata){
    MainInputContext *ctx=(MainInputContext*)userdata;
    if(intro_sequence_is_active(ctx->intro)) return;
    (void)x;
    (void)y;
    ctx->player->aiming=false;
}

