static void main_input_on_mouse_motion(const SDL_MouseMotionEvent *motion,bool right_drag,void *userdata){
    MainInputContext *ctx=(MainInputContext*)userdata;
    if(intro_sequence_is_active(ctx->intro)) return;
    EditorRuntimeState *editor=ctx->editor;
    bool editor_camera_active=editor->editor_mode||editor->path_edit||editor->wzone_edit||editor->river_edit||
                             editor->prop_edit||editor->prop_place_mode||editor->particle_fx_edit||
                             editor->marker_edit||editor->forest_edit||editor->wind_edit||
                             editor->sculpt_edit||editor->npc_edit_mode||editor->spawn_edit_mode||
                             editor->mount_edit_mode;
    if(ctx->map_screen->open&&(SDL_GetMouseState(NULL,NULL)&SDL_BUTTON(1))){
        float scale=WORLD_HALF*2.0f/ctx->map_screen->zoom/(float)(*ctx->win_w);
        ctx->map_screen->scroll_x-=motion->xrel*scale;
        ctx->map_screen->scroll_y-=motion->yrel*scale;
    } else if(editor_camera_active&&(SDL_GetMouseState(NULL,NULL)&SDL_BUTTON(SDL_BUTTON_MIDDLE))){
        float pan_scale=ctx->cam->dist*0.005f;
        Vec3 right=cam_right(ctx->cam);
        Vec3 forward=cam_forward(ctx->cam);
        editor->editor_cam_target.x-=right.x*(float)motion->xrel*pan_scale;
        editor->editor_cam_target.z-=right.z*(float)motion->xrel*pan_scale;
        editor->editor_cam_target.x+=forward.x*(float)motion->yrel*pan_scale;
        editor->editor_cam_target.z+=forward.z*(float)motion->yrel*pan_scale;
        editor->editor_cam_target.y=terrain_h(editor->editor_cam_target.x,editor->editor_cam_target.z);
    } else if(right_drag){
        float mouse_scale=0.005f*((float)g_options.mouse_sens/100.0f);
        float pitch_sign=g_options.invert_mouse_y?1.0f:-1.0f;
        ctx->cam->yaw-=motion->xrel*mouse_scale;
        ctx->cam->pitch=clampf(ctx->cam->pitch+motion->yrel*mouse_scale*pitch_sign,
                               editor_camera_active?0.10f:0.05f,
                               editor_camera_active?1.48f:1.3f);
    }
}

