    g_scene_surface_store_loaded[boot_scene]=true;
    collision_volumes_load(&g_collision_volumes);
    g_scene_collision_volume_store_loaded[boot_scene]=true;
    GrassSystem g_grass; grass_init(&g_grass);
    // Physical blade dimensions and distance LOD use the same default in play and the editor.
    g_grass.density_mul=1.0f;
    WaterInteraction g_wint; wint_init(&g_wint);
    PropList *shire_props=(boot_scene==SCENE_SHIRE)?&g_props:&g_scene_prop_store[SCENE_SHIRE];
    LOAD_STEP(&hud,win,"Building terrain...",++load_done,load_total);

    LOAD_STEP(&hud,win,"Initialising systems...",load_done,load_total);
    SkinProg   skin;     skinprog_init(&skin);
