            forest_init(&g_forest,fir?"models/silver_fir.glb":(chestnut?"models/chestnut.glb":"models/canopy_tree.glb"),
                        fir?"fir_billboard.png":(chestnut?"chestnut_billboard.png":tree_billboard_path));
