        wi_spawn(&world_items,ITEM_POTION_HP,  2,(Vec3){cf_wx+45,  terrain_h(cf_wx+45, cf_wz+18)+0.3f,   cf_wz+18});
        wi_spawn(&world_items,ITEM_GOLD_COIN,  8,(Vec3){cf_wx-30,  terrain_h(cf_wx-30, cf_wz-12)+0.3f,   cf_wz-12});
        wi_spawn(&world_items,ITEM_HELM_LEATHER,1,(Vec3){cf_wx+12, terrain_h(cf_wx+12, cf_wz+55)+0.3f,   cf_wz+55});

        /* Forest edge — mid loot */
        wi_spawn(&world_items,ITEM_POTION_HP,  3,(Vec3){cf_wx+150, terrain_h(cf_wx+150,cf_wz-60)+0.3f,   cf_wz-60});
        wi_spawn(&world_items,ITEM_CHEST_LEATHER,1,(Vec3){cf_wx+200,terrain_h(cf_wx+200,cf_wz+30)+0.3f,  cf_wz+30});
        wi_spawn(&world_items,ITEM_GOLD_COIN, 15,(Vec3){cf_wx+90,  terrain_h(cf_wx+90, cf_wz-180)+0.3f,  cf_wz-180});

        /* Bandit rise — harder starter-area loop, better rewards */
        wi_spawn(&world_items,ITEM_SWORD_STEEL, 1,(Vec3){cf_wx+210, terrain_h(cf_wx+210, cf_wz-250)+0.3f, cf_wz-250});
        wi_spawn(&world_items,ITEM_POTION_FULL, 2,(Vec3){cf_wx+265, terrain_h(cf_wx+265, cf_wz-185)+0.3f, cf_wz-185});
        wi_spawn(&world_items,ITEM_BOOTS_LEATHER,1,(Vec3){cf_wx+180,terrain_h(cf_wx+180,cf_wz-165)+0.3f,  cf_wz-165});
        wi_spawn(&world_items,ITEM_GOLD_COIN,  30,(Vec3){cf_wx+300, terrain_h(cf_wx+300,cf_wz-235)+0.3f,  cf_wz-235});

        /* River overlook cache */
        wi_spawn(&world_items,ITEM_CHEST_IRON,  1,(Vec3){cf_wx-35, terrain_h(cf_wx-35, cf_wz+205)+0.3f,   cf_wz+205});
        wi_spawn(&world_items,ITEM_HELM_IRON,   1,(Vec3){cf_wx-80, terrain_h(cf_wx-80, cf_wz+170)+0.3f,   cf_wz+170});
        wi_spawn(&world_items,ITEM_POTION_FULL, 3,(Vec3){cf_wx+5,  terrain_h(cf_wx+5,  cf_wz+235)+0.3f,   cf_wz+235});
